const n=1,e=JSON.parse('[{"id":"chem.applications.evaluation.exercise.1","title":"Sach- oder Werturteil?","difficulty":"basic","prompt":"Ordne die Aussagen den Begriffen Sachaussage und Wertentscheidung zu: (a) Verfahren A benötigt 20 % weniger Energie als Verfahren B. (b) Energieeinsparung ist wichtiger als niedrige Kosten. (c) Für Verfahren A wird ein seltenes Metall als Katalysator benötigt.","taskType":"matching","afb":2,"supportedModes":["screen"],"hints":["Eine Sachaussage lässt sich mit Daten prüfen."],"solution":"(a) Sachaussage. (b) Wertentscheidung. (c) Sachaussage.","competencies":["B"],"operators":["zuordnen"],"sourceLessonId":"chem.applications.evaluation","sourceKind":"exercise","answer":{"kind":"matching","options":["Sachaussage","Wertentscheidung"],"items":[{"id":"a","label":"(a) Verfahren A benötigt 20 % weniger Energie.","correct":"Sachaussage"},{"id":"b","label":"(b) Energieeinsparung ist wichtiger als niedrige Kosten.","correct":"Wertentscheidung"},{"id":"c","label":"(c) Für Verfahren A wird ein seltenes Metall benötigt.","correct":"Sachaussage"}]}},{"id":"chem.applications.evaluation.exercise.2","title":"Relative Änderung berechnen","difficulty":"basic","prompt":"Der Energiebedarf eines Verfahrens sinkt durch einen neuen Katalysator von 250 kJ auf 200 kJ pro Kilogramm Produkt. Berechne die relative Änderung.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["relative Änderung = (Endwert − Anfangswert) / Anfangswert · 100 %"],"solution":"(200 kJ − 250 kJ) / 250 kJ · 100 % = −20 %. Der Energiebedarf sinkt um 20 %.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.applications.evaluation","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"change","label":"Relative Änderung","value":-20,"unit":"%","tolerance":{"absolute":0.5}}]}},{"id":"chem.applications.evaluation.exercise.3","title":"Kriterien festlegen","difficulty":"standard","prompt":"Zwei Enteisungsmittel für Gehwege sollen verglichen werden: Natriumchlorid und Calciummagnesiumacetat. Nenne vier Bewertungskriterien und gib zu jedem eine messbare Größe an.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Denke an Wirkung, Umwelt, Material und Kosten."],"solution":"Zum Beispiel: Wirksamkeit, gemessen als tiefste Temperatur, bei der noch Eis geschmolzen wird; Umweltwirkung, gemessen als Chloridbelastung von Boden und Gewässern; Korrosion, gemessen als Masseverlust von Stahlproben; Kosten, gemessen in Euro pro behandelter Fläche. Andere begründete Kriterien sind ebenfalls möglich.","competencies":["B"],"operators":["nennen","angeben"],"sourceLessonId":"chem.applications.evaluation","sourceKind":"exercise"},{"id":"chem.applications.evaluation.exercise.4","title":"Gleiche Bezugsgröße","difficulty":"standard","prompt":"Waschmittel A enthält 2,0 % Phosphonat und wird mit 75 g pro Waschgang dosiert, Waschmittel B enthält 2,5 % und wird mit 50 g dosiert. Berechne die Phosphonatmasse pro Waschgang und begründe, welche Bezugsgröße für den Vergleich sinnvoll ist.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["Vergleiche, was tatsächlich pro Anwendung ins Abwasser gelangt."],"solution":"A: 75 g · 0,020 = 1,5 g pro Waschgang. B: 50 g · 0,025 = 1,25 g pro Waschgang. Obwohl B den höheren Massenanteil hat, gelangt pro Waschgang weniger Phosphonat ins Abwasser. Sinnvoll ist die Bezugsgröße pro Waschgang, weil sie die gleiche Funktion beider Produkte vergleicht.","competencies":["S","B"],"operators":["berechnen","begründen"],"sourceLessonId":"chem.applications.evaluation","sourceKind":"exercise"},{"id":"chem.applications.evaluation.exercise.5","title":"Platin- oder Eisenkatalysator","difficulty":"transfer","prompt":"Für einen Prozess stehen ein Platinkatalysator mit hoher Aktivität und ein weniger aktiver Eisenkatalysator zur Wahl. Bewerte die Wahl, indem du einen Zielkonflikt benennst und beschreibst, welche Daten für eine Entscheidung nötig sind.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Platin ist selten und teuer.","Höhere Aktivität kann Energie und Zeit sparen."],"solution":"Zielkonflikt: Der Platinkatalysator erlaubt höhere Umsätze oder niedrigere Temperaturen und spart Energie, Platin ist aber selten, teuer und mit belastendem Bergbau verbunden. Eisen ist häufig und günstig, benötigt aber möglicherweise mehr Energie. Für eine Entscheidung braucht man vergleichbare Daten zu Energiebedarf pro Produktmenge, Lebensdauer und Rückgewinnbarkeit des Katalysators, Kosten sowie Umweltfolgen der Rohstoffgewinnung. Das Ergebnis hängt außerdem davon ab, wie diese Kriterien gewichtet werden.","competencies":["B"],"operators":["bewerten"],"sourceLessonId":"chem.applications.evaluation","sourceKind":"exercise"},{"id":"chem.applications.evaluation.exercise.6","title":"Grenzwert und Messunsicherheit","difficulty":"transfer","prompt":"Für einen Schadstoff im Trinkwasser gilt ein Grenzwert von 0,50 mg·L⁻¹. Eine Messung ergibt 0,48 mg·L⁻¹ mit einer Messunsicherheit von ±0,05 mg·L⁻¹. Beurteile die Aussage „Der Grenzwert wird sicher eingehalten.“","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Bestimme den Bereich, in dem der wahre Wert liegen kann."],"solution":"Der wahre Wert liegt zwischen 0,43 und 0,53 mg·L⁻¹. Dieser Bereich schließt Werte oberhalb des Grenzwerts ein. Die Aussage „sicher eingehalten“ ist daher nicht gerechtfertigt. Zulässig ist: Der Messwert liegt unter dem Grenzwert, eine Überschreitung ist aber im Rahmen der Unsicherheit nicht ausgeschlossen. Wiederholungsmessungen oder ein genaueres Verfahren würden die Aussage absichern.","competencies":["E","B"],"operators":["beurteilen"],"sourceLessonId":"chem.applications.evaluation","sourceKind":"exercise"},{"id":"chem.applications.evaluation.selftest.1","title":"Sachurteil und Werturteil","difficulty":"basic","prompt":"Worin unterscheidet sich ein Sachurteil von einer Wertentscheidung?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Nur eines lässt sich mit Daten überprüfen."],"solution":"Ein Sachurteil beruht auf überprüfbaren Daten und Fachwissen. Eine Wertentscheidung legt fest, welche Kriterien wichtiger sind, und hängt von Werten und Zielen ab.","competencies":["B"],"operators":["unterscheiden"],"sourceLessonId":"chem.applications.evaluation","sourceKind":"selfTest"},{"id":"chem.applications.evaluation.selftest.2","title":"Gleiche Bezugsbasis","difficulty":"basic","prompt":"Warum müssen Daten zweier Verfahren auf dieselbe Bezugsgröße umgerechnet werden?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Denke an verschiedene Produktmengen."],"solution":"Nur dann vergleichen sie dieselbe Leistung, etwa dieselbe Produktmenge oder denselben Nutzen; sonst kann ein Verfahren nur scheinbar besser abschneiden.","competencies":["B"],"operators":["begründen"],"sourceLessonId":"chem.applications.evaluation","sourceKind":"selfTest"},{"id":"chem.applications.evaluation.selftest.3","title":"Zielkonflikt","difficulty":"basic","prompt":"Was ist ein Zielkonflikt bei einer Bewertung?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Zwei Kriterien zeigen in unterschiedliche Richtungen."],"solution":"Eine Situation, in der eine Option bei einem Kriterium besser und bei einem anderen schlechter abschneidet, sodass nicht alle Ziele zugleich erreicht werden.","competencies":["B"],"operators":["angeben"],"sourceLessonId":"chem.applications.evaluation","sourceKind":"selfTest"},{"id":"chem.basics.data.exercise.basic-axes","title":"Achsen prüfen","difficulty":"basic","prompt":"Die Abbildung zeigt die Temperatur einer Reaktionsmischung in °C gegen die Zeit in Sekunden; die Achsenbeschriftungen fehlen noch. Was muss in einer vollständigen Achsenbeschriftung stehen und warum ist die Einheit wichtig?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Nenne die dargestellte Größe und Einheit auf beiden Achsen.","Einheiten machen Messwerte eindeutig und vergleichbar."],"solution":"Die x-Achse muss Zeit t in s, die y-Achse Temperatur ϑ in °C angeben. Ohne Größen und Einheiten lassen sich Werte nicht eindeutig lesen oder vergleichen.","competencies":["E","K"],"operators":["angeben","begründen"],"sourceLessonId":"chem.basics.data","sourceKind":"exercise","figures":[{"file":"temperature-unlabeled.svg","alt":"Diagramm ohne Achsenbeschriftung: Eine Kurve steigt zunächst an, erreicht ein Maximum und fällt dann langsam ab. An beiden Achsen steht ein Fragezeichen.","placement":"prompt"}]},{"id":"chem.basics.data.exercise.basic-trend","title":"Trend beschreiben","difficulty":"basic","prompt":"Die Konzentration eines Edukts sinkt in einer Messreihe stetig. Formuliere eine Beschreibung des Trends, ohne bereits eine Ursache zu behaupten.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Beschreibe Richtung und Verlauf.","Vermeide eine Erklärung, die nicht aus den Messdaten folgt."],"solution":"Die gemessene Eduktkonzentration nimmt im betrachteten Zeitraum stetig ab. Aus dieser Beobachtung allein folgt noch keine Ursache der Abnahme.","competencies":["K"],"operators":["beschreiben"],"sourceLessonId":"chem.basics.data","sourceKind":"exercise"},{"id":"chem.basics.data.exercise.standard-rate","title":"Mittlere Abnahmegeschwindigkeit","difficulty":"standard","prompt":"Die Konzentration von H₂O₂ sinkt von 0,80 mol·L⁻¹ auf 0,50 mol·L⁻¹ innerhalb von 60 s. Berechne die mittlere Abnahmegeschwindigkeit der H₂O₂-Konzentration.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Berechne Δc = c₂ − c₁.","Für eine positive Abnahmegeschwindigkeit nutzt du −Δc/Δt."],"solution":"Δc = 0,50 − 0,80 = −0,30 mol·L⁻¹. Daher ist vₐᵦₙ = −(−0,30)/60 = 0,0050 mol·L⁻¹·s⁻¹. Das ist die mittlere Abnahmegeschwindigkeit von H₂O₂, nicht automatisch die stöchiometrisch normierte Reaktionsgeschwindigkeit.","competencies":["S","E"],"operators":["berechnen","angeben"],"sourceLessonId":"chem.basics.data","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"rate","label":"Mittlere Abnahmegeschwindigkeit","value":0.005,"unit":"mol·L⁻¹·s⁻¹"}]}},{"id":"chem.basics.data.exercise.standard-intervals","title":"Zwei Intervalle vergleichen","difficulty":"standard","prompt":"Eine Produktkonzentration steigt von 0,10 auf 0,30 mol·L⁻¹ in 20 s und danach auf 0,50 mol·L⁻¹ in 40 s. Vergleiche die mittleren Bildungsgeschwindigkeiten.","taskType":"structured","afb":2,"supportedModes":["screen"],"hints":["Berechne Δc/Δt getrennt für beide Intervalle.","Beachte, dass die Intervalle unterschiedlich lang sind."],"solution":"Im ersten Intervall: (0,30−0,10)/20 = 0,010 mol·L⁻¹·s⁻¹. Im zweiten: (0,50−0,30)/40 = 0,0050 mol·L⁻¹·s⁻¹. Die Konzentration steigt im zweiten Intervall halb so schnell.","competencies":["S","E","K"],"operators":["berechnen","vergleichen","beschreiben"],"sourceLessonId":"chem.basics.data","sourceKind":"exercise"},{"id":"chem.basics.data.exercise.transfer-equilibrium","title":"Hypothese mit Daten prüfen","difficulty":"transfer","prompt":"Zwei Versuchsreihen untersuchen dieselbe Reaktion bei unterschiedlicher Temperatur. Bei höherer Temperatur steigt die Produktkonzentration in den ersten 30 s schneller. Beurteile: „Die höhere Temperatur erhöht die Gleichgewichtsausbeute.“","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Unterscheide Reaktionsgeschwindigkeit und spätere Gleichgewichtskonzentration.","Prüfe, ob die Daten überhaupt einen Gleichgewichtszustand zeigen."],"solution":"Die Daten stützen, dass das Produkt bei höherer Temperatur in den ersten 30 s schneller entsteht. Sie belegen keine höhere Gleichgewichtsausbeute, solange die Endkonzentrationen im Gleichgewicht nicht verglichen werden. Geschwindigkeit und Gleichgewichtslage sind verschiedene Aussagen.","competencies":["E","B"],"operators":["beurteilen","begründen"],"sourceLessonId":"chem.basics.data","sourceKind":"exercise"},{"id":"chem.basics.data.exercise.transfer-uncertainty","title":"Messunsicherheit beachten","difficulty":"transfer","prompt":"Zwei Messwerte betragen 0,51 mol·L⁻¹ und 0,52 mol·L⁻¹. Für beide gilt eine Messunsicherheit von ±0,03 mol·L⁻¹. Kannst du sicher folgern, dass der zweite Wert größer ist? Begründe.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Vergleiche die Unsicherheitsbereiche.","Trenne eine kleine Zahlenabweichung von einem belastbaren Unterschied."],"solution":"Nein. Die Unsicherheitsbereiche sind 0,48–0,54 mol·L⁻¹ und 0,49–0,55 mol·L⁻¹; sie überlappen deutlich. Der Unterschied von 0,01 mol·L⁻¹ ist kleiner als die angegebene Unsicherheit. Die Messwerte belegen daher keine sichere Zunahme.","competencies":["E","B"],"operators":["beurteilen","begründen"],"sourceLessonId":"chem.basics.data","sourceKind":"exercise"},{"id":"chem.basics.data.selftest.rate","title":"Mittlere Änderungsrate","difficulty":"basic","prompt":"Wie berechnest du die mittlere Änderungsrate zwischen zwei Messpunkten?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Bilde die Differenz der Messgröße und teile durch die Zeitdifferenz."],"solution":"v̄ = Δy/Δt.","competencies":["E"],"operators":["angeben"],"sourceLessonId":"chem.basics.data","sourceKind":"selfTest"},{"id":"chem.basics.data.selftest.equilibrium","title":"Plateau und Gleichgewicht","difficulty":"basic","prompt":"Beweist ein Konzentrationsplateau allein ein chemisches Gleichgewicht?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Prüfe, ob weitere Erklärungen möglich sind."],"solution":"Nein. Ein Plateau kann mit einem dynamischen Gleichgewicht vereinbar sein, beweist es allein aber nicht.","competencies":["E"],"operators":["angeben"],"sourceLessonId":"chem.basics.data","sourceKind":"selfTest"},{"id":"chem.basics.data.selftest.uncertainty","title":"Kleine Messunterschiede","difficulty":"basic","prompt":"Was solltest du prüfen, bevor du kleine Unterschiede zwischen Messwerten deutest?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Berücksichtige die angegebene Genauigkeit."],"solution":"Vergleiche den Unterschied mit den Messunsicherheiten. Überlappende Unsicherheitsbereiche belegen keinen sicheren Unterschied.","competencies":["E"],"operators":["angeben"],"sourceLessonId":"chem.basics.data","sourceKind":"selfTest"},{"id":"chem.basics.quantities.exercise.basic-mole","title":"Stoffmenge berechnen","difficulty":"basic","prompt":"Eine Probe enthält 9,00 g Wasser. Berechne die Stoffmenge. Verwende M(H₂O) = 18,0 g·mol⁻¹.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Nutze n = m/M.","Setze Masse und molare Masse mit Einheiten ein."],"solution":"n = 9,00 g / 18,0 g·mol⁻¹ = 0,500 mol Wasser.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.basics.quantities","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"n","label":"Stoffmenge n(H₂O)","value":0.5,"unit":"mol"}]}},{"id":"chem.basics.quantities.exercise.basic-concentration","title":"Stoffmengenkonzentration berechnen","difficulty":"basic","prompt":"0,0200 mol Natriumchlorid werden zu 0,500 L Lösung verarbeitet. Berechne die Stoffmengenkonzentration.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Verwende c = n/V.","Setze das Volumen in Litern ein."],"solution":"c = 0,0200 mol / 0,500 L = 0,0400 mol·L⁻¹.","competencies":["S"],"operators":["berechnen","angeben"],"sourceLessonId":"chem.basics.quantities","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"c","label":"Stoffmengenkonzentration","value":0.04,"unit":"mol·L⁻¹"}]}},{"id":"chem.basics.quantities.exercise.standard-limiting","title":"Limitierendes Edukt","difficulty":"standard","prompt":"Für N₂ + 3 H₂ → 2 NH₃ stehen 0,40 mol N₂ und 0,90 mol H₂ bereit. Welcher Stoff ist limitierend und welche Stoffmenge NH₃ kann höchstens entstehen?","taskType":"structured","afb":2,"supportedModes":["screen"],"hints":["Berechne, wie viel H₂ für 0,40 mol N₂ benötigt würde.","Vergleiche den Bedarf mit der vorhandenen H₂-Menge."],"solution":"0,40 mol N₂ benötigen 1,20 mol H₂. Vorhanden sind nur 0,90 mol; H₂ ist limitierend. Aus 3 mol H₂ entstehen 2 mol NH₃: n(NH₃) = 0,90 · 2/3 = 0,60 mol.","competencies":["S","E"],"operators":["ermitteln","berechnen"],"sourceLessonId":"chem.basics.quantities","sourceKind":"exercise"},{"id":"chem.basics.quantities.exercise.standard-dilution","title":"Verdünnung berechnen","difficulty":"standard","prompt":"25,0 mL einer 0,200 mol·L⁻¹ Lösung werden auf 100,0 mL aufgefüllt. Berechne die Endkonzentration.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Beim Verdünnen bleibt die Stoffmenge des gelösten Stoffes gleich.","Nutze c₁V₁ = c₂V₂."],"solution":"c₂ = c₁V₁/V₂ = 0,200 mol·L⁻¹ · 25,0 mL / 100,0 mL = 0,0500 mol·L⁻¹. Die Volumeneinheiten kürzen sich, weil beide in mL angegeben sind.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.basics.quantities","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"c2","label":"Endkonzentration","value":0.05,"unit":"mol·L⁻¹"}]}},{"id":"chem.basics.quantities.exercise.transfer-gas","title":"Gasvolumen im Kontext","difficulty":"transfer","prompt":"Bei Raumtemperatur werden 0,0150 mol eines idealen Gases erzeugt. Berechne das Volumen bei T = 298 K und p = 100 kPa. Verwende R = 8,314 kPa·L·mol⁻¹·K⁻¹.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Nutze pV = nRT und stelle nach V um.","Achte darauf, dass die Einheit von R zum Druck passt."],"solution":"V = nRT/p = (0,0150 mol · 8,314 kPa·L·mol⁻¹·K⁻¹ · 298 K)/(100 kPa) = 0,372 L (drei signifikante Stellen).","competencies":["S","E"],"operators":["berechnen","angeben"],"sourceLessonId":"chem.basics.quantities","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"V","label":"Volumen","value":0.372,"unit":"L"}]}},{"id":"chem.basics.quantities.exercise.transfer-dose","title":"Konzentration und Dosis","difficulty":"transfer","prompt":"Eine Lösung enthält 0,030 mol Wirkstoff in 150 mL. Berechne die Stoffmengenkonzentration. Erkläre, warum dieser Wert allein keine sichere Dosis angibt.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["Wandle 150 mL in Liter um.","Konzentration beschreibt Stoffmenge pro Volumen, nicht aufgenommene Gesamtmenge oder Wirkung."],"solution":"V = 0,150 L. c = 0,030 mol / 0,150 L = 0,20 mol·L⁻¹. Die Konzentration allein nennt weder das getrunkene Volumen noch Körpermasse, Aufnahme oder toxikologische Wirkung. Eine sichere Dosis lässt sich daraus nicht beurteilen.","competencies":["S","B"],"operators":["berechnen","beurteilen"],"sourceLessonId":"chem.basics.quantities","sourceKind":"exercise"},{"id":"chem.basics.quantities.selftest.molar","title":"Stoffmenge aus der Masse","difficulty":"basic","prompt":"Wie berechnest du die Stoffmenge n aus Masse m und molarer Masse M?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Gesucht ist die Stoffmenge."],"solution":"n = m/M.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.basics.quantities","sourceKind":"selfTest"},{"id":"chem.basics.quantities.selftest.concentration","title":"Stoffmengenkonzentration","difficulty":"basic","prompt":"Was beschreibt die Stoffmengenkonzentration?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie setzt Stoffmenge und Lösungsvolumen ins Verhältnis."],"solution":"Sie gibt die Stoffmenge pro Volumen an: c = n/V.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.basics.quantities","sourceKind":"selfTest"},{"id":"chem.basics.quantities.selftest.limiting","title":"Limitierender Stoff","difficulty":"basic","prompt":"Welcher Stoff begrenzt die theoretische Produktmenge?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Prüfe das Stoffmengenverhältnis aus der ausgeglichenen Reaktionsgleichung."],"solution":"Das limitierende Edukt, das entsprechend der Reaktionsgleichung zuerst verbraucht wird.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.basics.quantities","sourceKind":"selfTest"},{"id":"chem.basics.representation.exercise.basic-levels","title":"Drei Beschreibungsebenen","difficulty":"basic","prompt":"Ordne zu und benenne jeweils die Ebene: (a) Eine Kupfersulfatlösung ist blau. (b) In der Lösung liegen hydratisierte Cu²⁺- und SO₄²⁻-Ionen vor. (c) CuSO₄(s) → Cu²⁺(aq) + SO₄²⁻(aq).","taskType":"structured","afb":2,"supportedModes":["screen"],"hints":["Frage dich, ob eine direkt beobachtbare Eigenschaft, ein Teilchenbild oder eine Symbolschreibweise beschrieben wird."],"solution":"(a) Stoffebene: Die Farbe ist beobachtbar. (b) Teilchenebene: Ionen und ihre Umgebung werden modellhaft beschrieben. (c) Symbolebene: Die Dissoziation ist als Gleichung notiert.","competencies":["S","K"],"operators":["zuordnen","benennen"],"sourceLessonId":"chem.basics.representation","sourceKind":"exercise"},{"id":"chem.basics.representation.exercise.basic-balance","title":"Knallgasreaktion ausgleichen","difficulty":"basic","prompt":"Gleiche H₂ + O₂ → H₂O aus. Prüfe danach die Zahl der H- und O-Atome auf beiden Seiten.","taskType":"free-response","afb":1,"supportedModes":["screen","handwriting"],"hints":["Ändere nur Koeffizienten vor den Formeln, nicht tiefgestellte Zahlen.","Gleiche zuerst Sauerstoff, dann Wasserstoff aus."],"solution":"2 H₂ + O₂ → 2 H₂O. Links und rechts liegen jeweils vier H-Atome und zwei O-Atome vor.","competencies":["S","K"],"operators":["ausgleichen","überprüfen"],"sourceLessonId":"chem.basics.representation","sourceKind":"exercise"},{"id":"chem.basics.representation.exercise.standard-zinc","title":"Beobachtung und Modell verknüpfen","difficulty":"standard","prompt":"Zink reagiert mit Salzsäure. Es entstehen Gasbläschen und die Zinkoberfläche wird kleiner. Beschreibe die Beobachtung, formuliere eine Reaktionsgleichung und erkläre ihre Aussage.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Trenne die beobachtbare Veränderung von der Teilchenerklärung.","Chlorid-Ionen sind Zuschauerionen, wenn du die Nettogleichung formulierst."],"solution":"Beobachtung: Zink wird verbraucht, Gasbläschen entstehen. Stoffgleichung: Zn(s) + 2 HCl(aq) → ZnCl₂(aq) + H₂(g). Nettogleichung: Zn(s) + 2 H⁺(aq) → Zn²⁺(aq) + H₂(g). Die Nettogleichung zeigt die Teilchen, die sich tatsächlich ändern; Chlorid-Ionen reagieren nicht mit.","competencies":["S","K"],"operators":["beschreiben","formulieren","erläutern"],"sourceLessonId":"chem.basics.representation","sourceKind":"exercise"},{"id":"chem.basics.representation.exercise.standard-structure","title":"Passende Darstellung wählen","difficulty":"standard","prompt":"Eine Aufgabe fragt nach der räumlichen Anordnung der Atome im Wassermolekül. Welche Darstellung ist geeigneter: Summenformel H₂O oder Lewis-Modell? Begründe und nenne eine Grenze der gewählten Darstellung.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Überlege, welche Information die Summenformel liefert und welche das Lewis-Modell zusätzlich zeigt."],"solution":"Das Lewis-Modell ist geeigneter, weil es bindende und freie Elektronenpaare darstellt und so die gewinkelte Struktur erklären hilft. Es bleibt eine zweidimensionale Modellzeichnung und zeigt weder Bindungslängen noch die Elektronenverteilung exakt.","competencies":["S","E"],"operators":["begründen","beurteilen"],"sourceLessonId":"chem.basics.representation","sourceKind":"exercise"},{"id":"chem.basics.representation.exercise.transfer-model","title":"Modellgrenze beurteilen","difficulty":"transfer","prompt":"Ein Teilchenbild zeigt alle gelösten Teilchen gleich groß und unbewegt. Beurteile, welche Aussagen sich daraus ableiten lassen und welche nicht.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Unterscheide qualitative Aussagen über Teilchenarten von Aussagen über Größe oder Bewegung.","Beziehe die Modellannahmen in dein Urteil ein."],"solution":"Das Bild kann qualitativ zeigen, welche Teilchenarten vorhanden sind und wie sie verteilt sind. Es belegt nicht, dass Teilchen gleich groß oder unbeweglich sind. Das sind Darstellungsvereinfachungen. Für Aussagen zur Bewegung brauchst du ein dynamisches Modell oder Messdaten.","competencies":["E","B","K"],"operators":["beurteilen","begründen"],"sourceLessonId":"chem.basics.representation","sourceKind":"exercise"},{"id":"chem.basics.representation.exercise.transfer-charge","title":"Aluminiumchlorid-Gleichung entwickeln","difficulty":"transfer","prompt":"Aluminium reagiert mit Chlor zu Aluminiumchlorid. Entwickle eine ausgeglichene Reaktionsgleichung und erkläre, wie du Atome und Ladung überprüfst.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Stelle zuerst Formeln der Elemente und des Ionenstoffs auf.","Gleiche dann die Atome mit Koeffizienten aus."],"solution":"2 Al(s) + 3 Cl₂(g) → 2 AlCl₃(s). Links und rechts stehen zwei Al-Atome und sechs Cl-Atome. Die Atome sind erhalten. Alle Stoffe sind insgesamt neutral, daher stimmt auch die Ladungsbilanz.","competencies":["S","E"],"operators":["entwickeln","überprüfen"],"sourceLessonId":"chem.basics.representation","sourceKind":"exercise"},{"id":"chem.basics.representation.selftest.levels","title":"Beschreibungsebenen","difficulty":"basic","prompt":"Welche drei Beschreibungsebenen nutzt die Chemie?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Eine Ebene beschreibt Beobachtungen, eine Teilchen und eine Symbole."],"solution":"Stoffebene, Teilchenebene und Symbolebene.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.basics.representation","sourceKind":"selfTest"},{"id":"chem.basics.representation.selftest.coefficient","title":"Gleichungen ausgleichen","difficulty":"basic","prompt":"Was darfst du beim Ausgleichen einer Reaktionsgleichung verändern?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Verändere die Zahl vor der Formel, nicht deren Index."],"solution":"Du veränderst Koeffizienten vor Formeln. Tiefgestellte Indizes bleiben unverändert.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.basics.representation","sourceKind":"selfTest"},{"id":"chem.basics.representation.selftest.model","title":"Gleichung und Mechanismus","difficulty":"basic","prompt":"Warum ist eine Reaktionsgleichung kein vollständiger Mechanismus?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Sie zeigt die Gesamtbilanz."],"solution":"Sie zeigt Ausgangs- und Endstoffe sowie die Stoffbilanz, aber nicht alle Reaktionsschritte oder Teilchenbewegungen.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.basics.representation","sourceKind":"selfTest"},{"id":"chem.q1.1.bonding.exercise.basic-bond","title":"Bindungsmodell zuordnen","difficulty":"basic","prompt":"Ordne den Stoffen NaCl(s), Cl₂(g) und Cu(s) das jeweils passende Bindungsmodell im Feststoff bzw. Molekül zu.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Frage, ob Ionen, Nichtmetallatome oder Metallatome die Bausteine bilden."],"solution":"NaCl(s) bildet ein Ionengitter mit Ionenbindung. Cl₂(g) besteht aus Molekülen mit einer Elektronenpaarbindung zwischen zwei Cl-Atomen. Cu(s) besitzt metallische Bindung zwischen Atomrümpfen und delokalisierten Elektronen.","competencies":["S"],"operators":["zuordnen","beschreiben"],"sourceLessonId":"chem.q1.1.bonding","sourceKind":"exercise"},{"id":"chem.q1.1.bonding.exercise.basic-lewis","title":"Lewis-Formel von HCl","difficulty":"basic","prompt":"Zeichne die Lewis-Formel des Chlorwasserstoffmoleküls HCl.","taskType":"free-response","afb":1,"supportedModes":["handwriting"],"hints":["H benötigt eine gemeinsame Elektronenpaarbindung, um die Duettregel zu erfüllen.","Cl besitzt sieben Valenzelektronen."],"solution":"H–Cl. Das gemeinsame Elektronenpaar bildet die Bindung. Am Chlor verbleiben drei freie Elektronenpaare.","competencies":["S","K"],"operators":["zeichnen"],"sourceLessonId":"chem.q1.1.bonding","sourceKind":"exercise","figures":[{"file":"lewis-hcl.svg","alt":"Lewis-Formel H–Cl: ein Bindungsstrich zwischen H und Cl, am Chlor drei freie Elektronenpaare oben, unten und rechts.","caption":"Lewis-Formel von HCl; freie Elektronenpaare sind als Striche dargestellt.","placement":"solution"}]},{"id":"chem.q1.1.bonding.exercise.standard-electronegativity","title":"Bindungspolarität erklären","difficulty":"standard","prompt":"Die Elektronegativität beträgt für H etwa 2,2 und für Cl etwa 3,2. Ordne die H–Cl-Bindung ein und markiere die Partialladungen.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Das elektronegativere Atom zieht das Bindungselektronenpaar stärker an.","Unterscheide Partialladung von einer Ionenladung."],"solution":"Die Elektronegativitätsdifferenz beträgt ungefähr 1,0. Das Bindungselektronenpaar ist zu Cl verschoben. H trägt δ⁺, Cl δ⁻. Die H–Cl-Bindung ist polar kovalent, aber die Partialladungen bedeuten keine vollständige Elektronenübertragung wie bei einem Ionengitter.","competencies":["S","E"],"operators":["einordnen","begründen"],"sourceLessonId":"chem.q1.1.bonding","sourceKind":"exercise"},{"id":"chem.q1.1.bonding.exercise.standard-properties","title":"Leitfähigkeit von NaCl und Kupfer","difficulty":"standard","prompt":"Natriumchlorid und Kupfer leiten als Feststoffe unterschiedlich gut Strom. Erkläre den Unterschied mit den jeweiligen Bindungsmodellen.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Welche geladenen Teilchen sind im Feststoff beweglich?","Vergleiche Metallbindung mit einem Ionengitter."],"solution":"Im Kupfer sind Elektronen delokalisiert und im Metallgitter beweglich. Daher leitet festes Kupfer Strom. Im festen NaCl sind die Ionen an Gitterplätze gebunden; sie können sich nicht frei durch den Feststoff bewegen. Eine NaCl-Schmelze oder Lösung leitet, weil Ionen dann beweglich sind.","competencies":["S","E"],"operators":["erläutern","vergleichen"],"sourceLessonId":"chem.q1.1.bonding","sourceKind":"exercise"},{"id":"chem.q1.1.bonding.exercise.transfer-charge","title":"Ionenformel entwickeln","difficulty":"transfer","prompt":"Leite aus den Ionen Na⁺ und O²⁻ die elektrisch neutrale Verhältnisformel ab. Erkläre deine Ladungsbilanz.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die Gesamtladung der Formeleinheit muss null ergeben.","Finde das kleinste ganzzahlige Verhältnis, das + und − ausgleicht."],"solution":"Zwei Na⁺-Ionen liefern zusammen +2; ein O²⁻-Ion liefert −2. Die Ladungen gleichen sich im Verhältnis 2:1 aus. Die Verhältnisformel lautet Na₂O.","competencies":["S","E"],"operators":["entwickeln","begründen"],"sourceLessonId":"chem.q1.1.bonding","sourceKind":"exercise"},{"id":"chem.q1.1.bonding.exercise.transfer-model","title":"Elektronengasmodell prüfen","difficulty":"transfer","prompt":"Die Abbildung zeigt ein Modell eines Metallgitters mit positiven Atomrümpfen und dazwischen beweglichen Elektronen. Erkläre, welche Eigenschaft es plausibel macht und was es vereinfacht.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Verbinde die Beweglichkeit der Elektronen mit elektrischer Leitfähigkeit.","Ein Modell ist keine maßstabsgetreue Abbildung."],"solution":"Das Modell erklärt die elektrische Leitfähigkeit, weil sich Elektronen durch das Gitter bewegen und Ladung transportieren können. Es vereinfacht die tatsächliche Elektronenverteilung und stellt weder quantenmechanische Zustände noch reale Abstände detailgetreu dar.","competencies":["E","B"],"operators":["erläutern","beurteilen"],"sourceLessonId":"chem.q1.1.bonding","sourceKind":"exercise","figures":[{"file":"electron-gas-model.svg","alt":"Elektronengasmodell: regelmäßig angeordnete Kreise mit Pluszeichen als Atomrümpfe, dazwischen viele kleine Punkte als frei bewegliche Elektronen.","placement":"prompt"}]},{"id":"chem.q1.1.bonding.selftest.models","title":"Bausteine im Ionengitter","difficulty":"basic","prompt":"Welche Bausteine bilden ein Ionengitter?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Denke an positive und negative Teilchen."],"solution":"Kationen und Anionen.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.bonding","sourceKind":"selfTest"},{"id":"chem.q1.1.bonding.selftest.metal","title":"Leitfähigkeit von Metallen","difficulty":"basic","prompt":"Welche Teilchen erklären die elektrische Leitfähigkeit eines Metalls?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie sind im Metallmodell delokalisiert."],"solution":"Bewegliche, delokalisierte Elektronen.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.bonding","sourceKind":"selfTest"},{"id":"chem.q1.1.bonding.selftest.polar","title":"Partialladungen","difficulty":"basic","prompt":"Was bedeuten δ⁺ und δ⁻ in einer Bindung?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Es sind keine vollen Ionenladungen."],"solution":"Sie bezeichnen Partialladungen durch ungleiche Verteilung der Bindungselektronen.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.bonding","sourceKind":"selfTest"},{"id":"chem.q1.1.hydrocarbons.exercise.basic-series","title":"Stoffklasse erkennen","difficulty":"basic","prompt":"Ordne Propan, Propen und Propin den Stoffklassen Alkan, Alken oder Alkin zu. Nenne jeweils das Strukturmerkmal.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Suche nach Einfach-, Doppel- oder Dreifachbindung zwischen C-Atomen."],"solution":"Propan ist ein Alkan mit C–C-Einfachbindungen. Propen ist ein Alken mit einer C=C-Doppelbindung. Propin ist ein Alkin mit einer C≡C-Dreifachbindung.","competencies":["S"],"operators":["zuordnen","benennen"],"sourceLessonId":"chem.q1.1.hydrocarbons","sourceKind":"exercise"},{"id":"chem.q1.1.hydrocarbons.exercise.basic-isomer","title":"Butan und 2-Methylpropan","difficulty":"basic","prompt":"Sind Butan und 2-Methylpropan Konstitutionsisomere? Begründe mit Summenformel und Verknüpfung.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Vergleiche die Summenformel und danach die Verknüpfung der C-Atome."],"solution":"Beide Stoffe haben die Summenformel C₄H₁₀, aber unterschiedliche Verknüpfungen: Butan ist unverzweigt, 2-Methylpropan verzweigt. Sie sind Konstitutionsisomere.","competencies":["S","K"],"operators":["begründen"],"sourceLessonId":"chem.q1.1.hydrocarbons","sourceKind":"exercise"},{"id":"chem.q1.1.hydrocarbons.exercise.standard-naming","title":"Struktur benennen","difficulty":"standard","prompt":"Benenne die Struktur CH₃–CH(CH₃)–CH₂–CH₃ nach IUPAC-Grundregeln.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Wähle die längste durchgehende C-Kette.","Nummeriere so, dass der Seitenrest die kleinste mögliche Positionszahl erhält."],"solution":"Die längste Kette hat vier C-Atome: Butan. Am C-2 sitzt eine Methylgruppe. Der Name lautet 2-Methylbutan.","competencies":["S"],"operators":["benennen"],"sourceLessonId":"chem.q1.1.hydrocarbons","sourceKind":"exercise"},{"id":"chem.q1.1.hydrocarbons.exercise.standard-addition","title":"HBr-Addition an But-1-en","difficulty":"standard","prompt":"Formuliere die Addition von HBr an But-1-en unter üblichen ionischen Bedingungen. Gib das Hauptprodukt nach der Markownikow-Regel an.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Die Doppelbindung wird geöffnet und H sowie Br addieren sich an die beiden C-Atome.","Bei der üblichen Markownikow-Orientierung bindet H an das stärker mit H substituierte C-Atom."],"solution":"CH₂=CH–CH₂–CH₃ + HBr → CH₃–CHBr–CH₂–CH₃. Das Hauptprodukt ist 2-Brombutan. Die Markownikow-Regel gilt für die üblichen ionischen Bedingungen; andere Bedingungen können die Orientierung verändern.","competencies":["S","E"],"operators":["formulieren","begründen"],"sourceLessonId":"chem.q1.1.hydrocarbons","sourceKind":"exercise"},{"id":"chem.q1.1.hydrocarbons.exercise.transfer-combustion","title":"Verbrennung stöchiometrisch formulieren","difficulty":"transfer","prompt":"Stelle die vollständige Verbrennung von Propan auf und gleiche die Gleichung aus. Erkläre, warum bei Sauerstoffmangel andere Produkte entstehen können.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Bei vollständiger Verbrennung entstehen CO₂ und H₂O.","Gleiche zuerst C und H, dann O aus."],"solution":"C₃H₈ + 5 O₂ → 3 CO₂ + 4 H₂O. Bei Sauerstoffmangel reicht der Sauerstoff nicht zur vollständigen Oxidation. Es können unter anderem CO oder elementarer Kohlenstoff entstehen; die genaue Produktverteilung hängt von den Bedingungen ab.","competencies":["S","E"],"operators":["formulieren","erläutern"],"sourceLessonId":"chem.q1.1.hydrocarbons","sourceKind":"exercise"},{"id":"chem.q1.1.hydrocarbons.exercise.transfer-reaction","title":"Bromwasser-Entfärbung deuten","difficulty":"transfer","prompt":"Ein Material zeigt, dass ein Alken Bromwasser entfärbt. Deute die Beobachtung auf Teilchenebene und formuliere eine passende Reaktionsgleichung für Ethen.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Die π-Bindung ist elektronenreich und kann an einer Additionsreaktion teilnehmen.","Atome aus Br₂ werden an die beiden C-Atome der Doppelbindung gebunden."],"solution":"Die Doppelbindung wird bei der Addition aufgelöst und zwei C–Br-Bindungen entstehen. CH₂=CH₂ + Br₂ → BrCH₂–CH₂Br. Die Entfärbung zeigt den Verbrauch des Broms; die Beobachtung allein belegt den Mechanismus nicht vollständig.","competencies":["S","E","K"],"operators":["deuten","formulieren"],"sourceLessonId":"chem.q1.1.hydrocarbons","sourceKind":"exercise"},{"id":"chem.q1.1.hydrocarbons.selftest.classes","title":"Kennzeichen eines Alkens","difficulty":"basic","prompt":"Welche Bindung kennzeichnet ein Alken?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie verbindet zwei C-Atome mehrfach."],"solution":"Ein Alken enthält mindestens eine C=C-Doppelbindung.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.hydrocarbons","sourceKind":"selfTest"},{"id":"chem.q1.1.hydrocarbons.selftest.isomers","title":"Konstitutionsisomere","difficulty":"basic","prompt":"Was unterscheidet Konstitutionsisomere?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Die Atome sind unterschiedlich verknüpft."],"solution":"Sie besitzen dieselbe Summenformel, aber unterschiedliche Verknüpfungen der Atome.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.hydrocarbons","sourceKind":"selfTest"},{"id":"chem.q1.1.hydrocarbons.selftest.addition","title":"Addition an C=C","difficulty":"basic","prompt":"Was geschieht bei einer Addition an eine C=C-Doppelbindung?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Die π-Bindung wird in neue Bindungen überführt."],"solution":"Die π-Bindung wird aufgelöst; zwei Gruppen addieren an die beiden C-Atome.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.hydrocarbons","sourceKind":"selfTest"},{"id":"chem.q1.1.inorganic-structures.exercise.basic-types","title":"Strukturtypen zuordnen","difficulty":"basic","prompt":"Ordne festes NaCl, festes Cu, molekulares CO₂ und festes Silicium jeweils einem Strukturmodell zu.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Achte auf die Art der Bausteine und ob abgegrenzte Moleküle vorliegen."],"solution":"NaCl: Ionengitter. Cu: Metallgitter mit delokalisierten Elektronen. CO₂(s): Molekülkristall aus CO₂-Molekülen. Elementares Silicium: kovalentes Atomnetzwerk.","competencies":["S"],"operators":["zuordnen"],"sourceLessonId":"chem.q1.1.inorganic-structures","sourceKind":"exercise"},{"id":"chem.q1.1.inorganic-structures.exercise.basic-silica","title":"Netzwerkstoff Siliciumdioxid","difficulty":"basic","prompt":"Siliciumdioxid wird als Netzwerkstoff beschrieben. Was bedeutet das für die Bausteine im Feststoff?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Unterscheide ein Atomnetzwerk von einem Kristall aus einzelnen Molekülen."],"solution":"Im Feststoff sind Si- und O-Atome durch ein zusammenhängendes kovalentes Netzwerk verbunden. Es liegen keine abgegrenzten SiO₂-Moleküle vor. SiO₂ ist die Verhältnisformel des Netzwerkstoffs.","competencies":["S","K"],"operators":["beschreiben","erläutern"],"sourceLessonId":"chem.q1.1.inorganic-structures","sourceKind":"exercise"},{"id":"chem.q1.1.inorganic-structures.exercise.standard-properties","title":"Struktur und Eigenschaft verknüpfen","difficulty":"standard","prompt":"Kupfer leitet als Feststoff gut Strom, Silicium deutlich schlechter. Erkläre den qualitativen Unterschied mit geeigneten Strukturmodellen.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Vergleiche die beweglichen Ladungsträger.","Ordne Silicium als Halbleiter ein; setze es nicht mit einem Isolator gleich."],"solution":"Im Kupfer können delokalisierte Elektronen das Gitter durchqueren und Ladung transportieren. Reines Silicium besitzt ein kovalentes Netzwerk und ist ein Halbleiter. Seine Ladungsträger sind unter üblichen Bedingungen deutlich weniger frei verfügbar als die Elektronen in einem Metall.","competencies":["S","E"],"operators":["vergleichen","erläutern"],"sourceLessonId":"chem.q1.1.inorganic-structures","sourceKind":"exercise"},{"id":"chem.q1.1.inorganic-structures.exercise.standard-structure","title":"SiO₂ und CO₂ vergleichen","difficulty":"standard","prompt":"Quarz und Kohlendioxid bestehen aus Siliciumdioxid beziehungsweise Kohlendioxid. Erkläre, warum SiO₂ als Netzwerkstoff und CO₂ als Molekülstoff beschrieben wird.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Betrachte die Bindungssituation und typische Teilchenstruktur der Feststoffe.","Die gleiche Elementsorte O führt nicht automatisch zur gleichen Stoffstruktur."],"solution":"Im SiO₂-Feststoff bildet jedes Si-Atom mit O-Atomen ein ausgedehntes kovalentes Netzwerk; einzelne SiO₂-Moleküle gibt es dort nicht. CO₂ besteht aus abgegrenzten, linearen Molekülen. Festes CO₂ ist ein Molekülkristall, in dem zwischen den Molekülen Dispersionskräfte wirken.","competencies":["S","E"],"operators":["erklären","vergleichen"],"sourceLessonId":"chem.q1.1.inorganic-structures","sourceKind":"exercise"},{"id":"chem.q1.1.inorganic-structures.exercise.transfer-context","title":"Materialeigenschaft beurteilen","difficulty":"transfer","prompt":"Ein Werkstoff soll bei hoher Temperatur formstabil bleiben und elektrisch nicht metallisch leitend sein. Ein Material nennt Quarz als Kandidaten. Beurteile die Eignung qualitativ anhand der Struktur und nenne eine Information, die du für eine konkrete Auswahl noch benötigst.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Verknüpfe das kovalente Netzwerk mit thermischer Stabilität.","Unterscheide qualitative Eignung von einem vollständigen Materialvergleich."],"solution":"Ein kovalentes Netzwerk wie in Quarz kann wegen der vielen starken Bindungen hohe thermische Stabilität unterstützen und leitet nicht wie ein Metall. Für eine konkrete Auswahl fehlen aber unter anderem Temperaturbereich, mechanische Belastung, Wärmeausdehnung und elektrische Anforderungen. Die Struktur allein reicht nicht für ein vollständiges Urteil.","competencies":["S","B"],"operators":["beurteilen","begründen"],"sourceLessonId":"chem.q1.1.inorganic-structures","sourceKind":"exercise"},{"id":"chem.q1.1.inorganic-structures.exercise.transfer-model","title":"Kugelmodell von Quarz","difficulty":"transfer","prompt":"Ein vereinfachtes Bild zeigt Siliciumdioxid als regelmäßig angeordnete Kugeln. Welche Aussagen über den Stoff kann das Bild unterstützen und welche Eigenschaften erklärt es nicht automatisch?","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Das Modell kann Nachbarschaften und Vernetzung veranschaulichen.","Makroskopische Eigenschaften benötigen zusätzliche Zusammenhänge."],"solution":"Das Bild kann die Vernetzung und lokale Anordnung der Atome veranschaulichen. Es liefert nicht automatisch quantitative Aussagen zu Härte, Wärmeleitfähigkeit oder chemischer Beständigkeit. Dafür brauchst du zusätzliche Struktur-, Mess- oder Materialdaten und ein geeignetes Modell.","competencies":["E","B"],"operators":["beurteilen","erläutern"],"sourceLessonId":"chem.q1.1.inorganic-structures","sourceKind":"exercise"},{"id":"chem.q1.1.inorganic-structures.selftest.network","title":"Formel eines Netzwerkstoffs","difficulty":"basic","prompt":"Was gibt die Formel SiO₂ bei Quarz an?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Denke an das Zahlenverhältnis in einer Netzwerkstruktur."],"solution":"Sie gibt das Verhältnis Si:O = 1:2 an; Quarz besteht nicht aus einzelnen SiO₂-Molekülen.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.inorganic-structures","sourceKind":"selfTest"},{"id":"chem.q1.1.inorganic-structures.selftest.conductivity","title":"Bindungen im Quarz","difficulty":"basic","prompt":"Welche Atome sind im Quarz über welche Art von Bindung zu einem Netzwerk verknüpft?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Quarz ist eine Form von Siliciumdioxid."],"solution":"Silicium- und Sauerstoff-Atome, verknüpft über kovalente Si–O-Bindungen zu einem räumlichen Netzwerk.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.inorganic-structures","sourceKind":"selfTest"},{"id":"chem.q1.1.inorganic-structures.selftest.silicon","title":"Ist Silicium ein Metall?","difficulty":"basic","prompt":"Ist Silicium ein Metall?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Ordne seine elektrische Leitfähigkeit ein."],"solution":"Nein. Silicium ist ein Halbleiter und besitzt eine kovalente Netzwerkstruktur.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.inorganic-structures","sourceKind":"selfTest"},{"id":"chem.q1.1.interactions.exercise.basic-shape","title":"Molekülform bestimmen","difficulty":"basic","prompt":"Leite mit dem EPA-Modell die Molekülform von CO₂ und H₂O ab.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Zähle am Zentralatom Bindungsbereiche und freie Elektronenpaare.","Mehrfachbindungen zählen im EPA-Modell als ein Elektronenbereich."],"solution":"CO₂ besitzt zwei Elektronenbereiche am C und keine freien Elektronenpaare; das Molekül ist linear. H₂O besitzt zwei Bindungsbereiche und zwei freie Elektronenpaare am O. Die Molekülform ist gewinkelt.","competencies":["S"],"operators":["bestimmen","darstellen"],"sourceLessonId":"chem.q1.1.interactions","sourceKind":"exercise"},{"id":"chem.q1.1.interactions.exercise.basic-force","title":"Wechselwirkung zwischen Wassermolekülen","difficulty":"basic","prompt":"Welche zwischenmolekulare Wechselwirkung kann zwischen Wassermolekülen auftreten? Begründe anhand der Struktur.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Prüfe, ob H direkt an ein stark elektronegatives Atom gebunden ist.","Betrachte auch freie Elektronenpaare am Nachbarmolekül."],"solution":"Wasser bildet Wasserstoffbrücken. H ist polar an O gebunden und kann mit einem freien Elektronenpaar eines O-Atoms in einem anderen Molekül wechselwirken. Zusätzlich treten Dipol-Dipol- und Dispersionskräfte auf.","competencies":["S"],"operators":["benennen","begründen"],"sourceLessonId":"chem.q1.1.interactions","sourceKind":"exercise"},{"id":"chem.q1.1.interactions.exercise.standard-dipole","title":"Molekülpolarität vergleichen","difficulty":"standard","prompt":"Erkläre, warum CO₂ trotz polarer C=O-Bindungen kein permanenter Dipol ist, H₂O aber schon.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Berücksichtige neben den Bindungen auch die räumliche Geometrie.","Prüfe, ob sich die Bindungsdipole gegenseitig aufheben."],"solution":"CO₂ ist linear und symmetrisch. Die beiden gleich großen C=O-Bindungsdipole zeigen entgegengesetzt und heben sich auf. H₂O ist gewinkelt; seine O–H-Bindungsdipole heben sich nicht vollständig auf. H₂O ist deshalb ein permanenter Dipol.","competencies":["S","E"],"operators":["erklären","vergleichen"],"sourceLessonId":"chem.q1.1.interactions","sourceKind":"exercise"},{"id":"chem.q1.1.interactions.exercise.standard-boiling","title":"Siedetemperatur von Ethan und Methan","difficulty":"standard","prompt":"Ethan siedet höher als Methan. Beide Stoffe sind unpolar. Begründe den Unterschied.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Beide Stoffe besitzen Dispersionskräfte.","Vergleiche Elektronenzahl und Polarisierbarkeit der Moleküle."],"solution":"Ethan besitzt mehr Elektronen und eine größere, stärker polarisierbare Elektronenhülle als Methan. Dadurch sind seine Dispersionskräfte stärker. Zum Trennen der Ethanmoleküle wird mehr Energie benötigt; daher liegt sein Siedepunkt höher.","competencies":["S","E"],"operators":["begründen"],"sourceLessonId":"chem.q1.1.interactions","sourceKind":"exercise"},{"id":"chem.q1.1.interactions.exercise.transfer-solubility","title":"Löslichkeit aus Struktur deuten","difficulty":"transfer","prompt":"Eine polare Substanz löst sich gut in Wasser, ein unpolares Öl dagegen kaum. Erkläre den Unterschied und nenne eine Grenze der Faustregel „Ähnliches löst sich in Ähnlichem“.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Vergleiche die Wechselwirkungen zwischen Wasser und den jeweiligen Stoffteilchen.","Löslichkeit hängt auch von Struktur und Energieänderungen ab."],"solution":"Polare Teilchen können mit Wasser Dipol-Dipol-Wechselwirkungen oder Wasserstoffbrücken eingehen. Unpolare Ölteilchen wechselwirken mit Wasser überwiegend über schwache Dispersionskräfte; das gleicht die Wechselwirkungen zwischen Wassermolekülen nicht ausreichend aus. Die Faustregel ist qualitativ. Molekülgröße, funktionelle Gruppen, Temperatur und Entropie beeinflussen die tatsächliche Löslichkeit ebenfalls.","competencies":["S","E","B"],"operators":["erläutern","beurteilen"],"sourceLessonId":"chem.q1.1.interactions","sourceKind":"exercise"},{"id":"chem.q1.1.interactions.exercise.transfer-hyaluronan","title":"Wasserbindung der Hyaluronsäure","difficulty":"transfer","prompt":"Ein Material beschreibt eine wasserreiche Hyaluronsäure-Schicht. Formuliere eine plausible Erklärung für die Wasserbindung, ohne allein aus dem Namen auf die genaue Löslichkeit einer Probe zu schließen.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Achte auf polare Gruppen und mögliche Wasserstoffbrücken.","Nenne weitere Informationen, die für eine quantitative Aussage fehlen."],"solution":"Polare Gruppen der Hyaluronsäure können mit Wassermolekülen Wasserstoffbrücken und weitere Dipol-Wechselwirkungen eingehen. Das unterstützt Hydratisierung und Wasserbindung. Die genaue Löslichkeit einer Probe lässt sich ohne Angaben zu Molekülstruktur, Gegenionen, Konzentration und Bedingungen nicht quantitativ vorhersagen.","competencies":["S","E","K"],"operators":["erläutern","begründen"],"sourceLessonId":"chem.q1.1.interactions","sourceKind":"exercise"},{"id":"chem.q1.1.interactions.selftest.geometry","title":"Elektronenbereiche im EPA-Modell","difficulty":"basic","prompt":"Was zählt im EPA-Modell als Elektronenbereich am Zentralatom?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Bindungen zählen unabhängig von ihrer Mehrfachheit; freie Paare zählen ebenfalls."],"solution":"Jede Einfach-, Doppel- oder Dreifachbindung zählt als ein Bereich. Jedes freie Elektronenpaar zählt ebenfalls.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.interactions","sourceKind":"selfTest"},{"id":"chem.q1.1.interactions.selftest.dipole","title":"Permanenter Dipol","difficulty":"basic","prompt":"Wann ist ein Molekül ein permanenter Dipol?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Betrachte die Summe der Bindungsdipole."],"solution":"Wenn sich die Bindungsdipole aufgrund der Molekülgeometrie nicht vollständig aufheben.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.interactions","sourceKind":"selfTest"},{"id":"chem.q1.1.interactions.selftest.forces","title":"Allgegenwärtige Wechselwirkung","difficulty":"basic","prompt":"Welche Wechselwirkung tritt zwischen allen Teilchen auf?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie entsteht durch momentane und induzierte Dipole."],"solution":"Dispersionskräfte wirken zwischen allen Teilchen.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.interactions","sourceKind":"selfTest"},{"id":"chem.q1.1.mechanisms.exercise.basic-classify","title":"Reaktionstyp unterscheiden","difficulty":"basic","prompt":"Ordne zu: (a) CH₄ + Cl₂ unter UV-Licht; (b) Ethen + HBr; (c) Bromoethan + OH⁻ in wässriger Lösung.","taskType":"structured","afb":2,"supportedModes":["screen"],"hints":["Austausch H gegen Cl ist Substitution.","Addition an eine Doppelbindung unterscheidet sich vom Austausch einer Abgangsgruppe."],"solution":"(a) Radikalische Substitution. (b) Elektrophile Addition. (c) Nukleophile Substitution, im einfachen Modell mit OH⁻ als Nukleophil.","competencies":["S"],"operators":["zuordnen","unterscheiden"],"sourceLessonId":"chem.q1.1.mechanisms","sourceKind":"exercise"},{"id":"chem.q1.1.mechanisms.exercise.basic-radical","title":"Phasen der radikalischen Chlorierung","difficulty":"basic","prompt":"Nenne die drei Phasen der radikalischen Chlorierung von Methan und ordne die Bildung von Cl· aus Cl₂ einer Phase zu.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Ein Initiierungsschritt erzeugt Radikale; danach wird die Kette fortgesetzt und schließlich abgebrochen."],"solution":"Die Phasen heißen Initiierung, Kettenfortpflanzung und Kettenabbruch. Cl₂ → 2 Cl· unter Licht ist die Initiierung.","competencies":["S"],"operators":["benennen","zuordnen"],"sourceLessonId":"chem.q1.1.mechanisms","sourceKind":"exercise"},{"id":"chem.q1.1.mechanisms.exercise.standard-sn2","title":"Nukleophile Substitution formulieren","difficulty":"standard","prompt":"Formuliere die Reaktion von Bromoethan mit Hydroxid-Ionen zu Ethanol als Ionengleichung und benenne angreifendes Teilchen und Abgangsgruppe.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["OH⁻ stellt ein Elektronenpaar für die neue C–O-Bindung bereit.","Bromid verlässt das Molekül."],"solution":"CH₃CH₂Br + OH⁻ → CH₃CH₂OH + Br⁻. OH⁻ ist das Nukleophil, Br⁻ die Abgangsgruppe. Die Gleichung zeigt eine nukleophile Substitution.","competencies":["S"],"operators":["formulieren","benennen"],"sourceLessonId":"chem.q1.1.mechanisms","sourceKind":"exercise"},{"id":"chem.q1.1.mechanisms.exercise.standard-elimination","title":"Eliminierung aus Bromethan","difficulty":"standard","prompt":"Bromoethan reagiert unter geeigneten Bedingungen mit Hydroxid-Ionen zu Ethen. Stelle eine ausgeglichene Ionengleichung auf und erkläre die Bindungsänderung.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Entferne H von einem benachbarten C-Atom und Br als Abgangsgruppe.","Aus einer C–C-Einfachbindung wird eine Doppelbindung."],"solution":"CH₃CH₂Br + OH⁻ → CH₂=CH₂ + H₂O + Br⁻. Ein H-Atom und Br werden abgespalten; zwischen den C-Atomen entsteht eine Doppelbindung.","competencies":["S","E"],"operators":["formulieren","erläutern"],"sourceLessonId":"chem.q1.1.mechanisms","sourceKind":"exercise"},{"id":"chem.q1.1.mechanisms.exercise.transfer-conditions","title":"Reaktionswege anhand von Bedingungen beurteilen","difficulty":"transfer","prompt":"Bromoethan wird einmal mit wässriger Hydroxid-Lösung und einmal mit alkoholischer Hydroxid-Lösung unter Erwärmen umgesetzt. Welche Reaktionstypen werden typischerweise begünstigt? Begründe vorsichtig anhand der Bedingungen.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Wässrige Lösung begünstigt in einfachen Schulmodellen Substitution; alkoholische Lösung und Erwärmen oft Eliminierung.","Formuliere die Vorhersage als Tendenz, nicht als Garantie unabhängig von Bedingungen."],"solution":"Wässrige Hydroxid-Lösung begünstigt typischerweise nukleophile Substitution zu Ethanol. Alkoholische Hydroxid-Lösung und Erwärmen begünstigen häufig Eliminierung zu Ethen. Es handelt sich um eine qualitative Tendenz; Substrat, Konzentration, Temperatur und Lösungsmittel beeinflussen die Produktverteilung.","competencies":["E","B"],"operators":["beurteilen","begründen"],"sourceLessonId":"chem.q1.1.mechanisms","sourceKind":"exercise"},{"id":"chem.q1.1.mechanisms.exercise.transfer-mechanism","title":"Mechanismus aus einem Schema","difficulty":"transfer","prompt":"Ein Reaktionsschema zeigt, dass eine Doppelbindung ein H⁺ aufnimmt und anschließend ein Halogenid-Ion bindet. Ordne den Mechanismus ein und erkläre, welche Bindungen sich ändern.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Ein elektronenreiches π-System greift ein Elektrophil an.","Prüfe, ob die Doppelbindung erhalten bleibt."],"solution":"Es handelt sich um eine elektrophile Addition. Die π-Bindung wird aufgelöst, es entsteht zunächst ein positiviertes Zwischenprodukt; anschließend bildet das Halogenid-Ion eine neue C–X-Bindung. Insgesamt werden H und X an die frühere Doppelbindung addiert.","competencies":["S","E","K"],"operators":["auswerten","erläutern"],"sourceLessonId":"chem.q1.1.mechanisms","sourceKind":"exercise"},{"id":"chem.q1.1.mechanisms.selftest.radical","title":"Startschritt der Chlorierung","difficulty":"basic","prompt":"Wie heißt der Schritt, in dem Licht aus Cl₂ zwei Cl-Radikale erzeugt?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Dabei startet die Radikalkette."],"solution":"Initiierung.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.mechanisms","sourceKind":"selfTest"},{"id":"chem.q1.1.mechanisms.selftest.nucleophile","title":"Rolle des Nucleophils","difficulty":"basic","prompt":"Was macht ein Nukleophil bei einer Substitution?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Es stellt ein Elektronenpaar bereit."],"solution":"Es bildet mit seinem Elektronenpaar eine neue Bindung und ersetzt dabei die Abgangsgruppe.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.mechanisms","sourceKind":"selfTest"},{"id":"chem.q1.1.mechanisms.selftest.elimination","title":"Kennzeichen der Eliminierung","difficulty":"basic","prompt":"Welche Strukturänderung ist für eine typische Eliminierung charakteristisch?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Zwei Gruppen werden abgespalten."],"solution":"Durch Abspaltung entsteht häufig eine C=C-Doppelbindung.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.1.mechanisms","sourceKind":"selfTest"},{"id":"chem.q1.2.alcohols.exercise.basic-classify","title":"Alkanol einordnen","difficulty":"basic","prompt":"Ordne Butan-1-ol, Butan-2-ol und 2-Methylpropan-2-ol als primäres, sekundäres oder tertiäres Alkanol ein.","taskType":"matching","afb":2,"supportedModes":["screen"],"hints":["Betrachte das C-Atom, an das die OH-Gruppe gebunden ist.","Zähle, mit wie vielen weiteren C-Atomen dieses C verbunden ist."],"solution":"Butan-1-ol ist primär: Das C mit OH ist an ein weiteres C gebunden. Butan-2-ol ist sekundär: Es ist an zwei weitere C-Atome gebunden. 2-Methylpropan-2-ol ist tertiär: Das C mit OH ist an drei weitere C-Atome gebunden.","competencies":["S"],"operators":["zuordnen"],"sourceLessonId":"chem.q1.2.alcohols","sourceKind":"exercise","answer":{"kind":"matching","options":["primär","sekundär","tertiär"],"items":[{"id":"butan-1-ol","label":"Butan-1-ol","correct":"primär"},{"id":"butan-2-ol","label":"Butan-2-ol","correct":"sekundär"},{"id":"methylpropan-2-ol","label":"2-Methylpropan-2-ol","correct":"tertiär"}]}},{"id":"chem.q1.2.alcohols.exercise.basic-bond","title":"Ethanol und Ethan","difficulty":"basic","prompt":"Welche Wechselwirkung kann zwischen zwei Ethanolmolekülen auftreten, die zwischen zwei Ethan-Molekülen nicht möglich ist? Begründe.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Untersuche, ob ein H-Atom direkt an O gebunden ist.","Prüfe, ob ein freies Elektronenpaar als Wechselwirkungspartner dienen kann."],"solution":"Zwischen Ethanolmolekülen können Wasserstoffbrücken zwischen der O–H-Gruppe und einem freien Elektronenpaar des O-Atoms eines Nachbarmoleküls entstehen. Ethan besitzt weder eine O–H-Gruppe noch O-Atome.","competencies":["S"],"operators":["benennen","begründen"],"sourceLessonId":"chem.q1.2.alcohols","sourceKind":"exercise"},{"id":"chem.q1.2.alcohols.exercise.standard-oxidation","title":"Oxidationsprodukt vorhersagen","difficulty":"standard","prompt":"Gib das organische Oxidationsprodukt von Butan-1-ol bei kontrollierter Oxidation an. Nenne auch ein mögliches Folgeprodukt bei weiterer Oxidation.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Butan-1-ol ist ein primäres Alkanol.","Bei weiterer Oxidation kann das zunächst gebildete Aldehyd zur Carbonsäure reagieren."],"solution":"Bei kontrollierter Oxidation entsteht Butanal. Bei weiterer Oxidation kann Butanal zu Butansäure oxidiert werden. Welche Stufe tatsächlich erreicht wird, hängt von Oxidationsmittel und Reaktionsbedingungen ab.","competencies":["S","E"],"operators":["angeben","begründen"],"sourceLessonId":"chem.q1.2.alcohols","sourceKind":"exercise"},{"id":"chem.q1.2.alcohols.exercise.standard-secondary","title":"Oxidation von Propan-2-ol","difficulty":"standard","prompt":"Formuliere die Oxidation von Propan-2-ol zu Propanon als vereinfachte Reaktionsgleichung mit [O].","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Ein sekundäres Alkanol bildet bei Oxidation ein Keton.","Bilanziere H und O in der vereinfachten Schreibweise."],"solution":"CH₃–CHOH–CH₃ + [O] → CH₃–CO–CH₃ + H₂O. Propan-2-ol wird zum Keton Propanon oxidiert.","competencies":["S","K"],"operators":["formulieren"],"sourceLessonId":"chem.q1.2.alcohols","sourceKind":"exercise"},{"id":"chem.q1.2.alcohols.exercise.transfer-properties","title":"Siedepunkte begründen","difficulty":"transfer","prompt":"Ethanol und Ethan besitzen ähnliche molare Massen. Ethanol siedet deutlich höher. Begründe den Unterschied über Struktur und Wechselwirkungen.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Beide Stoffe besitzen Dispersionskräfte.","Nur Ethanol kann zwischen seinen Molekülen Wasserstoffbrücken bilden."],"solution":"Ethanol besitzt eine polare OH-Gruppe und kann zwischen Molekülen Wasserstoffbrücken bilden. Ethan ist unpolar und besitzt überwiegend Dispersionskräfte. Die stärkeren zwischenmolekularen Anziehungen in Ethanol müssen beim Sieden überwunden werden; deshalb liegt sein Siedepunkt deutlich höher.","competencies":["S","E"],"operators":["begründen","vergleichen"],"sourceLessonId":"chem.q1.2.alcohols","sourceKind":"exercise"},{"id":"chem.q1.2.alcohols.exercise.transfer-tertiary","title":"Behauptung zu tertiären Alkanolen","difficulty":"transfer","prompt":"Eine Schülerin behauptet: „Jedes tertiäre Alkanol lässt sich unter milden Bedingungen genauso einfach zu einem Carbonylstoff oxidieren wie ein sekundäres Alkanol.“ Beurteile die Aussage.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Prüfe, ob das C-Atom mit OH ein H-Atom trägt.","Für eine einfache Carbonylbildung muss am betreffenden C ein H entfernt werden."],"solution":"Die Aussage ist falsch. Beim sekundären Alkanol trägt das C-Atom mit OH ein H-Atom, das bei der Oxidation entfernt werden kann. Ein tertiäres Alkanol besitzt dort kein solches H-Atom. Eine einfache Oxidation zum Carbonylstoff ist daher nicht möglich; stärkere Bedingungen können zu C–C-Spaltung führen.","competencies":["S","B"],"operators":["beurteilen","begründen"],"sourceLessonId":"chem.q1.2.alcohols","sourceKind":"exercise"},{"id":"chem.q1.2.alcohols.selftest.class","title":"Sekundäres Alkanol erkennen","difficulty":"basic","prompt":"Woran erkennst du ein sekundäres Alkanol?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Zähle die C-Nachbarn des C-Atoms mit OH."],"solution":"Das C-Atom mit der OH-Gruppe ist an zwei weitere C-Atome gebunden.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.2.alcohols","sourceKind":"selfTest"},{"id":"chem.q1.2.alcohols.selftest.primary","title":"Oxidation primärer Alkanole","difficulty":"basic","prompt":"Welches Produkt entsteht bei der ersten Oxidationsstufe eines primären Alkanols?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Es ist ein Carbonylstoff."],"solution":"Ein Aldehyd.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.2.alcohols","sourceKind":"selfTest"},{"id":"chem.q1.2.alcohols.selftest.tertiary","title":"Tertiäre Alkanole oxidieren","difficulty":"basic","prompt":"Warum wird ein tertiäres Alkanol nicht einfach zum Keton oxidiert?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Am C-Atom mit OH fehlt ein bestimmtes H-Atom."],"solution":"Am C-Atom mit der OH-Gruppe sitzt kein H-Atom, das für die einfache Bildung der Carbonylgruppe entfernt werden könnte.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.2.alcohols","sourceKind":"selfTest"},{"id":"chem.q1.2.carbonyls.exercise.basic-identify","title":"Aldehyd oder Keton?","difficulty":"basic","prompt":"Ordne Propanal und Propanon ein. Beschreibe jeweils die Position der Carbonylgruppe.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Prüfe, ob das Carbonyl-C am Ende der Kette oder zwischen zwei C-Atomen liegt."],"solution":"Propanal ist ein Aldehyd; die Carbonylgruppe liegt am Kettenende und ist an H gebunden. Propanon ist ein Keton; das Carbonyl-C liegt zwischen zwei C-Atomen.","competencies":["S"],"operators":["zuordnen","beschreiben"],"sourceLessonId":"chem.q1.2.carbonyls","sourceKind":"exercise"},{"id":"chem.q1.2.carbonyls.exercise.basic-polar","title":"Partialladungen an C=O","difficulty":"basic","prompt":"Welche Partialladungen entstehen an der C=O-Bindung? Begründe mit der Elektronegativität.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Sauerstoff zieht Bindungselektronen stärker an als Kohlenstoff."],"solution":"Die C=O-Bindung ist polar: O trägt δ⁻, das Carbonyl-C δ⁺. Das Carbonyl-C ist dadurch ein möglicher Angriffspunkt für ein Nukleophil.","competencies":["S"],"operators":["angeben","begründen"],"sourceLessonId":"chem.q1.2.carbonyls","sourceKind":"exercise"},{"id":"chem.q1.2.carbonyls.exercise.standard-reduction","title":"Reduktion zuordnen","difficulty":"standard","prompt":"Gib das Produkt der Reduktion von Butanon mit [H] an. Welche Stoffklasse entsteht?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Bei der Reduktion einer Carbonylgruppe entsteht eine C–OH-Gruppe.","Das Carbonyl-C des Ketons wird zu einem sekundären Alkohol-C."],"solution":"Butanon wird zu Butan-2-ol reduziert: CH₃COCH₂CH₃ + 2[H] → CH₃CHOHCH₂CH₃. Es entsteht ein sekundäres Alkanol.","competencies":["S","E"],"operators":["formulieren","zuordnen"],"sourceLessonId":"chem.q1.2.carbonyls","sourceKind":"exercise"},{"id":"chem.q1.2.carbonyls.exercise.standard-test","title":"Fehling-Befund auswerten","difficulty":"standard","prompt":"Eine Probe liefert mit Fehling-Lösung beim Erwärmen einen ziegelroten Niederschlag. Was kannst du daraus für eine typische Aldehydprobe schließen? Nenne eine Einschränkung.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die Fehling-Probe weist reduzierende Eigenschaften nach.","Ein positiver Test ist ein Hinweis, aber keine vollständige Strukturaufklärung."],"solution":"Ein positiver Fehling-Test ist mit einem Aldehyd vereinbar, der Cu²⁺ zu Cu₂O reduziert. Der Niederschlag ist ein Hinweis auf eine reduzierende Substanz, identifiziert aber ohne weitere Informationen nicht eindeutig ein bestimmtes Aldehyd.","competencies":["S","E"],"operators":["auswerten","beurteilen"],"sourceLessonId":"chem.q1.2.carbonyls","sourceKind":"exercise"},{"id":"chem.q1.2.carbonyls.exercise.transfer-addition","title":"Nucleophile Addition erklären","difficulty":"transfer","prompt":"Ein Nucleophil greift ein Carbonyl-C an. Beschreibe die Verschiebung des Elektronenpaars und die anschließende Protonierung in einer wässrigen Umgebung.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Das Carbonyl-C trägt δ⁺.","Die π-Elektronen der C=O-Bindung verschieben sich zum O-Atom."],"solution":"Das Nucleophil bindet an das elektrophile Carbonyl-C. Gleichzeitig werden die π-Elektronen der C=O-Bindung zum O verschoben. Es entsteht ein tetraedrisches O⁻-Zwischenprodukt, das in Wasser protoniert werden kann. Es bildet sich eine C–Nu-Bindung und aus C=O wird C–O.","competencies":["S","E"],"operators":["erläutern","darstellen"],"sourceLessonId":"chem.q1.2.carbonyls","sourceKind":"exercise"},{"id":"chem.q1.2.carbonyls.exercise.transfer-oxidation","title":"Unbekannte Carbonylverbindung","difficulty":"transfer","prompt":"Eine unbekannte Carbonylverbindung wird durch ein geeignetes Oxidationsmittel weiter oxidiert. Das Ergebnis passt zur Bildung einer Carbonsäure. Welche Stoffklasse liegt wahrscheinlich vor und warum?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Vergleiche die Oxidierbarkeit von Aldehyden und Ketonen im üblichen LK-Kontext.","Nenne die Aussage als begründete Zuordnung, nicht als vollständigen Strukturbeweis."],"solution":"Wahrscheinlich lag ein Aldehyd vor. Aldehyde können im üblichen Schulmodell zu Carbonsäuren oxidiert werden. Ketone lassen sich unter milden Bedingungen nicht entsprechend weiter oxidieren. Der Befund allein ist dennoch kein vollständiger Strukturbeweis; Versuchsbedingungen und weitere Nachweise sind zu berücksichtigen.","competencies":["E","B"],"operators":["ableiten","begründen"],"sourceLessonId":"chem.q1.2.carbonyls","sourceKind":"exercise"},{"id":"chem.q1.2.carbonyls.selftest.aldehyde","title":"Lage der Aldehydgruppe","difficulty":"basic","prompt":"Wo liegt die Carbonylgruppe eines Aldehyds?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Das Carbonyl-C trägt ein H-Atom."],"solution":"Am Kettenende; das Carbonyl-C ist an mindestens ein H-Atom gebunden.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.2.carbonyls","sourceKind":"selfTest"},{"id":"chem.q1.2.carbonyls.selftest.nucleophile","title":"Angriffspunkt für Nucleophile","difficulty":"basic","prompt":"Welches Atom der Carbonylgruppe ist für ein Nucleophil besonders angreifbar?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Die Bindung ist polar."],"solution":"Das δ⁺-Carbonyl-C.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.2.carbonyls","sourceKind":"selfTest"},{"id":"chem.q1.2.carbonyls.selftest.reduction","title":"Reduktion eines Ketons","difficulty":"basic","prompt":"Welche Alkoholklasse entsteht bei der Reduktion eines Ketons?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Das Carbonyl-C bleibt mit zwei C-Resten verbunden."],"solution":"Ein sekundäres Alkanol.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.2.carbonyls","sourceKind":"selfTest"},{"id":"chem.q1.3.carboxylic-acids.exercise.basic-group","title":"Carboxygruppe erkennen","difficulty":"basic","prompt":"Markiere die Carboxygruppe in CH₃–CH₂–COOH und benenne die Verbindung.","taskType":"free-response","afb":1,"supportedModes":["screen","handwriting"],"hints":["Eine Carboxygruppe enthält C=O und O–H am selben C-Atom.","Zähle die C-Atome der Hauptkette."],"solution":"Die Gruppe –COOH ist die Carboxygruppe. Die Verbindung heißt Propansäure.","competencies":["S"],"operators":["beschriften","benennen"],"sourceLessonId":"chem.q1.3.carboxylic-acids","sourceKind":"exercise"},{"id":"chem.q1.3.carboxylic-acids.exercise.basic-protolysis","title":"Protolyse der Ethansäure","difficulty":"basic","prompt":"Formuliere die Protolyse von Ethansäure in Wasser.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Die Säure überträgt ein Proton auf Wasser.","Das Säurerest-Ion ist Acetat."],"solution":"CH₃COOH + H₂O ⇌ CH₃COO⁻ + H₃O⁺. Ethansäure gibt ein Proton ab, Wasser nimmt es auf.","competencies":["S","K"],"operators":["formulieren"],"sourceLessonId":"chem.q1.3.carboxylic-acids","sourceKind":"exercise"},{"id":"chem.q1.3.carboxylic-acids.exercise.standard-acidity","title":"Säurestärke vergleichen","difficulty":"standard","prompt":"Chlorethansäure ist stärker sauer als Ethansäure. Erkläre den Unterschied mit dem induktiven Effekt.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Chlor ist elektronegativer als Kohlenstoff.","Vergleiche die Stabilität der jeweiligen Carboxylat-Ionen."],"solution":"Chlor zieht über σ-Bindungen Elektronendichte ab (−I-Effekt). Dadurch wird die negative Ladung im Chlorethanoat-Ion relativ stabilisiert. Die Protonenabgabe wird begünstigt; Chlorethansäure ist stärker als Ethansäure.","competencies":["S","E"],"operators":["vergleichen","begründen"],"sourceLessonId":"chem.q1.3.carboxylic-acids","sourceKind":"exercise"},{"id":"chem.q1.3.carboxylic-acids.exercise.standard-pka","title":"pKa-Werte vergleichen","difficulty":"standard","prompt":"Ethansäure hat pKa = 4,76, Chlorethansäure pKa = 2,86. Welche ist stärker? Begründe mit dem Zusammenhang zwischen pKa und Säurestärke.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Ein kleiner pKa-Wert bedeutet eine stärkere Säure.","Verknüpfe die Daten mit der Stabilität der konjugierten Base."],"solution":"Chlorethansäure ist stärker, weil ihr pKa-Wert kleiner ist (2,86 < 4,76). Der elektronenanziehende Chlorsubstituent stabilisiert das Chlorethanoat-Ion durch den −I-Effekt und begünstigt so die Protonenabgabe.","competencies":["S","E"],"operators":["auswerten","begründen"],"sourceLessonId":"chem.q1.3.carboxylic-acids","sourceKind":"exercise"},{"id":"chem.q1.3.carboxylic-acids.exercise.transfer-polyacid","title":"Mehrprotonige Säure deuten","difficulty":"transfer","prompt":"Oxalsäure besitzt zwei Carboxygruppen. Erkläre, warum man ihre Protolyse nicht mit nur einer einzigen Gleichung vollständig beschreibt.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Jede Carboxygruppe kann ein Proton abgeben.","Die Protonenabgaben laufen stufenweise ab und besitzen unterschiedliche Gleichgewichtskonstanten."],"solution":"Oxalsäure kann zwei Protonen stufenweise abgeben. Deshalb beschreibt man zwei Protolysegleichgewichte mit unterschiedlichen pKa-Werten. Die erste und zweite Protonenabgabe sind nicht gleich stark; nach der ersten Abgabe ist das Teilchen bereits negativ geladen.","competencies":["S","E"],"operators":["erläutern","begründen"],"sourceLessonId":"chem.q1.3.carboxylic-acids","sourceKind":"exercise"},{"id":"chem.q1.3.carboxylic-acids.exercise.transfer-isomerism","title":"Chiralität am α-C-Atom","difficulty":"transfer","prompt":"Eine Carbonsäure besitzt am α-C-Atom vier verschiedene Substituenten. Welche stereochemische Eigenschaft kann daraus folgen? Nenne, was zusätzlich zu prüfen ist.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Ein tetraedrisches C-Atom mit vier verschiedenen Gruppen kann chiral sein.","Die Struktur muss tatsächlich ein stereogenes Zentrum enthalten."],"solution":"Das α-C-Atom kann ein Chiralitätszentrum sein; dann sind Enantiomere möglich. Zu prüfen ist, ob wirklich vier verschiedene Substituenten gebunden sind. Aus der bloßen Nähe zur Carboxygruppe folgt Chiralität nicht automatisch.","competencies":["S","E"],"operators":["ableiten","begründen"],"sourceLessonId":"chem.q1.3.carboxylic-acids","sourceKind":"exercise"},{"id":"chem.q1.3.carboxylic-acids.selftest.group","title":"Aufbau der Carboxygruppe","difficulty":"basic","prompt":"Welche beiden Gruppen bilden zusammen die Carboxygruppe?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie enthalten eine Carbonyl- und eine Hydroxygruppe."],"solution":"Eine Carbonylgruppe C=O und eine Hydroxygruppe O–H am selben C-Atom.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.3.carboxylic-acids","sourceKind":"selfTest"},{"id":"chem.q1.3.carboxylic-acids.selftest.pka","title":"pKa und Säurestärke","difficulty":"basic","prompt":"Welche Säure ist bei sonst vergleichbaren Bedingungen stärker: pKa 2 oder pKa 5?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Ein kleinerer pKa bedeutet stärkere Säure."],"solution":"Die Säure mit pKa 2.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.3.carboxylic-acids","sourceKind":"selfTest"},{"id":"chem.q1.3.carboxylic-acids.selftest.inductive","title":"Elektronenziehende Gruppen","difficulty":"basic","prompt":"Wie beeinflusst eine elektronenanziehende Gruppe häufig die Carbonsäurestärke?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie kann die konjugierte Base stabilisieren."],"solution":"Sie zieht Elektronendichte ab und kann das Carboxylat-Ion stabilisieren; dadurch steigt häufig die Säurestärke.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.3.carboxylic-acids","sourceKind":"selfTest"},{"id":"chem.q1.3.esters.exercise.basic-name","title":"Estergruppe benennen","difficulty":"basic","prompt":"Markiere die Estergruppe in CH₃–COO–CH₂–CH₃ und benenne den Ester.","taskType":"free-response","afb":1,"supportedModes":["screen","handwriting"],"hints":["Trenne gedanklich Säurerest und Alkoholrest am O-Atom.","Der Säurerest stammt von Ethansäure, der Alkoholrest von Ethanol."],"solution":"Die Gruppe –COO– ist die Estergruppe. Der Stoff heißt Ethylethanoat (auch Ethansäureethylester).","competencies":["S"],"operators":["beschriften","benennen"],"sourceLessonId":"chem.q1.3.esters","sourceKind":"exercise"},{"id":"chem.q1.3.esters.exercise.basic-reaction","title":"Edukte und Produkte der Veresterung","difficulty":"basic","prompt":"Welche Stoffklassen reagieren bei der üblichen säurekatalysierten Veresterung miteinander? Welche zwei Produkte entstehen?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Betrachte Carboxygruppe und alkoholische Hydroxygruppe."],"solution":"Eine Carbonsäure reagiert mit einem Alkanol. Es entstehen ein Ester und Wasser. Die Reaktion ist reversibel.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.3.esters","sourceKind":"exercise"},{"id":"chem.q1.3.esters.exercise.standard-equilibrium","title":"Gleichgewicht beeinflussen","difficulty":"standard","prompt":"Eine Veresterung läuft im Gleichgewicht. Nenne zwei Möglichkeiten, die Esterbildung nach dem Prinzip von Le Châtelier zu begünstigen.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Entferne ein Produkt oder erhöhe die Menge eines Edukts.","Die Antwort muss mit dem Gleichgewicht der Reaktion verknüpft sein."],"solution":"Man kann einen Eduktstoff im Überschuss einsetzen oder Wasser beziehungsweise Ester während der Reaktion entfernen. Dadurch verschiebt sich das Gleichgewicht zur Produktseite. Die praktische Wirksamkeit hängt von Versuchsaufbau und Stoffeigenschaften ab.","competencies":["S","E"],"operators":["angeben","begründen"],"sourceLessonId":"chem.q1.3.esters","sourceKind":"exercise"},{"id":"chem.q1.3.esters.exercise.standard-hydrolysis","title":"Verseifung von Ethylethanoat","difficulty":"standard","prompt":"Formuliere die alkalische Hydrolyse von Ethylethanoat mit Natronlauge als Ionengleichung. Nenne die organischen Produkte.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["OH⁻ greift das Carbonyl-C an.","Bei basischer Hydrolyse liegt der Säurerest als Carboxylat vor."],"solution":"CH₃COOCH₂CH₃ + OH⁻ → CH₃COO⁻ + CH₃CH₂OH. Es entstehen Ethanoat-Ion und Ethanol.","competencies":["S","K"],"operators":["formulieren","benennen"],"sourceLessonId":"chem.q1.3.esters","sourceKind":"exercise"},{"id":"chem.q1.3.esters.exercise.transfer-mechanism","title":"Mechanismus erklären","difficulty":"transfer","prompt":"Erkläre die Grundidee der säurekatalysierten Veresterung von Ethansäure mit Ethanol. Warum wirkt Säure als Katalysator?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Protonierung macht das Carbonyl-C stärker elektrophil.","Nach Bindungsbildung und Wasserabgabe wird das Proton zurückgebildet."],"solution":"Die Säure protoniert zunächst das Carbonyl-O und erhöht so die Elektrophilie des Carbonyl-C. Ethanol kann nucleophil angreifen. Nach Protonenübertragungen wird Wasser abgespalten; abschließende Deprotonierung ergibt den Ester und regeneriert den Säurekatalysator.","competencies":["S","E"],"operators":["erläutern","begründen"],"sourceLessonId":"chem.q1.3.esters","sourceKind":"exercise"},{"id":"chem.q1.3.esters.exercise.transfer-process","title":"Esterausbeute erhöhen","difficulty":"transfer","prompt":"Ein Ansatz enthält Carbonsäure und Alkanol im Verhältnis 1:1. Die Ausbeute bleibt niedrig. Nenne zwei chemisch begründete Maßnahmen zur Erhöhung der Estermenge und eine praktische Einschränkung.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Nutze das Prinzip von Le Châtelier.","Eine technische Maßnahme muss zu Flüchtigkeit, Löslichkeit oder Sicherheit der Stoffe passen."],"solution":"Eduktüberschuss oder kontinuierliches Entfernen eines Produkts verschiebt das Gleichgewicht zur Esterseite. Praktische Einschränkungen: Abtrennung kann Energie benötigen; Stoffe können flüchtig oder sicherheitsrelevant sein, und nicht jeder Aufbau erlaubt eine selektive Produktentfernung.","competencies":["E","B"],"operators":["entwickeln","beurteilen"],"sourceLessonId":"chem.q1.3.esters","sourceKind":"exercise"},{"id":"chem.q1.3.esters.selftest.group","title":"Estergruppe","difficulty":"basic","prompt":"Welche funktionelle Gruppe kennzeichnet Ester?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie enthält ein Carbonyl-C und ein einfach gebundenes O."],"solution":"Die Estergruppe –COO–.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.3.esters","sourceKind":"selfTest"},{"id":"chem.q1.3.esters.selftest.catalyst","title":"Katalysator und Estergleichgewicht","difficulty":"basic","prompt":"Verschiebt ein Katalysator die Gleichgewichtslage?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Er beschleunigt beide Reaktionsrichtungen."],"solution":"Nein. Er beschleunigt Hin- und Rückreaktion, verändert aber nicht die Gleichgewichtslage.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.3.esters","sourceKind":"selfTest"},{"id":"chem.q1.3.esters.selftest.saponification","title":"Produkt der Verseifung","difficulty":"basic","prompt":"Welche organische Teilchenart entsteht bei alkalischer Esterhydrolyse aus dem Säurerest?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Die Reaktion läuft unter basischen Bedingungen."],"solution":"Ein Carboxylat-Ion.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.3.esters","sourceKind":"selfTest"},{"id":"chem.q1.4.q4.3.surfactants.exercise.1","title":"Bau eines Seifen-Anions","difficulty":"basic","prompt":"Natriumstearat (C₁₇H₃₅COO⁻ Na⁺) ist eine Seife. Beschreibe den Bau des Stearat-Ions und ordne seinen Molekülteilen die Begriffe hydrophil und hydrophob zu.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Unterscheide den geladenen Kopf und die lange Kohlenwasserstoffkette."],"solution":"Das Stearat-Ion besteht aus einer langen, unpolaren Kohlenwasserstoffkette (C₁₇H₃₅–) und einer negativ geladenen Carboxylatgruppe (–COO⁻). Die Carboxylatgruppe ist hydrophil, die Kohlenwasserstoffkette ist hydrophob.","competencies":["S"],"operators":["beschreiben","zuordnen"],"sourceLessonId":"chem.q1.4.q4.3.surfactants","sourceKind":"exercise"},{"id":"chem.q1.4.q4.3.surfactants.exercise.2","title":"Kalkseife formulieren","difficulty":"basic","prompt":"Formuliere die Reaktionsgleichung für die Bildung von Kalkseife aus Stearat-Ionen und Calcium-Ionen.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Ein Calcium-Ion ist zweifach positiv geladen."],"solution":"Ca²⁺ + 2 C₁₇H₃₅COO⁻ → (C₁₇H₃₅COO)₂Ca↓. Es entsteht schwer lösliches Calciumstearat.","competencies":["S"],"operators":["formulieren"],"sourceLessonId":"chem.q1.4.q4.3.surfactants","sourceKind":"exercise"},{"id":"chem.q1.4.q4.3.surfactants.exercise.3","title":"Fett von Textilien lösen","difficulty":"standard","prompt":"Erkläre auf Teilchenebene, wie Tenside einen Fettfleck von einem Textil ablösen und in der Waschlauge halten.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die hydrophoben Reste lagern sich am Fett an.","Denke an die Bildung von Mizellen."],"solution":"Die hydrophoben Reste der Tensid-Ionen lagern sich am unpolaren Fett an, die hydrophilen Köpfe zeigen ins Wasser. Durch die Bewegung der Waschlauge lösen sich Fetttröpfchen vom Gewebe. Sie werden vollständig von Tensid-Ionen umhüllt, mit dem Fett im Inneren und den geladenen Köpfen außen. Diese Mizellen stoßen sich wegen der gleichen Ladung gegenseitig ab und bleiben in der Lauge verteilt, bis sie ausgespült werden.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.q1.4.q4.3.surfactants","sourceKind":"exercise","figures":[{"file":"washing-steps.svg","alt":"Drei Schritte des Waschvorgangs: Erstens lagern sich Tensid-Teilchen mit ihren hydrophoben Resten an einen Fettfleck auf einer Faser an. Zweitens löst sich das Fett als Tröpfchen ab, auch an der Faser sitzen Tenside. Drittens ist das Fetttröpfchen vollständig von Tensiden umhüllt, die hydrophilen Köpfe zeigen nach außen.","caption":"Vereinfachtes Teilchenmodell des Waschvorgangs","placement":"solution"}]},{"id":"chem.q1.4.q4.3.surfactants.exercise.4","title":"Seife in saurer Lösung","difficulty":"standard","prompt":"Gibt man Salzsäure zu einer Seifenlösung, bildet sich ein weißer Niederschlag, und die Lösung schäumt kaum noch. Erkläre die Beobachtung mit einer Reaktionsgleichung.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Carboxylat-Ionen sind Basen."],"solution":"Die Oxonium-Ionen protonieren die Carboxylat-Ionen: C₁₇H₃₅COO⁻ + H₃O⁺ → C₁₇H₃₅COOH + H₂O. Die entstehende Fettsäure ist ungeladen und wegen der langen unpolaren Kette in Wasser schwer löslich; sie fällt aus. Damit fehlen die geladenen Tensid-Ionen, die Waschwirkung und Schaumbildung gehen zurück.","competencies":["S"],"operators":["erklären","formulieren"],"sourceLessonId":"chem.q1.4.q4.3.surfactants","sourceKind":"exercise"},{"id":"chem.q1.4.q4.3.surfactants.exercise.5","title":"Waschen in hartem Wasser","difficulty":"transfer","prompt":"Moderne Waschmittel enthalten statt Seife synthetische Tenside wie Alkylbenzolsulfonate und zusätzlich Enthärter wie Zeolith A. Erläutere, wie beide Maßnahmen die Waschleistung in hartem Wasser verbessern.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Vergleiche die Löslichkeit der Calciumsalze.","Zeolith A ist ein Ionenaustauscher."],"solution":"Calcium- und Magnesium-Ionen bilden mit Seifen-Anionen schwer lösliche Kalkseifen; Tensid geht verloren und lagert sich ab. Die Calciumsalze von Alkylbenzolsulfonaten sind deutlich besser löslich, diese Tenside bleiben daher in hartem Wasser wirksam. Zeolith A nimmt Calcium- und Magnesium-Ionen auf und gibt dafür Natrium-Ionen ab. Dadurch sinkt die Wasserhärte, und es bilden sich weniger Ablagerungen.","competencies":["S"],"operators":["erläutern"],"sourceLessonId":"chem.q1.4.q4.3.surfactants","sourceKind":"exercise"},{"id":"chem.q1.4.q4.3.surfactants.exercise.6","title":"Die sinkende Büroklammer","difficulty":"transfer","prompt":"Eine vorsichtig aufgelegte Büroklammer schwimmt auf Wasser. Gibt man einen Tropfen Spülmittel an den Rand, sinkt sie. Erkläre beide Beobachtungen.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["An der Wasseroberfläche wirken Wasserstoffbrücken nur zur Seite und nach unten.","Tenside lagern sich an der Oberfläche an."],"solution":"Die Wassermoleküle an der Oberfläche werden durch Wasserstoffbrücken nach innen und zur Seite gezogen; es entsteht eine Oberflächenspannung, die wie eine Haut die leichte Büroklammer trägt. Spülmittel enthält Tenside, die sich an der Oberfläche anordnen, mit den hydrophilen Köpfen im Wasser und den hydrophoben Resten zur Luft. Sie schieben sich zwischen die Wassermoleküle und verringern die Wechselwirkungen an der Oberfläche. Die Oberflächenspannung sinkt, die Büroklammer wird nicht mehr getragen.","competencies":["S","E"],"operators":["erklären"],"sourceLessonId":"chem.q1.4.q4.3.surfactants","sourceKind":"exercise"},{"id":"chem.q1.4.q4.3.surfactants.selftest.1","title":"Hydrophob","difficulty":"basic","prompt":"Welcher Teil eines Tensid-Moleküls ist hydrophob?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Er ist unpolar."],"solution":"Der lange Kohlenwasserstoffrest.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.4.q4.3.surfactants","sourceKind":"selfTest"},{"id":"chem.q1.4.q4.3.surfactants.selftest.2","title":"Wasserhärte","difficulty":"basic","prompt":"Welche Ionen verursachen die Wasserhärte?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Es sind zweifach positiv geladene Ionen."],"solution":"Calcium- und Magnesium-Ionen.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.4.q4.3.surfactants","sourceKind":"selfTest"},{"id":"chem.q1.4.q4.3.surfactants.selftest.3","title":"Inneres einer Mizelle","difficulty":"basic","prompt":"Was befindet sich im Inneren einer Mizelle in Wasser?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Die hydrophilen Köpfe zeigen zum Wasser."],"solution":"Die hydrophoben Reste der Tenside und gegebenenfalls aufgenommene unpolare Stoffe wie Fett.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.4.q4.3.surfactants","sourceKind":"selfTest"},{"id":"chem.q1.5.preservatives.exercise.basic-groups","title":"Konservierungsstoff einordnen","difficulty":"basic","prompt":"Sorbinsäure besitzt eine Carboxygruppe und mehrere C=C-Doppelbindungen. Welche Stoffklasse liegt vor und welche funktionelle Gruppe kann ein Proton abgeben?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Die Carboxygruppe kennzeichnet eine Carbonsäure."],"solution":"Sorbinsäure ist eine ungesättigte Carbonsäure. Die Carboxygruppe –COOH kann ein Proton abgeben.","competencies":["S"],"operators":["zuordnen","benennen"],"sourceLessonId":"chem.q1.5.preservatives","sourceKind":"exercise"},{"id":"chem.q1.5.preservatives.exercise.basic-vitamin","title":"Ascorbinsäure als Antioxidans","difficulty":"basic","prompt":"Ascorbinsäure wird als Antioxidans eingesetzt. Erkläre qualitativ, was ein Antioxidans in einer Oxidationsreaktion leisten kann.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Ein Antioxidans kann selbst oxidiert werden und so andere Stoffe schützen.","Beziehe dich auf die Elektronenübertragung."],"solution":"Ein Antioxidans kann als Reduktionsmittel Elektronen abgeben und dadurch die Oxidation eines anderen Stoffes begrenzen. Ascorbinsäure kann selbst oxidiert werden. Die konkrete Reaktionsbilanz muss dem Material entnommen werden.","competencies":["S","E"],"operators":["erläutern"],"sourceLessonId":"chem.q1.5.preservatives","sourceKind":"exercise"},{"id":"chem.q1.5.preservatives.exercise.standard-titration","title":"Konzentration einer Säure bestimmen","difficulty":"standard","prompt":"25,00 mL einer einprotonigen Konservierungssäure werden mit 0,0500 mol·L⁻¹ NaOH titriert. Am Äquivalenzpunkt sind 12,40 mL Maßlösung verbraucht. Berechne die Säurekonzentration.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Nutze das Verhältnis 1:1 der einprotonigen Säure und OH⁻.","Rechne beide Volumina in Liter um."],"solution":"n(OH⁻) = 0,0500 mol·L⁻¹ · 0,01240 L = 6,20·10⁻⁴ mol. Am Äquivalenzpunkt ist n(Säure) gleich groß. c(Säure) = 6,20·10⁻⁴ mol / 0,02500 L = 0,0248 mol·L⁻¹.","competencies":["S","E"],"operators":["berechnen"],"sourceLessonId":"chem.q1.5.preservatives","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"c","label":"Säurekonzentration","value":0.0248,"unit":"mol·L⁻¹"}]}},{"id":"chem.q1.5.preservatives.exercise.standard-speciation","title":"pH und Säureform","difficulty":"standard","prompt":"Eine schwache Konservierungssäure HA steht mit A⁻ im Gleichgewicht. Erkläre, wie eine pH-Erhöhung die Verteilung der beiden Formen qualitativ verändert.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Bei steigendem pH werden Protonen abgefangen.","Nutze das Gleichgewicht HA ⇌ H⁺ + A⁻."],"solution":"Eine pH-Erhöhung entspricht einer geringeren Oxonium-Ionen-Konzentration beziehungsweise basischeren Bedingungen. Das Gleichgewicht verschiebt sich zur deprotonierten Form A⁻. Der genaue Anteil hängt von pH und pKa ab.","competencies":["S","E"],"operators":["erläutern"],"sourceLessonId":"chem.q1.5.preservatives","sourceKind":"exercise"},{"id":"chem.q1.5.preservatives.exercise.transfer-method","title":"Analytische Methode planen","difficulty":"transfer","prompt":"Du sollst den Gehalt einer einprotonigen Konservierungssäure in einer Probe bestimmen. Skizziere eine geeignete Titrationsmethode und nenne zwei Grenzen.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Wähle eine Maßlösung bekannter Konzentration und einen passenden Endpunkt.","Beachte mögliche weitere Säuren oder gefärbte Bestandteile der Probe."],"solution":"Eine abgemessene Probenmenge wird mit standardisierter NaOH titriert. Am Äquivalenzpunkt wird das verbrauchte Volumen ermittelt und mit dem 1:1-Stoffmengenverhältnis in die Säurekonzentration umgerechnet. Grenzen: weitere titrierbare Säuren können das Ergebnis verfälschen; Eigenfarbe oder Trübung erschweren einen Indikatorendpunkt. pH-Metrie kann helfen, benötigt aber Kalibrierung.","competencies":["E","B"],"operators":["planen","begründen"],"sourceLessonId":"chem.q1.5.preservatives","sourceKind":"exercise"},{"id":"chem.q1.5.preservatives.exercise.transfer-health","title":"Grundlagen eines Gesundheitsurteils","difficulty":"transfer","prompt":"Ein Material nennt eine zulässige Einsatzmenge eines Konservierungsstoffs und einen analytisch bestimmten Gehalt. Welche chemischen und datenbezogenen Aspekte brauchst du für ein sachliches Urteil?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Vergleiche Gehalt mit dem konkret geltenden Grenzwert und berücksichtige Einheiten.","Ein chemischer Messwert allein ist keine vollständige Gesundheitsbewertung."],"solution":"Prüfe Messwert, Einheit, Probenbezug, Messunsicherheit und den konkret geltenden Grenzwert aus dem Aufgabenmaterial. Für ein gesundheitliches Urteil sind außerdem Exposition und toxikologische Daten nötig. Eine bloße Konzentrationsangabe belegt weder Sicherheit noch Schaden.","competencies":["E","B"],"operators":["beurteilen","bewerten"],"sourceLessonId":"chem.q1.5.preservatives","sourceKind":"exercise"},{"id":"chem.q1.5.preservatives.selftest.sorbic","title":"Säuregruppe der Sorbinsäure","difficulty":"basic","prompt":"Welche funktionelle Gruppe besitzt Sorbinsäure, die ein Proton abgeben kann?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie kennzeichnet eine Carbonsäure."],"solution":"Die Carboxygruppe –COOH.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.5.preservatives","sourceKind":"selfTest"},{"id":"chem.q1.5.preservatives.selftest.ascorbic","title":"Schutzwirkung der Ascorbinsäure","difficulty":"basic","prompt":"Wie kann Ascorbinsäure andere Stoffe vor Oxidation schützen?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie selbst kann Elektronen abgeben."],"solution":"Sie kann als Reduktionsmittel Elektronen abgeben und wird dabei selbst oxidiert.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.5.preservatives","sourceKind":"selfTest"},{"id":"chem.q1.5.preservatives.selftest.evidence","title":"Analysenwert und Grenzwert","difficulty":"basic","prompt":"Was musst du vor einem Vergleich eines Analysenwerts mit einem Grenzwert prüfen?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Achte auf Datenqualität und gleiche Bezugsgrößen."],"solution":"Einheit, Probenbezug, Messunsicherheit und den geltenden Referenzwert aus dem Material.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q1.5.preservatives","sourceKind":"selfTest"},{"id":"chem.q2.1.amino-acids-peptides.exercise.basic-draw","title":"Ladungsbild von Alanin","difficulty":"basic","prompt":"Alanin hat eine nicht ionisierbare Methyl-Seitenkette. Zeichne die bei pH 6,0 vorherrschende Struktur als Valenzstrichformel und markiere die formalen Ladungen.","taskType":"free-response","afb":1,"supportedModes":["handwriting"],"hints":["Vergleiche pH 6 zuerst mit den pKa-Werten der Carboxy- und Ammoniumgruppe.","Liegt der pH zwischen diesen pKa-Werten, ist die Carboxygruppe überwiegend deprotoniert und die Aminogruppe überwiegend protoniert."],"solution":"Alanin liegt überwiegend als H₃N⁺–CH(CH₃)–COO⁻ vor. Die Ammoniumgruppe trägt die Ladung +1, die Carboxylatgruppe −1. Zusammen ist die Gesamtladung null. Diese Form heißt Zwitterion.","competencies":["S","K"],"operators":["zeichnen","angeben"],"sourceLessonId":"chem.q2.1.amino-acids-peptides","sourceKind":"exercise","figures":[{"file":"alanine-zwitterion.svg","alt":"Valenzstrichformel des Alanin-Zwitterions: Ammoniumgruppe mit drei H-Atomen und positiver Ladung am Stickstoff, zentrales C-Atom mit H und CH₃, Carboxylatgruppe mit einer C=O-Doppelbindung und einem negativ geladenen Sauerstoffatom; freie Elektronenpaare an den Sauerstoffatomen.","caption":"Alanin bei pH 6,0 als Zwitterion","placement":"solution"}]},{"id":"chem.q2.1.amino-acids-peptides.exercise.basic-bonds","title":"Peptidbindungen im Tetrapeptid","difficulty":"basic","prompt":"Ein unverzweigtes Tetrapeptid besteht aus vier Aminosäureresten. Wie viele Peptidbindungen enthält es? Begründe deine Antwort.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Eine Peptidbindung verbindet zwei benachbarte Reste.","Bei einer linearen Kette aus n Resten gibt es n − 1 Verknüpfungen."],"solution":"Das Tetrapeptid enthält 4 − 1 = 3 Peptidbindungen. Zwischen vier Bausteinen liegen drei benachbarte Paare.","competencies":["S","K"],"operators":["bestimmen","begründen"],"sourceLessonId":"chem.q2.1.amino-acids-peptides","sourceKind":"exercise"},{"id":"chem.q2.1.amino-acids-peptides.exercise.standard-pi","title":"Isoelektrischen Punkt bestimmen","difficulty":"standard","prompt":"Für Alanin gelten pKa₁ = 2,35 und pKa₂ = 9,87. Berechne den isoelektrischen Punkt. Entscheide anschließend, ob Alanin bei pH 8,0 im Mittel positiv oder negativ geladen ist.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["Im vereinfachten Modell hat Alanin keine zusätzlich ionisierbare Seitenkette.","Vergleiche den gegebenen pH mit dem berechneten pI."],"solution":"Berechne zunächst den Mittelwert: pI = (2,35 + 9,87) / 2 = 12,22 / 2 = 6,11. Bei pH 8,0 > pI ist Alanin im Mittel leicht negativ geladen. Die Carboxylatgruppe liegt überwiegend als COO⁻ vor; ein kleiner Teil der Ammoniumgruppen ist bereits zu NH₂ deprotoniert.","competencies":["S","E"],"operators":["berechnen","begründen"],"sourceLessonId":"chem.q2.1.amino-acids-peptides","sourceKind":"exercise"},{"id":"chem.q2.1.amino-acids-peptides.exercise.standard-limiting","title":"Dipeptid aus Glycin und Alanin","difficulty":"standard","prompt":"Für die formale Bildung eines Dipeptids setzt du 0,080 mol Glycin und 0,060 mol Alanin ein. Berechne die maximal mögliche Stoffmenge des Dipeptids und die Stoffmenge des dabei im gleichen Verhältnis entstehenden Wassers.","taskType":"numeric","afb":2,"supportedModes":["screen","handwriting"],"hints":["Lies das Stoffmengenverhältnis aus der Reaktionsgleichung ab.","Vergleiche die Eduktmengen passend zu diesem Verhältnis."],"solution":"Die Reaktionsgleichung gibt für Glycin, Alanin, Dipeptid und Wasser das Verhältnis 1 : 1 : 1 : 1 an. Alanin ist mit 0,060 mol das limitierende Edukt. Deshalb können höchstens 0,060 mol Dipeptid und 0,060 mol Wasser entstehen.","competencies":["S","E"],"operators":["berechnen","ermitteln"],"sourceLessonId":"chem.q2.1.amino-acids-peptides","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"dipeptide","label":"n(Dipeptid)","value":0.06,"unit":"mol"},{"id":"water","label":"n(Wasser)","value":0.06,"unit":"mol"}]}},{"id":"chem.q2.1.amino-acids-peptides.exercise.transfer-migration","title":"Ladung und Wanderungsrichtung","difficulty":"transfer","prompt":"Du untersuchst Glycin in zwei Elektrophoreseversuchen: einmal bei pH 3,0 und einmal bei pH 8,0. Verwende pI(Glycin) = 5,97. Sage für beide Versuche die Nettoladungstendenz und die Wanderungsrichtung im elektrischen Feld voraus. Begründe auch, warum der pI allein keine genaue Verteilung der Konzentrationen angibt.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Unterhalb des pI überwiegt eine positive, oberhalb eine negative Nettoladung.","Kationen wandern zur negativen Elektrode (Kathode), Anionen zur positiven Elektrode (Anode).","Für genaue Anteile brauchst du zusätzlich pKa-Werte und Gleichgewichtsbeziehungen."],"solution":"Bei pH 3,0 < pI 5,97 überwiegt die positive Ladung. Glycin wandert daher zur Kathode, der negativen Elektrode. Bei pH 8,0 > pI überwiegt die negative Nettoladung; Glycin wandert zur Anode, der positiven Elektrode. Der pI gibt den pH-Wert der mittleren Nettoladung null an. Für die genauen Anteile der einzelnen Protonierungsformen brauchst du zusätzlich die pKa-Werte und musst die Gleichgewichte berechnen.","competencies":["S","E","K"],"operators":["vorhersagen","begründen","beurteilen"],"sourceLessonId":"chem.q2.1.amino-acids-peptides","sourceKind":"exercise"},{"id":"chem.q2.1.amino-acids-peptides.exercise.transfer-configuration","title":"L-Konfiguration und Drehsinn","difficulty":"transfer","prompt":"Eine Person behauptet: „L-Alanin dreht polarisiertes Licht immer nach links.“ Beurteile die Aussage und erkläre, welche Information die Bezeichnung L tatsächlich liefert.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Unterscheide die relative Konfiguration von der optischen Aktivität und Drehrichtung.","Ordne D/L der Fischer-Projektion zu, nicht einem Plus- oder Minuszeichen."],"solution":"Die Aussage ist falsch. L bezeichnet die relative Konfiguration im System der Fischer-Projektion. Das Vorzeichen der optischen Drehung wird experimentell bestimmt und lässt sich nicht allein aus L ableiten.","competencies":["S","K","B"],"operators":["beurteilen","erläutern"],"sourceLessonId":"chem.q2.1.amino-acids-peptides","sourceKind":"exercise"},{"id":"chem.q2.1.amino-acids-peptides.selftest.zwitterion","title":"Zwitterion erkennen","difficulty":"basic","prompt":"Welche Ladung trägt die Aminogruppe und welche die Carboxygruppe im Zwitterion einer α-Aminosäure?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Bei der inneren Protonenübertragung gibt die Carboxygruppe ein Proton an die Aminogruppe ab."],"solution":"Die Aminogruppe liegt als NH₃⁺ vor und trägt +1. Die Carboxygruppe liegt als COO⁻ vor und trägt −1. Zusammen ist die Gesamtladung null.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.1.amino-acids-peptides","sourceKind":"selfTest"},{"id":"chem.q2.1.amino-acids-peptides.selftest.pi","title":"pI-Regel","difficulty":"basic","prompt":"Welche beiden pKa-Werte mittelst du für den pI einer Aminosäure, deren Seitenkette nicht ionisierbar ist?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Suche die beiden Protolyse-Schritte, zwischen denen das Zwitterion liegt."],"solution":"Du mittelst die beiden pKa-Werte, zwischen denen das Zwitterion liegt: pI = (pKa₁ + pKa₂)/2.","competencies":["S"],"operators":["angeben","erläutern"],"sourceLessonId":"chem.q2.1.amino-acids-peptides","sourceKind":"selfTest"},{"id":"chem.q2.1.amino-acids-peptides.selftest.bonds","title":"Bindungszahl","difficulty":"basic","prompt":"Ein lineares Hexapeptid besteht aus sechs Aminosäureresten. Wie viele Peptidbindungen enthält es?","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Verbinde die sechs Reste zu einer Kette und zähle die Verknüpfungen."],"solution":"Das Hexapeptid enthält fünf Peptidbindungen: n−1 = 6−1 = 5.","competencies":["S"],"operators":["bestimmen"],"sourceLessonId":"chem.q2.1.amino-acids-peptides","sourceKind":"selfTest","answer":{"kind":"numeric","parts":[{"id":"bonds","label":"Anzahl der Peptidbindungen","value":5,"tolerance":{"absolute":0}}]}},{"id":"chem.q2.1.amino-acids-peptides.selftest.configuration","title":"D/L und optische Drehung","difficulty":"standard","prompt":"Kannst du aus der Bezeichnung D ableiten, dass eine Aminosäure polarisiertes Licht nach rechts dreht?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Unterscheide Konfiguration und gemessene Drehrichtung."],"solution":"Nein. D beschreibt eine relative Konfiguration in der Fischer-Konvention. Die Richtung der optischen Drehung muss gemessen werden.","competencies":["S","K"],"operators":["beurteilen"],"sourceLessonId":"chem.q2.1.amino-acids-peptides","sourceKind":"selfTest"},{"id":"chem.q2.1.amino-acids-peptides.selftest.limiting","title":"Limitierendes Edukt","difficulty":"standard","prompt":"Formal reagieren 0,12 mol Glycin mit 0,10 mol Alanin im Verhältnis 1:1. Wie viel Dipeptid kann höchstens entstehen?","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Bei einem Verhältnis von 1:1 begrenzt das knappere Edukt die Produktmenge."],"solution":"Alanin ist das limitierende Edukt. Daher können höchstens 0,10 mol Dipeptid entstehen.","competencies":["S","E"],"operators":["berechnen"],"sourceLessonId":"chem.q2.1.amino-acids-peptides","sourceKind":"selfTest","answer":{"kind":"numeric","parts":[{"id":"dipeptide","label":"n(Dipeptid)","value":0.1,"unit":"mol"}]}},{"id":"chem.q2.1.biopolymers.exercise.1","difficulty":"basic","title":"Bausteine und Bindungen zuordnen","prompt":"Ordne Proteinen, Cellulose und Chitin jeweils ihren Grundbaustein und die Bindung zu, über die die Bausteine verknüpft sind.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Proteine und Polysaccharide unterscheiden sich in Baustein und Bindungstyp.","Chitin ähnelt im Aufbau der Cellulose."],"solution":"Proteine: Aminosäuren, verknüpft über Peptidbindungen. Cellulose: β-D-Glucose, verknüpft über β-1,4-glycosidische Bindungen. Chitin: N-Acetylglucosamin, ebenfalls über β-1,4-glycosidische Bindungen verknüpft.","competencies":["S"],"operators":["zuordnen"],"sourceLessonId":"chem.q2.1.biopolymers","sourceKind":"exercise"},{"id":"chem.q2.1.biopolymers.exercise.2","difficulty":"basic","title":"Kondensation zählen","prompt":"50 Glucose-Einheiten werden formal zu einer unverzweigten Polysaccharidkette verknüpft. Gib an, wie viele Wassermoleküle dabei abgespalten werden, und begründe.","taskType":"structured","afb":2,"supportedModes":["screen"],"hints":["Jede glycosidische Bindung entsteht unter Abspaltung eines Wassermoleküls.","Zähle die Verknüpfungsstellen einer Kette."],"solution":"Es werden 49 Wassermoleküle abgespalten. In einer unverzweigten Kette aus 50 Bausteinen gibt es 49 glycosidische Bindungen, und bei jeder Kondensation wird ein Wassermolekül frei.","competencies":["S"],"operators":["angeben","begründen"],"sourceLessonId":"chem.q2.1.biopolymers","sourceKind":"exercise"},{"id":"chem.q2.1.biopolymers.exercise.3","difficulty":"standard","title":"Reißfeste Cellulose","prompt":"Cellulosefasern sind reißfest und in Wasser unlöslich. Erkläre beide Eigenschaften mit dem Bau der Cellulose.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Cellulose bildet lange, unverzweigte Ketten.","Überlege, welche Wechselwirkungen zwischen benachbarten Ketten möglich sind."],"solution":"Cellulose besteht aus langen, unverzweigten Ketten β-1,4-verknüpfter Glucose-Einheiten. Die Ketten liegen gestreckt und parallel nebeneinander. Zwischen ihren vielen Hydroxygruppen bilden sich zahlreiche Wasserstoffbrücken. Diese Vielzahl an Wechselwirkungen hält die Ketten fest zusammen und macht die Faser reißfest. Wassermoleküle können die Ketten nicht vollständig voneinander trennen, deshalb ist Cellulose unlöslich.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.q2.1.biopolymers","sourceKind":"exercise"},{"id":"chem.q2.1.biopolymers.exercise.4","difficulty":"standard","title":"Quellen ohne Lösen","prompt":"Ein Polysaccharid nimmt viel Wasser auf und quillt, löst sich aber nicht vollständig. Erkläre diesen Befund.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Unterscheide Wechselwirkungen mit Wasser und Wechselwirkungen zwischen den Ketten."],"solution":"Die polaren Hydroxygruppen binden Wassermoleküle über Wasserstoffbrücken; Wasser dringt zwischen die Ketten ein, das Material quillt. Lange Ketten, geordnete Bereiche und viele Wechselwirkungen zwischen den Ketten bleiben aber teilweise bestehen. Dadurch werden die Makromoleküle nicht vollständig voneinander getrennt und gehen nicht in Lösung.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.q2.1.biopolymers","sourceKind":"exercise"},{"id":"chem.q2.1.biopolymers.exercise.5","difficulty":"transfer","title":"Seide und Baumwolle vergleichen","prompt":"Seide besteht überwiegend aus dem Protein Fibroin, Baumwolle aus Cellulose. Vergleiche die beiden Fasern hinsichtlich Baustein, Verknüpfung und Wechselwirkungen zwischen den Ketten. Nenne einen Nachweis, mit dem du eine Seidenfaser von einer Baumwollfaser unterscheiden kannst.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Fibroin enthält auch Aminosäuren mit aromatischen Seitenketten wie Tyrosin.","Ein Proteinnachweis fällt bei Cellulose negativ aus."],"solution":"Seide: Aminosäuren, über Peptidbindungen verknüpft; zwischen den Ketten wirken vor allem Wasserstoffbrücken zwischen N–H- und C=O-Gruppen. Baumwolle: Glucose-Einheiten, über β-1,4-glycosidische Bindungen verknüpft; zwischen den Ketten wirken Wasserstoffbrücken zwischen Hydroxygruppen. Gemeinsam ist beiden die Stabilisierung durch Wasserstoffbrücken. Unterscheiden lassen sich die Fasern zum Beispiel mit der Xanthoprotein-Reaktion: Seide färbt sich mit konzentrierter Salpetersäure gelb, weil ihre aromatischen Seitenketten nitriert werden; Baumwolle nicht. Auch die Ninhydrin-Probe fällt nur bei Seide positiv aus.","competencies":["S","E"],"operators":["vergleichen","nennen"],"sourceLessonId":"chem.q2.1.biopolymers","sourceKind":"exercise"},{"id":"chem.q2.1.biopolymers.exercise.6","difficulty":"transfer","title":"Verdickungsmittel Guarkernmehl","prompt":"Ein Lebensmitteletikett nennt Guarkernmehl, das überwiegend aus einem Galactomannan besteht, als Verdickungsmittel. Erkläre, wie es Wasser „verdicken“ kann, und beurteile, welche Angaben fehlen, um die Wirkung zweier Produkte zu vergleichen.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Galactomannane sind lange Polysaccharidketten mit Seitengruppen.","Die Wirkung hängt nicht nur von der Stoffklasse ab."],"solution":"Galactomannane besitzen lange Ketten mit vielen Hydroxygruppen. Sie binden Wasser über Wasserstoffbrücken, und die langen, verzweigten Makromoleküle behindern sich gegenseitig in ihrer Bewegung. Dadurch steigt die Zähflüssigkeit. Für einen Vergleich zweier Produkte fehlen unter anderem die Kettenlänge beziehungsweise Molekülmasse, die eingesetzte Konzentration, die Temperatur und das Verhältnis von Mannose- zu Galactose-Einheiten. Aus dem Stoffnamen allein lässt sich die Stärke der Wirkung nicht ableiten.","competencies":["S","B"],"operators":["erklären","beurteilen"],"sourceLessonId":"chem.q2.1.biopolymers","sourceKind":"exercise"},{"id":"chem.q2.1.biopolymers.selftest.1","title":"Chitin einordnen","difficulty":"basic","prompt":"Zu welcher Stoffklasse gehört Chitin, und aus welchem Baustein ist es aufgebaut?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Chitin ist ein stickstoffhaltiger Naturstoff aus Zuckerbausteinen."],"solution":"Chitin ist ein Polysaccharid aus N-Acetylglucosamin-Einheiten.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.1.biopolymers","sourceKind":"selfTest"},{"id":"chem.q2.1.biopolymers.selftest.2","title":"Struktur-Eigenschafts-Kette","difficulty":"basic","prompt":"Formuliere für die Reißfestigkeit von Cellulose die Erklärungskette aus Strukturmerkmal, Wechselwirkung und Eigenschaft.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Strukturmerkmal → Wechselwirkung → Eigenschaft."],"solution":"Lange, unverzweigte Ketten mit vielen Hydroxygruppen → viele Wasserstoffbrücken zwischen parallel liegenden Ketten → hohe Reißfestigkeit.","competencies":["S","K"],"operators":["formulieren"],"sourceLessonId":"chem.q2.1.biopolymers","sourceKind":"selfTest"},{"id":"chem.q2.1.biopolymers.selftest.3","title":"Abgespaltenes Molekül","difficulty":"basic","prompt":"Welches Molekül wird bei der Bildung einer Peptidbindung und einer glycosidischen Bindung jeweils abgespalten?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Beide Verknüpfungen sind Kondensationsreaktionen."],"solution":"Jeweils ein Wassermolekül.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.1.biopolymers","sourceKind":"selfTest"},{"id":"chem.q2.1.carbohydrates.exercise.1","difficulty":"basic","title":"Anomere unterscheiden","prompt":"Worin unterscheiden sich α- und β-D-Glucopyranose? Gib das betroffene C-Atom an.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Beim Ringschluss entsteht ein neues Stereozentrum."],"solution":"Sie unterscheiden sich nur in der Konfiguration am anomeren C-Atom C1. In der Haworth-Projektion steht die OH-Gruppe an C1 bei α-D-Glucopyranose unterhalb, bei β-D-Glucopyranose oberhalb der Ringebene.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.1.carbohydrates","sourceKind":"exercise","figures":[{"file":"glucose-anomers.svg","alt":"Zwei Haworth-Projektionen nebeneinander. Bei α-D-Glucopyranose zeigt die OH-Gruppe am C1 nach unten, bei β-D-Glucopyranose nach oben. Die übrigen Gruppen sind gleich: CH₂OH an C5 oben, OH an C4 unten, an C3 oben, an C2 unten.","caption":"Haworth-Projektionen; H-Atome an den Ring-C-Atomen sind nicht dargestellt. Markiert ist das anomere C-Atom C1.","placement":"solution"}]},{"id":"chem.q2.1.carbohydrates.exercise.2","difficulty":"basic","title":"Glucose und Fructose","prompt":"Glucose und Fructose haben beide die Summenformel C₆H₁₂O₆. Beschreibe den Strukturunterschied ihrer offenkettigen Formen und gib an, in welchem Isomerieverhältnis sie zueinander stehen.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Vergleiche die funktionelle Gruppe und ihre Position in der Kette."],"solution":"Glucose ist eine Aldohexose mit einer Aldehydgruppe an C1. Fructose ist eine Ketohexose mit einer Ketogruppe an C2. Bei gleicher Summenformel und unterschiedlicher Verknüpfung sind sie Konstitutionsisomere.","competencies":["S"],"operators":["beschreiben","angeben"],"sourceLessonId":"chem.q2.1.carbohydrates","sourceKind":"exercise"},{"id":"chem.q2.1.carbohydrates.exercise.3","difficulty":"standard","title":"Reduzierende Wirkung begründen","prompt":"Begründe, warum Glucose in der Fehling-Probe reduzierend wirkt, obwohl sie in Wasser überwiegend als Ring vorliegt.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Ring- und Kettenform stehen im Gleichgewicht.","Nur eine bestimmte Form besitzt eine Aldehydgruppe."],"solution":"In wässriger Lösung stehen die Ringformen über die offenkettige Form im Gleichgewicht. Das Halbacetal an C1 kann sich öffnen; die offenkettige Form besitzt eine Aldehydgruppe. Diese reduziert Cu²⁺ zu Cu₂O. Weil dabei offenkettige Form verbraucht wird, stellt sich das Gleichgewicht laufend neu ein, bis die Glucose umgesetzt ist.","competencies":["S"],"operators":["begründen"],"sourceLessonId":"chem.q2.1.carbohydrates","sourceKind":"exercise"},{"id":"chem.q2.1.carbohydrates.exercise.4","difficulty":"standard","title":"Zwei Nachweise auswerten","prompt":"Probe A färbt sich mit Iod-Kaliumiodid-Lösung blauschwarz, die Fehling-Probe bleibt blau. Probe B zeigt mit Iod-Kaliumiodid keine Färbung, die Fehling-Probe ergibt einen ziegelroten Niederschlag. Deute beide Ergebnisse.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die beiden Nachweise prüfen unterschiedliche Eigenschaften."],"solution":"Probe A enthält Stärke: Die Blaufärbung entsteht durch Einlagerung von Polyiodid in die Amylose-Helix. Stärke hat nur sehr wenige freie Halbacetalgruppen und reagiert bei Fehling praktisch nicht. Probe B enthält keine Stärke, aber einen reduzierenden Zucker wie Glucose, der Cu²⁺ zu Cu₂O reduziert.","competencies":["S","E"],"operators":["deuten"],"sourceLessonId":"chem.q2.1.carbohydrates","sourceKind":"exercise"},{"id":"chem.q2.1.carbohydrates.exercise.5","difficulty":"transfer","title":"Lactose vorhersagen","prompt":"Lactose besteht aus Galactose und Glucose. Die Bausteine sind über C1 der Galactose und C4 der Glucose β-glycosidisch verknüpft. Sage das Verhalten von Lactose in der Fehling-Probe voraus und begründe.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Prüfe, welche anomeren C-Atome an der Bindung beteiligt sind."],"solution":"Lactose reagiert positiv. An der glycosidischen Bindung ist nur das anomere C-Atom der Galactose beteiligt. Das anomere C-Atom C1 der Glucose-Einheit bleibt als Halbacetal frei, kann sich zur offenkettigen Form mit Aldehydgruppe öffnen und Cu²⁺ reduzieren.","competencies":["S"],"operators":["vorhersagen","begründen"],"sourceLessonId":"chem.q2.1.carbohydrates","sourceKind":"exercise"},{"id":"chem.q2.1.carbohydrates.exercise.6","difficulty":"transfer","title":"Saccharose nach Hydrolyse","prompt":"Eine Saccharose-Lösung ergibt in der Fehling-Probe keinen Niederschlag. Wird sie zuvor mit verdünnter Salzsäure erhitzt und anschließend neutralisiert, fällt die Fehling-Probe positiv aus. Erkläre beide Befunde und begründe, warum vor der Fehling-Probe neutralisiert werden muss.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Säure katalysiert die Spaltung glycosidischer Bindungen.","Die Fehling-Lösung ist stark alkalisch."],"solution":"In Saccharose sind die anomeren C-Atome von Glucose und Fructose gemeinsam an der glycosidischen Bindung beteiligt; es gibt kein freies Halbacetal, die Probe ist negativ. Beim Erhitzen mit Säure wird die glycosidische Bindung hydrolysiert, es entstehen Glucose und Fructose. Beide wirken unter den Bedingungen der Fehling-Probe reduzierend. Die Säure muss vorher neutralisiert werden, weil sie sonst die alkalische Fehling-Lösung neutralisiert und die Reaktion verhindert.","competencies":["S","E"],"operators":["erklären","begründen"],"sourceLessonId":"chem.q2.1.carbohydrates","sourceKind":"exercise"},{"id":"chem.q2.1.carbohydrates.selftest.1","title":"Anomeres C-Atom","difficulty":"basic","prompt":"Welches C-Atom ist in D-Glucopyranose das anomere C-Atom?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Es ist das C-Atom der früheren Aldehydgruppe."],"solution":"C1.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.1.carbohydrates","sourceKind":"selfTest"},{"id":"chem.q2.1.carbohydrates.selftest.2","title":"Positiver Fehling-Befund","difficulty":"basic","prompt":"Welche Beobachtung zeigt eine positive Fehling-Probe an?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Achte auf Farbe und Niederschlag."],"solution":"Beim Erwärmen verschwindet die tiefblaue Farbe, und es bildet sich ein ziegelroter Niederschlag von Kupfer(I)-oxid.","competencies":["E"],"operators":["angeben"],"sourceLessonId":"chem.q2.1.carbohydrates","sourceKind":"selfTest"},{"id":"chem.q2.1.carbohydrates.selftest.3","title":"Iod-Stärke-Befund","difficulty":"basic","prompt":"Eine Probe färbt sich mit Iod-Kaliumiodid-Lösung blauschwarz. Was weist der Befund nach?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Der Nachweis beruht auf einer Helixstruktur."],"solution":"Stärke, genauer die Amylose. Der Befund ist kein allgemeiner Zuckernachweis.","competencies":["E"],"operators":["angeben"],"sourceLessonId":"chem.q2.1.carbohydrates","sourceKind":"selfTest"},{"id":"chem.q2.1.fats-oils.exercise.1","difficulty":"basic","title":"Triacylglycerid aufbauen","prompt":"Nenne die Bausteine eines Triacylglycerids und gib an, wie viele Esterbindungen es enthält.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Glycerin besitzt drei Hydroxygruppen."],"solution":"Ein Triacylglycerid besteht aus Glycerin und drei Fettsäuren. Alle drei Hydroxygruppen des Glycerins sind verestert; es enthält drei Esterbindungen.","competencies":["S"],"operators":["nennen","angeben"],"sourceLessonId":"chem.q2.1.fats-oils","sourceKind":"exercise"},{"id":"chem.q2.1.fats-oils.exercise.2","difficulty":"basic","title":"Fettsäuren einordnen","prompt":"Ordne Stearinsäure (C₁₇H₃₅COOH), Ölsäure (C₁₇H₃₃COOH) und Linolsäure (C₁₇H₃₁COOH) den Gruppen gesättigt, einfach ungesättigt und zweifach ungesättigt zu. Begründe mit der Summenformel des Alkylrests.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Ein gesättigter Alkylrest hat die Formel CₙH₂ₙ₊₁.","Jede C=C-Doppelbindung verringert die Zahl der H-Atome um zwei."],"solution":"Stearinsäure: C₁₇H₃₅ entspricht CₙH₂ₙ₊₁, also gesättigt. Ölsäure: zwei H-Atome weniger, eine C=C-Doppelbindung, einfach ungesättigt. Linolsäure: vier H-Atome weniger, zwei C=C-Doppelbindungen, zweifach ungesättigt.","competencies":["S"],"operators":["zuordnen","begründen"],"sourceLessonId":"chem.q2.1.fats-oils","sourceKind":"exercise"},{"id":"chem.q2.1.fats-oils.exercise.3","difficulty":"standard","title":"Verseifung formulieren","prompt":"Formuliere die Verseifung von Glycerintristearat mit Natronlauge als vereinfachte Ionengleichung und benenne die Produkte.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Glycerintristearat ist der Triester aus Glycerin und drei Stearinsäure-Molekülen.","Bei der Verseifung werden alle drei Esterbindungen gespalten."],"solution":"C₃H₅(OOC–C₁₇H₃₅)₃ + 3 OH⁻ → C₃H₅(OH)₃ + 3 C₁₇H₃₅COO⁻. Es entstehen Glycerin und drei Stearat-Ionen; zusammen mit den Natrium-Ionen liegt Natriumstearat, eine Seife, vor.","competencies":["S"],"operators":["formulieren","benennen"],"sourceLessonId":"chem.q2.1.fats-oils","sourceKind":"exercise"},{"id":"chem.q2.1.fats-oils.exercise.4","difficulty":"standard","title":"Iodzahl berechnen","prompt":"5,00 g eines Fettes addieren 0,00100 mol Iod (I₂). Berechne die Iodzahl. M(I₂) = 253,8 g·mol⁻¹.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Die Iodzahl gibt die Masse an Iod in Gramm pro 100 g Fett an."],"solution":"m(I₂) = 0,00100 mol · 253,8 g·mol⁻¹ = 0,2538 g. Iodzahl = 0,2538 g / 5,00 g · 100 ≈ 5,08.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q2.1.fats-oils","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"iodine","label":"Iodzahl","value":5.08}]}},{"id":"chem.q2.1.fats-oils.exercise.5","difficulty":"transfer","title":"Fetthärtung erklären","prompt":"Bei der partiellen Hydrierung eines Pflanzenöls steigt der Schmelzbereich, das Produkt wird streichfest. Erkläre diese Änderung und erläutere, warum dabei auch trans-Fettsäurereste entstehen können.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Wasserstoff wird an C=C-Doppelbindungen addiert.","Am Katalysator können sich Doppelbindungen umlagern."],"solution":"Bei der Hydrierung wird Wasserstoff an C=C-Doppelbindungen addiert; ein Teil der Reste wird gesättigt. Gesättigte Ketten sind gestreckt und lassen sich dichter packen, die Van-der-Waals-Kräfte nehmen zu, der Schmelzbereich steigt. Bei einer nur teilweisen Hydrierung können Doppelbindungen am Katalysator vorübergehend reagieren und in der energetisch günstigeren trans-Konfiguration zurückgebildet werden. So entstehen trans-Fettsäurereste.","competencies":["S"],"operators":["erklären","erläutern"],"sourceLessonId":"chem.q2.1.fats-oils","sourceKind":"exercise"},{"id":"chem.q2.1.fats-oils.exercise.6","difficulty":"transfer","title":"Öle über die Iodzahl vergleichen","prompt":"Öl A hat die Iodzahl 85, Öl B die Iodzahl 180. Vergleiche die beiden Öle hinsichtlich ihres Gehalts an C=C-Doppelbindungen und beurteile, welche Aussagen die Iodzahl über die Fettsäurezusammensetzung nicht liefert.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Je mehr Doppelbindungen, desto mehr Iod wird addiert.","Überlege, was eine einzige Kennzahl nicht unterscheiden kann."],"solution":"Öl B addiert pro 100 g gut doppelt so viel Iod wie Öl A und enthält entsprechend deutlich mehr C=C-Doppelbindungen. Die Iodzahl ist ein Summenwert. Sie zeigt nicht, wie sich die Doppelbindungen auf einzelne Fettsäuren verteilen, ob sie cis- oder trans-konfiguriert sind und welche Fettsäuren genau vorliegen. Für eine Identifizierung sind weitere Analysen nötig.","competencies":["S","B"],"operators":["vergleichen","beurteilen"],"sourceLessonId":"chem.q2.1.fats-oils","sourceKind":"exercise"},{"id":"chem.q2.1.fats-oils.selftest.1","title":"Fettsäurereste zählen","difficulty":"basic","prompt":"Wie viele Fettsäurereste enthält ein Triacylglycerid?","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Zähle die Hydroxygruppen des Glycerins."],"solution":"Drei.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.1.fats-oils","sourceKind":"selfTest","answer":{"kind":"numeric","parts":[{"id":"count","label":"Anzahl der Fettsäurereste","value":3,"tolerance":{"absolute":0}}]}},{"id":"chem.q2.1.fats-oils.selftest.2","title":"Iodzahl","difficulty":"basic","prompt":"Was gibt die Iodzahl eines Fettes an?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie bezieht sich auf 100 g Fett."],"solution":"Die Masse an Iod in Gramm, die 100 g Fett unter festgelegten Bedingungen addieren. Sie ist ein Maß für den Gehalt an C=C-Doppelbindungen.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.1.fats-oils","sourceKind":"selfTest"},{"id":"chem.q2.1.fats-oils.selftest.3","title":"Flüssige Öle","difficulty":"basic","prompt":"Warum sind Fette mit vielen cis-ungesättigten Fettsäureresten bei Raumtemperatur meist flüssig?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Cis-Doppelbindungen erzeugen Knicke in der Kette."],"solution":"Die Knicke verhindern eine dichte Packung der Ketten. Die Van-der-Waals-Kräfte zwischen den Molekülen sind schwächer, der Schmelzbereich liegt niedriger.","competencies":["S"],"operators":["begründen"],"sourceLessonId":"chem.q2.1.fats-oils","sourceKind":"selfTest"},{"id":"chem.q2.1.proteins.exercise.1","title":"Strukturebenen ordnen","difficulty":"basic","prompt":"Ordne die Aminosäuresequenz, eine α-Helix und die räumliche Faltung einer einzelnen Polypeptidkette den Strukturebenen eines Proteins zu.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Die Quartärstruktur beschreibt mehrere Untereinheiten."],"solution":"Aminosäuresequenz: Primärstruktur. α-Helix: Sekundärstruktur. Gesamte Faltung einer Kette: Tertiärstruktur.","competencies":["S"],"operators":["zuordnen"],"sourceLessonId":"chem.q2.1.proteins","sourceKind":"exercise"},{"id":"chem.q2.1.proteins.exercise.2","title":"Denaturierung und Hydrolyse","difficulty":"basic","prompt":"Erkläre, warum eine Denaturierung nicht automatisch eine Hydrolyse des Proteins bedeutet.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Unterscheide Faltungsänderung und Bindungsspaltung."],"solution":"Bei der Denaturierung ändern sich vor allem die räumliche Struktur und die stabilisierenden Wechselwirkungen; die Peptidbindungen bleiben in der Regel erhalten. Bei der Hydrolyse werden kovalente Peptidbindungen unter Wasseraufnahme gespalten.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.q2.1.proteins","sourceKind":"exercise"},{"id":"chem.q2.1.proteins.exercise.3","title":"Disulfidbrücken deuten","difficulty":"standard","prompt":"Ein Protein verliert an Stabilität, wenn seine S–S-Brücken reduziert werden. Erkläre den Befund.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Nenne Bindungstyp und Strukturfolge."],"solution":"Disulfidbrücken sind kovalente Querverbindungen zwischen Cysteinresten. Werden sie zu SH-Gruppen reduziert, fallen diese Verknüpfungen innerhalb einer Kette oder zwischen Ketten weg. Die Faltung wird weniger stark fixiert und kann sich leichter verändern.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.q2.1.proteins","sourceKind":"exercise"},{"id":"chem.q2.1.proteins.exercise.4","title":"Biuret-Befund auswerten","difficulty":"standard","prompt":"Eine Proteinprobe färbt sich bei der Biuret-Reaktion violett. Formuliere eine zulässige und eine nicht zulässige Schlussfolgerung.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Trenne Nachweisbeobachtung von Identifikation."],"solution":"Zulässig: Die Probe enthält Verbindungen mit mindestens zwei Peptidbindungen, also Peptide oder Proteine. Nicht zulässig: Es liege ein bestimmtes Protein mit einer bestimmten Funktion vor; dafür reicht der Farbnachweis nicht aus.","competencies":["E","B"],"operators":["formulieren"],"sourceLessonId":"chem.q2.1.proteins","sourceKind":"exercise"},{"id":"chem.q2.1.proteins.exercise.5","title":"pH-Einfluss erklären","difficulty":"transfer","prompt":"Ein Enzym verliert in stark saurer Lösung seine Aktivität. Erkläre einen möglichen molekularen Grund.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Betrachte geladene Seitenketten und ihre Wechselwirkungen."],"solution":"Im stark Sauren werden Seitenketten wie Carboxylatgruppen protoniert und verlieren ihre negative Ladung. Ionenbindungen zwischen Seitenketten und manche Wasserstoffbrücken brechen auf. Die Faltung, auch im aktiven Zentrum, verändert sich, und das Enzym verliert seine Aktivität. Wie stark der Effekt ist, hängt vom jeweiligen Protein ab.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.q2.1.proteins","sourceKind":"exercise"},{"id":"chem.q2.1.proteins.exercise.6","title":"Festigkeit von Keratin begründen","difficulty":"transfer","prompt":"Ein Materialtext führt die hohe Festigkeit einer Keratinfaser auf ihre Proteinstruktur zurück. Beurteile, welche Strukturangaben du für eine fundierte Erklärung benötigst.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Verknüpfe Struktur und makroskopische Eigenschaft mit Belegen."],"solution":"Benötigt werden Angaben zur Sekundärstruktur und Anordnung der Ketten in der Faser, zum Anteil an Cysteinresten und damit an Disulfidbrücken zwischen den Ketten sowie zu weiteren Wechselwirkungen wie Wasserstoffbrücken. Erst diese Angaben erlauben eine Erklärung; aus dem Stoffnamen Protein allein folgt keine bestimmte Festigkeit.","competencies":["S","B"],"operators":["beurteilen"],"sourceLessonId":"chem.q2.1.proteins","sourceKind":"exercise"},{"id":"chem.q2.1.proteins.selftest.1","title":"Grundbausteine","difficulty":"basic","prompt":"Aus welchen Bausteinen bestehen Proteine, und über welche Bindung sind sie verknüpft?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Denke an die Primärstruktur."],"solution":"Aus Aminosäuren, die über Peptidbindungen verknüpft sind.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.1.proteins","sourceKind":"selfTest"},{"id":"chem.q2.1.proteins.selftest.2","title":"Stabilisierende Wechselwirkungen","difficulty":"basic","prompt":"Nenne vier Wechselwirkungen oder Bindungen, die die Tertiärstruktur eines Proteins stabilisieren.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Kovalente und nicht kovalente Wechselwirkungen kommen vor."],"solution":"Wasserstoffbrücken, Ionenbindungen zwischen geladenen Seitenketten, hydrophobe Wechselwirkungen und Disulfidbrücken.","competencies":["S"],"operators":["nennen"],"sourceLessonId":"chem.q2.1.proteins","sourceKind":"selfTest"},{"id":"chem.q2.1.proteins.selftest.3","title":"Hitzedenaturierung","difficulty":"basic","prompt":"Werden bei der Denaturierung eines Proteins durch Hitze in der Regel Peptidbindungen gespalten?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Unterscheide Faltung und Primärstruktur."],"solution":"Nein. Die räumliche Struktur geht verloren, die Primärstruktur mit den Peptidbindungen bleibt in der Regel erhalten.","competencies":["S"],"operators":["entscheiden"],"sourceLessonId":"chem.q2.1.proteins","sourceKind":"selfTest"},{"id":"chem.q2.2.polycondensation-polyaddition.exercise.1","title":"Reaktionstyp zuordnen","difficulty":"basic","prompt":"Ordne den Reaktionen die Begriffe Polymerisation, Polykondensation und Polyaddition zu: (a) Ethen reagiert zu Polyethen. (b) Ethan-1,2-diol und Terephthalsäure reagieren zu einem Polyester und Wasser. (c) Ein Diol und ein Diisocyanat reagieren ohne Nebenprodukt zu einem Polyurethan.","taskType":"matching","afb":2,"supportedModes":["screen"],"hints":["Prüfe, ob eine Doppelbindung geöffnet wird und ob ein kleines Molekül entsteht."],"solution":"(a) Polymerisation. (b) Polykondensation. (c) Polyaddition.","competencies":["S"],"operators":["zuordnen"],"sourceLessonId":"chem.q2.2.polycondensation-polyaddition","sourceKind":"exercise","answer":{"kind":"matching","options":["Polymerisation","Polykondensation","Polyaddition"],"items":[{"id":"a","label":"(a) Ethen → Polyethen","correct":"Polymerisation"},{"id":"b","label":"(b) Ethan-1,2-diol + Terephthalsäure → Polyester + Wasser","correct":"Polykondensation"},{"id":"c","label":"(c) Diol + Diisocyanat → Polyurethan","correct":"Polyaddition"}]}},{"id":"chem.q2.2.polycondensation-polyaddition.exercise.2","title":"Funktionelle Gruppen der Monomere","difficulty":"basic","prompt":"Gib an, welche funktionellen Gruppen die Monomere tragen müssen, damit ein linearer Polyester beziehungsweise ein lineares Polyamid entsteht.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Jedes Monomer braucht zwei reaktionsfähige Gruppen."],"solution":"Polyester: Diole mit zwei Hydroxygruppen und Dicarbonsäuren mit zwei Carboxygruppen, oder Hydroxycarbonsäuren mit je einer der beiden Gruppen. Polyamid: Diamine mit zwei Aminogruppen und Dicarbonsäuren, oder Aminocarbonsäuren.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.2.polycondensation-polyaddition","sourceKind":"exercise"},{"id":"chem.q2.2.polycondensation-polyaddition.exercise.3","title":"Polyester formulieren","difficulty":"standard","prompt":"Ethan-1,2-diol (HO–CH₂–CH₂–OH) reagiert mit Butandisäure (HOOC–CH₂–CH₂–COOH) zu einem Polyester. Formuliere die Wiederholungseinheit und gib an, wie viele Wassermoleküle pro neu gebildeter Esterbindung entstehen.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Eine Esterbindung entsteht aus einer Hydroxy- und einer Carboxygruppe.","Achte darauf, dass die Wiederholungseinheit je einen Baustein beider Monomere enthält."],"solution":"Wiederholungseinheit: [–O–CH₂–CH₂–O–CO–CH₂–CH₂–CO–]ₙ. Pro Esterbindung wird ein Wassermolekül abgespalten.","competencies":["S","K"],"operators":["formulieren","angeben"],"sourceLessonId":"chem.q2.2.polycondensation-polyaddition","sourceKind":"exercise"},{"id":"chem.q2.2.polycondensation-polyaddition.exercise.4","title":"Polyamid 6,6","difficulty":"standard","prompt":"Polyamid 6,6 entsteht aus Hexandisäure und Hexan-1,6-diamin. Formuliere die Wiederholungseinheit und erkläre, warum Polyamidfasern besonders reißfest sind.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Die Amidgruppe enthält N–H- und C=O-Gruppen."],"solution":"Wiederholungseinheit: [–NH–(CH₂)₆–NH–CO–(CH₂)₄–CO–]ₙ; bei jeder Verknüpfung wird Wasser abgespalten. Zwischen den N–H-Gruppen einer Kette und den C=O-Gruppen benachbarter Ketten bilden sich zahlreiche Wasserstoffbrücken. Diese starken zwischenmolekularen Kräfte halten die Ketten fest zusammen und machen die Faser reißfest.","competencies":["S","K"],"operators":["formulieren","erklären"],"sourceLessonId":"chem.q2.2.polycondensation-polyaddition","sourceKind":"exercise","figures":[{"file":"polyamide-hydrogen-bonds.svg","alt":"Zwei waagerechte Polyamid-Kettenabschnitte übereinander. Die C=O-Gruppen der einen Kette liegen gegenüber den N–H-Gruppen der anderen; gepunktete Linien kennzeichnen die Wasserstoffbrücken zwischen ihnen.","caption":"Ausschnitt aus zwei benachbarten Ketten von Polyamid 6,6","placement":"solution"}]},{"id":"chem.q2.2.polycondensation-polyaddition.exercise.5","title":"Glycerin statt Diol","difficulty":"transfer","prompt":"Bei einer Polyestersynthese wird ein Teil des Ethan-1,2-diols durch Glycerin (Propan-1,2,3-triol) ersetzt. Leite ab, wie sich Struktur und Eigenschaften des Produkts verändern.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Zähle die Hydroxygruppen von Glycerin.","Überlege, was eine dritte reaktionsfähige Gruppe für das Kettenwachstum bedeutet."],"solution":"Glycerin besitzt drei Hydroxygruppen und kann mit drei Säuregruppen verestert werden. An diesen Stellen verzweigen sich die Ketten, und es können Querverbindungen zwischen Ketten entstehen. Es bildet sich ein räumliches Netzwerk. Das Produkt wird härter und lässt sich nicht mehr schmelzen und umformen; es verhält sich wie ein Duroplast.","competencies":["S"],"operators":["ableiten"],"sourceLessonId":"chem.q2.2.polycondensation-polyaddition","sourceKind":"exercise"},{"id":"chem.q2.2.polycondensation-polyaddition.exercise.6","title":"Polyurethan und Feuchtigkeit","difficulty":"transfer","prompt":"Polyurethane entstehen aus Diisocyanaten (O=C=N–R–N=C=O) und Diolen. Erkläre, warum diese Reaktion eine Polyaddition ist. Bei der Herstellung kompakter Polyurethan-Teile muss Feuchtigkeit ausgeschlossen werden; Isocyanatgruppen reagieren mit Wasser zu einer Aminogruppe und Kohlenstoffdioxid. Erläutere die Folge für das Material.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Prüfe, ob bei der Bildung der Urethangruppe ein Molekül abgespalten wird.","Ein Gas entsteht im Inneren des Materials."],"solution":"Bei der Reaktion lagert sich das H-Atom der Hydroxygruppe an das N-Atom der Isocyanatgruppe an, es entsteht die Urethangruppe –NH–CO–O–. Dabei wird kein Molekül abgespalten; es handelt sich um eine Polyaddition. Mit Wasser reagiert die Isocyanatgruppe: R–N=C=O + H₂O → R–NH₂ + CO₂. Das entstehende Kohlenstoffdioxid bildet Gasblasen im Material, das Teil wird porös statt kompakt. Diese Reaktion nutzt man gezielt bei der Herstellung von Polyurethanschäumen.","competencies":["S"],"operators":["erklären","erläutern"],"sourceLessonId":"chem.q2.2.polycondensation-polyaddition","sourceKind":"exercise"},{"id":"chem.q2.2.polycondensation-polyaddition.selftest.1","title":"Kondensationsprodukt","difficulty":"basic","prompt":"Welches kleine Molekül entsteht bei der Bildung eines Polyesters aus einem Diol und einer Dicarbonsäure?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Es entsteht bei jeder Esterbildung."],"solution":"Wasser.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.2.polycondensation-polyaddition","sourceKind":"selfTest"},{"id":"chem.q2.2.polycondensation-polyaddition.selftest.2","title":"Polykondensation und Polyaddition","difficulty":"basic","prompt":"Worin unterscheiden sich Polykondensation und Polyaddition in ihrer Stoffbilanz?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Achte auf Nebenprodukte."],"solution":"Bei der Polykondensation wird bei jeder Verknüpfung ein kleines Molekül wie Wasser abgespalten, bei der Polyaddition nicht.","competencies":["S"],"operators":["unterscheiden"],"sourceLessonId":"chem.q2.2.polycondensation-polyaddition","sourceKind":"selfTest"},{"id":"chem.q2.2.polycondensation-polyaddition.selftest.3","title":"Mindestzahl funktioneller Gruppen","difficulty":"basic","prompt":"Wie viele reaktionsfähige funktionelle Gruppen muss ein Monomer mindestens besitzen, damit eine lineare Kette wachsen kann?","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Die Kette muss an beiden Enden weiterwachsen können."],"solution":"Zwei.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.2.polycondensation-polyaddition","sourceKind":"selfTest","answer":{"kind":"numeric","parts":[{"id":"count","label":"Mindestzahl funktioneller Gruppen","value":2,"tolerance":{"absolute":0}}]}},{"id":"chem.q2.2.polymerization.exercise.1","title":"Wiederholungseinheit ableiten","difficulty":"basic","prompt":"Gib die Wiederholungseinheiten der Polymere an, die durch Polymerisation von Propen (CH₂=CH–CH₃) und von Chlorethen (CH₂=CHCl) entstehen.","taskType":"free-response","afb":1,"supportedModes":["screen","handwriting"],"hints":["Öffne die C=C-Doppelbindung; die Seitenreste bleiben erhalten."],"solution":"Polypropen: [–CH₂–CH(CH₃)–]ₙ. Polychlorethen (PVC): [–CH₂–CHCl–]ₙ.","competencies":["S","K"],"operators":["angeben"],"sourceLessonId":"chem.q2.2.polymerization","sourceKind":"exercise"},{"id":"chem.q2.2.polymerization.exercise.2","title":"Monomer erschließen","difficulty":"basic","prompt":"Gib für die Polymere [–CF₂–CF₂–]ₙ und [–CH₂–CH(CN)–]ₙ jeweils das Monomer an.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Setze zwischen die beiden C-Atome der Hauptkette wieder eine Doppelbindung."],"solution":"[–CF₂–CF₂–]ₙ entsteht aus Tetrafluorethen CF₂=CF₂. [–CH₂–CH(CN)–]ₙ entsteht aus Propennitril (Acrylnitril) CH₂=CH–CN.","competencies":["S","K"],"operators":["angeben"],"sourceLessonId":"chem.q2.2.polymerization","sourceKind":"exercise"},{"id":"chem.q2.2.polymerization.exercise.3","title":"Radikalische Polymerisation formulieren","difficulty":"standard","prompt":"Ethen wird mit einem Peroxid R–O–O–R als Initiator polymerisiert. Formuliere je eine Gleichung für Start, Kettenwachstum und Kettenabbruch.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Die O–O-Bindung des Peroxids spaltet sich homolytisch.","Beim Abbruch reagieren zwei Radikale miteinander."],"solution":"Start: R–O–O–R → 2 R–O·, danach R–O· + CH₂=CH₂ → R–O–CH₂–CH₂·. Kettenwachstum: R–O–CH₂–CH₂· + CH₂=CH₂ → R–O–CH₂–CH₂–CH₂–CH₂·, dieser Schritt wiederholt sich vielfach. Kettenabbruch, zum Beispiel durch Rekombination: R–O–(CH₂)ₙ· + ·(CH₂)ₘ–O–R → R–O–(CH₂)ₙ₊ₘ–O–R.","competencies":["S","K"],"operators":["formulieren"],"sourceLessonId":"chem.q2.2.polymerization","sourceKind":"exercise"},{"id":"chem.q2.2.polymerization.exercise.4","title":"Molare Masse einer Kette","difficulty":"standard","prompt":"Eine Polyethen-Kette besteht aus 2000 Ethen-Einheiten. Berechne ihre molare Masse näherungsweise (M(C₂H₄) = 28,05 g·mol⁻¹) und begründe, warum du die Masse der Monomere einfach addieren darfst.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["Endgruppen kannst du bei so langen Ketten vernachlässigen."],"solution":"M ≈ 2000 · 28,05 g·mol⁻¹ = 56 100 g·mol⁻¹ ≈ 5,6 · 10⁴ g·mol⁻¹. Bei der Polymerisation wird kein kleines Molekül abgespalten; jede Ethen-Einheit geht vollständig in die Kette ein. Nur die Endgruppen weichen ab, ihr Anteil ist bei 2000 Einheiten vernachlässigbar.","competencies":["S"],"operators":["berechnen","begründen"],"sourceLessonId":"chem.q2.2.polymerization","sourceKind":"exercise"},{"id":"chem.q2.2.polymerization.exercise.5","title":"Polystyrol und Polyethen","difficulty":"transfer","prompt":"Polystyrol ist bei Raumtemperatur hart und spröde, Polyethen niedriger Dichte weich und biegsam. Erkläre den Unterschied mit dem Bau der Ketten.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Vergleiche die Seitenreste der beiden Polymere."],"solution":"Polystyrol trägt an jeder zweiten Kohlenstoff-Einheit einen großen Phenylrest. Diese sperrigen Seitengruppen behindern die Drehung und das Aneinandervorbeigleiten der Ketten; bei Raumtemperatur sind die Ketten praktisch unbeweglich, der Stoff ist hart und spröde. Polyethen besitzt nur H-Atome als Substituenten; seine Ketten sind bei Raumtemperatur in den ungeordneten Bereichen gut beweglich, der Werkstoff ist biegsam.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.q2.2.polymerization","sourceKind":"exercise"},{"id":"chem.q2.2.polymerization.exercise.6","title":"Mehr Initiator, kürzere Ketten","difficulty":"transfer","prompt":"Bei einer radikalischen Polymerisation wird die Initiatormenge verdoppelt, alle übrigen Bedingungen bleiben gleich. Leite ab, wie sich die mittlere Kettenlänge verändert.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Jedes Startradikal beginnt eine eigene Kette.","Mehr Radikale treffen auch häufiger aufeinander."],"solution":"Mit mehr Initiator entstehen mehr Startradikale und damit mehr wachsende Ketten. Die vorhandenen Monomere verteilen sich auf mehr Ketten, und Abbruchreaktionen zwischen Radikalen werden häufiger. Die mittlere Kettenlänge nimmt deshalb ab.","competencies":["S","E"],"operators":["ableiten"],"sourceLessonId":"chem.q2.2.polymerization","sourceKind":"exercise"},{"id":"chem.q2.2.polymerization.selftest.1","title":"Nebenprodukt?","difficulty":"basic","prompt":"Wird bei der Polymerisation von Ethen ein kleines Molekül abgespalten?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Vergleiche mit der Polykondensation."],"solution":"Nein. Die Monomere werden vollständig addiert; es entsteht kein Nebenprodukt.","competencies":["S"],"operators":["entscheiden"],"sourceLessonId":"chem.q2.2.polymerization","sourceKind":"selfTest"},{"id":"chem.q2.2.polymerization.selftest.2","title":"Voraussetzung im Monomer","difficulty":"basic","prompt":"Welches Strukturmerkmal muss ein Monomer für eine Polymerisation besitzen?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Diese Bindung wird beim Kettenwachstum geöffnet."],"solution":"Eine C=C-Doppelbindung.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.2.polymerization","sourceKind":"selfTest"},{"id":"chem.q2.2.polymerization.selftest.3","title":"Rolle des Initiators","difficulty":"basic","prompt":"Welche Aufgabe hat der Initiator bei der radikalischen Polymerisation?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Ohne ihn beginnt kein Kettenwachstum."],"solution":"Er zerfällt in Radikale, die eine Doppelbindung angreifen und damit das Kettenwachstum starten.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.2.polymerization","sourceKind":"selfTest"},{"id":"chem.q2.2.properties.exercise.1","title":"Kunststoffklassen zuordnen","difficulty":"basic","prompt":"Ordne die Gegenstände den Klassen Thermoplast, Elastomer und Duroplast zu: (a) Gummiband, (b) Steckdosengehäuse aus Phenolharz, (c) Getränkeflasche aus Polyethen.","taskType":"matching","afb":1,"supportedModes":["screen"],"hints":["Denke an Verformbarkeit beim Erwärmen und Rückstellung nach Dehnung."],"solution":"(a) Elastomer. (b) Duroplast. (c) Thermoplast.","competencies":["S"],"operators":["zuordnen"],"sourceLessonId":"chem.q2.2.properties","sourceKind":"exercise","answer":{"kind":"matching","options":["Thermoplast","Elastomer","Duroplast"],"items":[{"id":"a","label":"(a) Gummiband","correct":"Elastomer"},{"id":"b","label":"(b) Steckdosengehäuse aus Phenolharz","correct":"Duroplast"},{"id":"c","label":"(c) Getränkeflasche aus Polyethen","correct":"Thermoplast"}]}},{"id":"chem.q2.2.properties.exercise.2","title":"Verhalten beim Erwärmen","difficulty":"basic","prompt":"Beschreibe, wie sich ein Thermoplast, ein Elastomer und ein Duroplast beim starken Erwärmen verhalten.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Unterscheide Erweichen, Schmelzen und Zersetzen."],"solution":"Ein Thermoplast erweicht und schmilzt schließlich; nach dem Abkühlen ist er wieder fest und kann erneut umgeformt werden. Ein Elastomer schmilzt nicht, sondern zersetzt sich bei hoher Temperatur. Ein Duroplast bleibt bis zur Zersetzung hart und formstabil; er schmilzt nicht.","competencies":["S"],"operators":["beschreiben"],"sourceLessonId":"chem.q2.2.properties","sourceKind":"exercise"},{"id":"chem.q2.2.properties.exercise.3","title":"Thermoplaste umformen","difficulty":"standard","prompt":"Erkläre auf Teilchenebene, warum sich Thermoplaste durch Erwärmen umformen und verschweißen lassen.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die Ketten sind nicht kovalent miteinander verbunden."],"solution":"Thermoplaste bestehen aus unvernetzten Ketten, die nur durch zwischenmolekulare Kräfte zusammengehalten werden. Beim Erwärmen bewegen sich die Ketten stärker; die Kräfte werden überwunden, und die Ketten gleiten aneinander vorbei. Das Material wird formbar, und Ketten zweier Teile können sich an der Kontaktstelle durchdringen. Nach dem Abkühlen wirken die zwischenmolekularen Kräfte wieder, die neue Form bleibt erhalten.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.q2.2.properties","sourceKind":"exercise"},{"id":"chem.q2.2.properties.exercise.4","title":"PE-HD und PE-LD","difficulty":"standard","prompt":"Polyethen hoher Dichte (PE-HD) besitzt kaum verzweigte Ketten, Polyethen niedriger Dichte (PE-LD) viele Seitenverzweigungen. Erkläre, warum PE-HD dichter und fester ist.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Überlege, wie gut sich gerade und verzweigte Ketten aneinanderlegen können."],"solution":"Unverzweigte Ketten können sich dicht und geordnet aneinanderlegen; es entstehen größere kristalline Bereiche. Die Ketten haben viele Kontaktstellen, die Van-der-Waals-Kräfte sind insgesamt stärker. Dadurch ist PE-HD dichter und fester. Verzweigungen in PE-LD halten die Ketten auf Abstand und stören die Ordnung.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.q2.2.properties","sourceKind":"exercise"},{"id":"chem.q2.2.properties.exercise.5","title":"Copolymer oder Blend?","difficulty":"transfer","prompt":"Material A besteht aus Ketten, in denen Ethen- und Vinylacetat-Einheiten abwechselnd oder zufällig verteilt kovalent verknüpft sind. Material B ist eine Mischung aus reinen Polyethen- und reinen Polypropen-Ketten. Ordne beide Materialien den Begriffen Copolymer und Blend zu und begründe.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Prüfe, ob die verschiedenen Monomere in derselben Kette verbaut sind."],"solution":"Material A ist ein Copolymer: Verschiedene Monomerarten sind kovalent in derselben Kette verknüpft. Material B ist ein Blend: Zwei verschiedene Polymere liegen als physikalische Mischung vor, jede Kette besteht nur aus einer Monomerart.","competencies":["S"],"operators":["zuordnen","begründen"],"sourceLessonId":"chem.q2.2.properties","sourceKind":"exercise"},{"id":"chem.q2.2.properties.exercise.6","title":"Werkstoff für einen Pfannengriff","difficulty":"transfer","prompt":"Für den Griff einer Bratpfanne stehen ein Thermoplast und ein Duroplast zur Auswahl. Beurteile die Eignung beider Werkstoffe und nenne einen Nachteil des geeigneteren Werkstoffs.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Der Griff kann beim Kochen deutlich erwärmt werden."],"solution":"Der Duroplast ist geeigneter: Sein engmaschiges Netzwerk verhindert ein Erweichen beim Erwärmen, der Griff bleibt formstabil. Ein Thermoplast könnte bei Wärme weich werden und sich verformen. Nachteile des Duroplasts sind, dass er nicht durch Schmelzen recycelt oder umgeformt werden kann und eher spröde ist.","competencies":["S","B"],"operators":["beurteilen"],"sourceLessonId":"chem.q2.2.properties","sourceKind":"exercise"},{"id":"chem.q2.2.properties.selftest.1","title":"Wiederholt schmelzbar","difficulty":"basic","prompt":"Welche Kunststoffklasse lässt sich wiederholt schmelzen und umformen?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Ihre Ketten sind nicht vernetzt."],"solution":"Thermoplaste.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.2.properties","sourceKind":"selfTest"},{"id":"chem.q2.2.properties.selftest.2","title":"Weitmaschige Vernetzung","difficulty":"basic","prompt":"Welche Eigenschaft verleiht eine weitmaschige Vernetzung einem Kunststoff?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Denke an ein Gummiband."],"solution":"Elastizität: Das Material lässt sich dehnen und kehrt danach in die Ausgangsform zurück.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.2.properties","sourceKind":"selfTest"},{"id":"chem.q2.2.properties.selftest.3","title":"Duroplast erhitzen","difficulty":"basic","prompt":"Warum schmilzt ein Duroplast beim Erhitzen nicht?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die Ketten sind kovalent verknüpft."],"solution":"Die Ketten sind durch kovalente Bindungen zu einem engmaschigen Netzwerk verbunden und können nicht aneinander vorbeigleiten. Bei starkem Erhitzen werden Bindungen gespalten, das Material zersetzt sich.","competencies":["S"],"operators":["begründen"],"sourceLessonId":"chem.q2.2.properties","sourceKind":"selfTest"},{"id":"chem.q2.2.sustainability.exercise.1","title":"Verwertungswege zuordnen","difficulty":"basic","prompt":"Ordne die Verfahren den Begriffen werkstoffliches, rohstoffliches und energetisches Recycling beziehungsweise Verwertung zu: (a) Gesammelte PET-Flaschen werden gemahlen, gereinigt und zu Fasern versponnen. (b) Kunststoffabfälle werden durch Pyrolyse in ein Öl aus kleineren Molekülen zerlegt. (c) Kunststoffabfälle werden in einer Anlage verbrannt, die Wärme wird genutzt.","taskType":"matching","afb":2,"supportedModes":["screen"],"hints":["Prüfe, ob das Polymer, die Ausgangsstoffe oder nur die Energie genutzt werden."],"solution":"(a) Werkstoffliches Recycling. (b) Rohstoffliches Recycling. (c) Energetische Verwertung.","competencies":["S"],"operators":["zuordnen"],"sourceLessonId":"chem.q2.2.sustainability","sourceKind":"exercise","answer":{"kind":"matching","options":["werkstoffliches Recycling","rohstoffliches Recycling","energetische Verwertung"],"items":[{"id":"a","label":"(a) PET-Flaschen werden zu Fasern versponnen","correct":"werkstoffliches Recycling"},{"id":"b","label":"(b) Pyrolyse zu einem Öl","correct":"rohstoffliches Recycling"},{"id":"c","label":"(c) Verbrennung mit Wärmenutzung","correct":"energetische Verwertung"}]}},{"id":"chem.q2.2.sustainability.exercise.2","title":"Rezyklatanteil berechnen","difficulty":"basic","prompt":"Ein Hersteller verarbeitet 8,0 t Kunststoff, davon 2,4 t Rezyklat. Berechne den Massenanteil des Rezyklats.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["w = m(Anteil) / m(Gesamt) · 100 %"],"solution":"w = 2,4 t / 8,0 t · 100 % = 30 %.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q2.2.sustainability","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"w","label":"Massenanteil Rezyklat","value":30,"unit":"%","tolerance":{"absolute":0.5}}]}},{"id":"chem.q2.2.sustainability.exercise.3","title":"Grenzen des werkstofflichen Recyclings","difficulty":"standard","prompt":"Erläutere zwei Gründe, warum Rezyklat aus werkstofflichem Recycling oft schlechtere Eigenschaften hat als Neuware.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Denke an die Ketten selbst und an fremde Stoffe im Material."],"solution":"Bei Nutzung und erneuter Verarbeitung können Ketten durch Wärme, Licht und mechanische Belastung gespalten werden; kürzere Ketten verringern die Festigkeit. Außerdem gelangen Fremdkunststoffe, Additive und Verschmutzungen ins Rezyklat. Unverträgliche Polymere mischen sich schlecht und bilden Schwachstellen im Material.","competencies":["S"],"operators":["erläutern"],"sourceLessonId":"chem.q2.2.sustainability","sourceKind":"exercise"},{"id":"chem.q2.2.sustainability.exercise.4","title":"Bio-PE","difficulty":"standard","prompt":"„Bio-Polyethen“ wird aus Ethanol hergestellt, das aus Zuckerrohr gewonnen wird. Begründe, ob dieses Material biologisch abbaubar ist.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Vergleiche die Molekülstruktur mit Polyethen aus Erdöl."],"solution":"Bio-Polyethen ist chemisch identisch mit Polyethen aus Erdöl; es besteht aus denselben langen C–C-Ketten. Die biobasierte Herkunft ändert die Struktur nicht. Es ist daher genauso wenig biologisch abbaubar wie fossiles Polyethen. Biobasiert beschreibt die Rohstoffquelle, nicht das Abbauverhalten.","competencies":["S","B"],"operators":["begründen"],"sourceLessonId":"chem.q2.2.sustainability","sourceKind":"exercise"},{"id":"chem.q2.2.sustainability.exercise.5","title":"Zwei Getränkeverpackungen vergleichen","difficulty":"transfer","prompt":"Fiktive Daten: Eine Mehrweg-Glasflasche (0,70 L) verursacht in der Herstellung 400 g CO₂-Äquivalente und wird 20-mal befüllt; pro Umlauf kommen 40 g für Transport und Reinigung hinzu. Eine Einweg-PET-Flasche (1,5 L) verursacht insgesamt 60 g. Berechne die Emissionen je Liter Füllvolumen und beurteile, ob damit ein fairer Vergleich vorliegt.","taskType":"structured","afb":3,"supportedModes":["screen","handwriting"],"hints":["Verteile die Herstellungsemissionen der Glasflasche auf alle Umläufe.","Ein fairer Vergleich braucht dieselbe Funktion und Systemgrenze."],"solution":"Glas: 400 g / 20 + 40 g = 60 g pro Befüllung; 60 g / 0,70 L ≈ 86 g·L⁻¹. PET: 60 g / 1,5 L = 40 g·L⁻¹. Nach diesen Daten schneidet PET besser ab. Der Vergleich ist aber nur eingeschränkt fair: Es ist offen, ob beide Werte dieselbe Systemgrenze haben, etwa Transportentfernungen, Recyclingquote der PET-Flasche und Entsorgung. Auch die Zahl der Umläufe ist eine Annahme, die das Ergebnis stark beeinflusst.","competencies":["E","B"],"operators":["berechnen","beurteilen"],"sourceLessonId":"chem.q2.2.sustainability","sourceKind":"exercise"},{"id":"chem.q2.2.sustainability.exercise.6","title":"PET chemisch recyceln","difficulty":"transfer","prompt":"PET kann durch Hydrolyse der Esterbindungen wieder in Terephthalsäure und Ethan-1,2-diol zerlegt werden. Bewerte dieses rohstoffliche Recycling im Vergleich zum werkstofflichen Recycling anhand von zwei Kriterien.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Mögliche Kriterien sind Produktqualität und Energiebedarf."],"solution":"Qualität: Die zurückgewonnenen Monomere können gereinigt und zu neuwertigem PET polymerisiert werden; Kettenabbau und Fremdstoffe spielen kaum eine Rolle. Das spricht für das rohstoffliche Verfahren. Energie und Aufwand: Die Spaltung, Reinigung und erneute Polymerisation benötigen deutlich mehr Energie und Chemikalien als Mahlen und Umschmelzen. Welches Verfahren insgesamt vorzuziehen ist, hängt von der Sortenreinheit des Abfalls und von belastbaren Energiedaten ab.","competencies":["S","B"],"operators":["bewerten"],"sourceLessonId":"chem.q2.2.sustainability","sourceKind":"exercise"},{"id":"chem.q2.2.sustainability.selftest.1","title":"Energetische Verwertung","difficulty":"basic","prompt":"Was geht bei der energetischen Verwertung von Kunststoffen verloren?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Vergleiche mit dem werkstofflichen Recycling."],"solution":"Der Werkstoff selbst: Das Polymer wird verbrannt; genutzt wird nur die freigesetzte Energie.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.2.sustainability","sourceKind":"selfTest"},{"id":"chem.q2.2.sustainability.selftest.2","title":"Systemgrenze","difficulty":"basic","prompt":"Was legt die Systemgrenze bei einer ökologischen Bewertung fest?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Denke an den Lebensweg eines Produkts."],"solution":"Welche Abschnitte des Lebenswegs, etwa Herstellung, Transport, Nutzung und Entsorgung, in die Bewertung einbezogen werden.","competencies":["B"],"operators":["angeben"],"sourceLessonId":"chem.q2.2.sustainability","sourceKind":"selfTest"},{"id":"chem.q2.2.sustainability.selftest.3","title":"Biobasiert und abbaubar","difficulty":"basic","prompt":"Ist ein biobasierter Kunststoff automatisch biologisch abbaubar?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Unterscheide Herkunft und Struktur."],"solution":"Nein. Biobasiert beschreibt die Rohstoffherkunft. Ob ein Kunststoff abbaubar ist, hängt von seiner Struktur und den Abbaubedingungen ab.","competencies":["B"],"operators":["entscheiden"],"sourceLessonId":"chem.q2.2.sustainability","sourceKind":"selfTest"},{"id":"chem.q2.3.aromatics.exercise.basic-ring","title":"Aromaten erkennen","difficulty":"basic","prompt":"Ein sechsgliedriger Ring besitzt drei alternierende Doppelbindungen. Welche zusätzliche Modellvorstellung brauchst du, um Benzol angemessen zu beschreiben?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Berücksichtige, dass die π-Elektronen nicht jeweils nur einer festen Doppelbindung zugeordnet sind."],"solution":"Benzol wird als planarer, konjugierter Ring mit sechs delokalisierten π-Elektronen beschrieben. Die Kekulé-Formeln sind mesomere Grenzstrukturen, keine wechselnden Einzelzustände.","competencies":["S"],"operators":["beschreiben","erläutern"],"sourceLessonId":"chem.q2.3.aromatics","sourceKind":"exercise"},{"id":"chem.q2.3.aromatics.exercise.basic-reaction","title":"Bromierung von Benzol","difficulty":"basic","prompt":"Benzol reagiert mit Brom unter geeigneten katalytischen Bedingungen zu Brombenzol. Ordne den Reaktionstyp ein und begründe, warum der Ring erhalten bleibt.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Achte darauf, ob ein H-Atom ersetzt oder an eine Doppelbindung addiert wird.","Die Aromatizität kann nach einem Zwischenschritt wiederhergestellt werden."],"solution":"Es handelt sich um eine elektrophile aromatische Substitution: Ein H-Atom des Rings wird durch Br ersetzt. Nach der vorübergehenden Störung des π-Systems wird die Aromatizität wiederhergestellt.","competencies":["S"],"operators":["zuordnen","begründen"],"sourceLessonId":"chem.q2.3.aromatics","sourceKind":"exercise"},{"id":"chem.q2.3.aromatics.exercise.standard-nitration","title":"Nitrierung formulieren","difficulty":"standard","prompt":"Formuliere das Reaktionsschema der Nitrierung von Benzol zu Nitrobenzol und nenne das Elektrophil.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Schwefelsäure unterstützt die Bildung des Nitronium-Ions.","Die Nettogleichung enthält Salpetersäure und Benzol als Ausgangsstoffe."],"solution":"C₆H₆ + HNO₃ → C₆H₅NO₂ + H₂O (konzentrierte H₂SO₄ als Katalysator/reaktionsfördernde Säure). Das Elektrophil ist NO₂⁺, das Nitronium-Ion.","competencies":["S","K"],"operators":["formulieren","benennen"],"sourceLessonId":"chem.q2.3.aromatics","sourceKind":"exercise"},{"id":"chem.q2.3.aromatics.exercise.standard-mechanism","title":"Schritte der elektrophilen Substitution","difficulty":"standard","prompt":"Ordne die drei Grundschritte der elektrophilen aromatischen Substitution: Elektrophilbildung, Angriff des Rings, Protonenabgabe.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Nach dem Angriff entsteht ein nicht-aromatisches Zwischenprodukt.","Der letzte Schritt stellt das delokalisierte π-System wieder her."],"solution":"Zuerst wird das Elektrophil gebildet. Dann greift das π-System des Rings an; ein σ-Komplex entsteht und die Aromatizität ist vorübergehend aufgehoben. Schließlich wird H⁺ abgespalten. Das π-System wird wiederhergestellt und das substituierte Aromat entsteht.","competencies":["S","E"],"operators":["ordnen","erläutern"],"sourceLessonId":"chem.q2.3.aromatics","sourceKind":"exercise"},{"id":"chem.q2.3.aromatics.exercise.transfer-substituent","title":"Substituenteneffekt kontextbezogen prüfen","difficulty":"transfer","prompt":"Ein Material vergleicht die Zweitsubstitution von Benzol und einem bereits substituierten Aromaten. Welche Informationen brauchst du, bevor du eine bevorzugte Position begründest?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Prüfe, welcher Substituent bereits vorhanden ist und welche Reaktion untersucht wird.","Nutze dirigierende Regeln nur, wenn sie für den Jahrgang verlangt oder im Material gegeben sind."],"solution":"Du brauchst die Struktur und den elektronischen Einfluss des vorhandenen Substituenten sowie Reaktionsbedingungen und die im Unterricht/Erlass vorausgesetzten Regeln. Dirigierende Effekte darfst du nur im verlangten curricularen Umfang anwenden. Ohne diese Angaben ist eine konkrete Positionsvorhersage nicht begründet.","competencies":["E","B"],"operators":["prüfen","begründen"],"sourceLessonId":"chem.q2.3.aromatics","sourceKind":"exercise"},{"id":"chem.q2.3.aromatics.exercise.transfer-addition","title":"Benzol und Bromwasser","difficulty":"transfer","prompt":"Eine Behauptung lautet: „Benzol entfärbt Bromwasser wie ein Alken, weil es drei Doppelbindungen besitzt.“ Beurteile sie.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Unterscheide lokale Doppelbindungen in einer Grenzformel vom delokalisierten aromatischen System.","Berücksichtige den Energiegewinn durch Erhalt der Aromatizität."],"solution":"Die Behauptung ist falsch. Benzol besitzt ein delokalisiertes aromatisches π-System. Eine Addition würde die Aromatizität dauerhaft aufheben. Unter üblichen Bedingungen reagiert Benzol daher nicht wie ein Alken durch einfache Addition; typische Reaktionen sind Substitutionen, bei denen die Aromatizität wiederhergestellt wird.","competencies":["S","B"],"operators":["beurteilen","begründen"],"sourceLessonId":"chem.q2.3.aromatics","sourceKind":"exercise"},{"id":"chem.q2.3.aromatics.selftest.pi","title":"π-Elektronen im Benzol","difficulty":"basic","prompt":"Wie sind die sechs π-Elektronen im Benzol verteilt?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie gehören zum gesamten Ringsystem."],"solution":"Sie sind über den Ring delokalisiert.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.3.aromatics","sourceKind":"selfTest"},{"id":"chem.q2.3.aromatics.selftest.reaction","title":"Typische Reaktion des Benzols","difficulty":"basic","prompt":"Welcher Reaktionstyp ist typisch für Benzol?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Ein H am Ring wird ersetzt."],"solution":"Elektrophile aromatische Substitution.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.3.aromatics","sourceKind":"selfTest"},{"id":"chem.q2.3.aromatics.selftest.sigma","title":"Nach dem σ-Komplex","difficulty":"basic","prompt":"Was geschieht nach Bildung des σ-Komplexes?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Ein Proton wird abgegeben."],"solution":"Durch Protonenabgabe wird das delokalisierte π-System und damit die Aromatizität wiederhergestellt.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.3.aromatics","sourceKind":"selfTest"},{"id":"chem.q2.4.organic-materials.exercise.1","title":"PLA einordnen","difficulty":"basic","prompt":"Gib das Monomer von Polymilchsäure (PLA) an und nenne die Bindung, über die die Bausteine verknüpft sind.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Milchsäure enthält eine Hydroxy- und eine Carboxygruppe."],"solution":"Monomer: Milchsäure (2-Hydroxypropansäure). Die Bausteine sind über Esterbindungen verknüpft; PLA ist ein Polyester.","competencies":["S"],"operators":["angeben","nennen"],"sourceLessonId":"chem.q2.4.organic-materials","sourceKind":"exercise"},{"id":"chem.q2.4.organic-materials.exercise.2","title":"Vulkanisation","difficulty":"basic","prompt":"Nenne die Verknüpfungen, die bei der Vulkanisation von Kautschuk entstehen, und beschreibe ihre Wirkung auf die Eigenschaften.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Bei der Vulkanisation wird Schwefel eingesetzt."],"solution":"Es entstehen Schwefelbrücken zwischen den Kautschukketten. Die weitmaschige Vernetzung verhindert, dass die Ketten dauerhaft aneinander vorbeigleiten. Das Material wird elastisch und formbeständig und klebt nicht mehr.","competencies":["S"],"operators":["nennen","beschreiben"],"sourceLessonId":"chem.q2.4.organic-materials","sourceKind":"exercise"},{"id":"chem.q2.4.organic-materials.exercise.3","title":"PLA-Bildung formulieren","difficulty":"standard","prompt":"Formuliere die Bildung von PLA aus Milchsäure (HO–CH(CH₃)–COOH) als Polykondensation mit Wiederholungseinheit und erkläre, warum hier ein einziges Monomer genügt.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Ein Milchsäure-Molekül trägt beide für eine Esterbindung nötigen Gruppen."],"solution":"n HO–CH(CH₃)–COOH → H–[O–CH(CH₃)–CO]ₙ–OH + (n−1) H₂O; Wiederholungseinheit [–O–CH(CH₃)–CO–]ₙ. Jedes Milchsäure-Molekül besitzt eine Hydroxy- und eine Carboxygruppe. Die Hydroxygruppe eines Moleküls kann mit der Carboxygruppe des nächsten verestert werden; so wächst die Kette aus nur einer Monomerart.","competencies":["S","K"],"operators":["formulieren","erklären"],"sourceLessonId":"chem.q2.4.organic-materials","sourceKind":"exercise"},{"id":"chem.q2.4.organic-materials.exercise.4","title":"Weich- und Hartgummi","difficulty":"standard","prompt":"Mit wenig Schwefel vulkanisierter Kautschuk ist weich und elastisch, mit viel Schwefel entsteht harter, kaum dehnbarer Hartgummi. Erkläre diesen Unterschied.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Vergleiche den Abstand der Vernetzungsstellen."],"solution":"Wenig Schwefel erzeugt wenige Schwefelbrücken, das Netzwerk ist weitmaschig. Die Kettenabschnitte zwischen den Vernetzungsstellen sind lang und beweglich; das Material lässt sich dehnen und kehrt zurück. Viel Schwefel erzeugt ein engmaschiges Netzwerk. Die Kettenabschnitte sind kurz und kaum beweglich, das Material wird hart.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.q2.4.organic-materials","sourceKind":"exercise"},{"id":"chem.q2.4.organic-materials.exercise.5","title":"Viskose und Baumwolle","difficulty":"transfer","prompt":"Viskose und Baumwolle bestehen beide aus Cellulose. Viskosefasern verlieren im nassen Zustand aber deutlich mehr an Festigkeit. Erkläre diesen Unterschied mit der Herstellung der Viskose.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Bei der Viskoseherstellung wird Cellulose gelöst und regeneriert.","Denke an Kettenlänge und Ordnung der Ketten."],"solution":"Bei der Viskoseherstellung wird Cellulose chemisch gelöst und wieder ausgefällt. Dabei werden die Ketten verkürzt, und sie lagern sich weniger geordnet zusammen; die kristallinen Bereiche sind kleiner. In den ungeordneten Bereichen kann Wasser leicht eindringen und Wasserstoffbrücken zwischen den Ketten durch Wasserstoffbrücken zum Wasser ersetzen. Die Ketten halten im nassen Zustand weniger fest zusammen, die Faser wird schwächer.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.q2.4.organic-materials","sourceKind":"exercise"},{"id":"chem.q2.4.organic-materials.exercise.6","title":"Kompostierbarer PLA-Becher","difficulty":"transfer","prompt":"Ein Trinkbecher aus PLA trägt den Hinweis „kompostierbar“. Beurteile, ob der Becher im Gartenkompost oder in der Natur rasch abgebaut wird, und nenne die Angaben, die eine solche Aussage stützen müssten.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Esterbindungen werden zuerst hydrolysiert, bevor Mikroorganismen die Bruchstücke abbauen.","Die Geschwindigkeit hängt stark von Temperatur und Feuchtigkeit ab."],"solution":"PLA wird abgebaut, indem zunächst die Esterbindungen hydrolysiert werden; das läuft bei hoher Temperatur und Feuchte deutlich schneller. Unter den Bedingungen industrieller Kompostierung, etwa bei rund 60 °C, zerfällt PLA innerhalb weniger Monate. Im Gartenkompost und in der Natur sind die Temperaturen meist zu niedrig; der Abbau dauert dort sehr viel länger. Die Angabe „kompostierbar“ ist daher nur mit Prüfbedingungen aussagekräftig: Temperatur, Feuchte, Dauer und das zugrunde liegende Prüfverfahren.","competencies":["S","B"],"operators":["beurteilen","nennen"],"sourceLessonId":"chem.q2.4.organic-materials","sourceKind":"exercise"},{"id":"chem.q2.4.organic-materials.selftest.1","title":"Stoffklasse von PLA","difficulty":"basic","prompt":"Zu welcher Polymerklasse gehört PLA?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Betrachte die Bindung zwischen den Bausteinen."],"solution":"Zu den Polyestern.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.4.organic-materials","sourceKind":"selfTest"},{"id":"chem.q2.4.organic-materials.selftest.2","title":"Vernetzung im Gummi","difficulty":"basic","prompt":"Welche Brücken verbinden die Ketten in vulkanisiertem Kautschuk?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie entstehen durch Schwefel."],"solution":"Schwefelbrücken.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.4.organic-materials","sourceKind":"selfTest"},{"id":"chem.q2.4.organic-materials.selftest.3","title":"Ausgangsstoff der Viskose","difficulty":"basic","prompt":"Aus welchem Naturstoff wird Viskose hergestellt?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Viskose ist eine regenerierte Faser."],"solution":"Aus Cellulose.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q2.4.organic-materials","sourceKind":"selfTest"},{"id":"chem.q3.1.applications.exercise.basic-haber","title":"Ammoniaksynthese formulieren","difficulty":"basic","prompt":"Formuliere die ausgeglichene Reaktionsgleichung der Ammoniaksynthese aus Stickstoff und Wasserstoff.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Beachte, dass Stickstoff und Wasserstoff als zweiatomige Moleküle vorliegen.","Gleiche N und H aus."],"solution":"N₂(g) + 3 H₂(g) ⇌ 2 NH₃(g).","competencies":["S"],"operators":["formulieren"],"sourceLessonId":"chem.q3.1.applications","sourceKind":"exercise"},{"id":"chem.q3.1.applications.exercise.basic-exothermic","title":"Wärme in der Reaktionsgleichung","difficulty":"basic","prompt":"Die Hinreaktion der Ammoniaksynthese ist exotherm. Auf welcher Seite steht Wärme in einer schematischen Gleichung für die Hinreaktion?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Exotherme Reaktionen geben Wärme ab."],"solution":"Wärme steht bei einer exothermen Hinreaktion auf der Produktseite: N₂ + 3 H₂ ⇌ 2 NH₃ + Wärme.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.1.applications","sourceKind":"exercise"},{"id":"chem.q3.1.applications.exercise.standard-conditions","title":"Prozessbedingungen erklären","difficulty":"standard","prompt":"Erkläre, warum die Ammoniaksynthese bei technischen Bedingungen nicht einfach bei möglichst niedriger Temperatur durchgeführt wird, obwohl die Hinreaktion exotherm ist.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Niedrige Temperatur begünstigt das Gleichgewicht, kann aber die Reaktionsgeschwindigkeit senken.","Technische Verfahren müssen Umsatz und Zeitaufwand abwägen."],"solution":"Niedrige Temperatur begünstigt zwar die exotherme Produktseite, verlangsamt aber die Reaktion. Die technische Prozessführung wägt deshalb Gleichgewichtsausbeute und Reaktionsgeschwindigkeit ab; ein Katalysator beschleunigt die Einstellung, ändert aber die Gleichgewichtslage nicht.","competencies":["S","E"],"operators":["erläutern","begründen"],"sourceLessonId":"chem.q3.1.applications","sourceKind":"exercise"},{"id":"chem.q3.1.applications.exercise.standard-ester","title":"Esterausbeute begründen","difficulty":"standard","prompt":"Die Veresterung einer Carbonsäure mit einem Alkanol ist umkehrbar. Nenne eine Maßnahme, mit der sich die Estermenge im Gleichgewicht erhöhen lässt, und begründe die Richtung der Verschiebung.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Nutze ein Edukt im Überschuss oder entferne ein Produkt.","Erkläre die Richtung der Gleichgewichtsverschiebung."],"solution":"Ein Edukt kann im Überschuss eingesetzt oder Wasser beziehungsweise Ester entfernt werden. Das Gleichgewicht verschiebt sich dadurch zur Produktseite, sofern die Maßnahme unter den Prozessbedingungen wirksam ist.","competencies":["S","E"],"operators":["begründen"],"sourceLessonId":"chem.q3.1.applications","sourceKind":"exercise"},{"id":"chem.q3.1.applications.exercise.transfer-evaluate","title":"Bedingungen vergleichen","difficulty":"transfer","prompt":"Ein Material vergleicht zwei Verfahren: Verfahren A arbeitet bei niedriger Temperatur und erreicht hohen Gleichgewichtsumsatz, Verfahren B reagiert bei höherer Temperatur schneller, erreicht aber einen geringeren Gleichgewichtsumsatz. Welche weiteren Kriterien brauchst du für eine Prozessbewertung?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Ein Verfahren wird nicht allein über die Gleichgewichtsausbeute bewertet.","Berücksichtige Energiebedarf, Sicherheit und Stoffkreisläufe."],"solution":"Du brauchst unter anderem Reaktionszeit und Durchsatz, Energiebedarf, Druck, Katalysator, Sicherheit, Trennaufwand, Rohstoffnutzung und Rückführung unverbrauchter Stoffe. Erst anhand gewichteter Kriterien lässt sich der Prozess beurteilen.","competencies":["E","B"],"operators":["vergleichen","bewerten"],"sourceLessonId":"chem.q3.1.applications","sourceKind":"exercise"},{"id":"chem.q3.1.applications.exercise.transfer-mw","title":"Produktentfernung beim Haber-Bosch-Verfahren","difficulty":"transfer","prompt":"Bei N₂(g) + 3 H₂(g) ⇌ 2 NH₃(g) wird NH₃ kontinuierlich aus dem Reaktionsgemisch entfernt. Erkläre die erwartete Richtung der anfänglichen Nettoreaktion mithilfe von Qc und Kc.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die Entfernung senkt die Produktkonzentration und damit zunächst Qc.","Vergleiche Qc mit Kc bei gleicher Temperatur."],"solution":"Durch das Entfernen von NH₃ sinkt Qc zunächst unter Kc. Die Nettoreaktion läuft zur Produktseite, bis sich ein neues Gleichgewicht einstellt.","competencies":["S","E"],"operators":["ableiten","begründen"],"sourceLessonId":"chem.q3.1.applications","sourceKind":"exercise"},{"id":"chem.q3.1.applications.selftest.haber","title":"Druck und Ammoniaksynthese","difficulty":"basic","prompt":"Welche Seite der Ammoniaksynthese wird bei Druckerhöhung begünstigt?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Vergleiche die Zahl gasförmiger Teilchen."],"solution":"Die Produktseite mit zwei statt vier Mol Gasteilchen pro Reaktionsumsatz.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.1.applications","sourceKind":"selfTest"},{"id":"chem.q3.1.applications.selftest.catalyst","title":"Katalysator und Ausbeute","difficulty":"basic","prompt":"Ändert ein Katalysator die Gleichgewichtsausbeute?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Er wirkt auf die Geschwindigkeit."],"solution":"Nein. Er beschleunigt die Einstellung, verändert aber die Gleichgewichtslage nicht.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.1.applications","sourceKind":"selfTest"},{"id":"chem.q3.1.applications.selftest.ester","title":"Estermenge erhöhen","difficulty":"basic","prompt":"Nenne eine Möglichkeit, die Estermenge im Gleichgewicht zu erhöhen.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Le Chatelier anwenden."],"solution":"Einen Eduktstoff im Überschuss einsetzen oder ein Produkt entfernen.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.1.applications","sourceKind":"selfTest"},{"id":"chem.q3.1.mwg.exercise.basic-dynamic","title":"Dynamisches Gleichgewicht beschreiben","difficulty":"basic","prompt":"In einem geschlossenen Gefäß bleiben die Konzentrationen von Edukten und Produkten konstant. Bedeutet das, dass die Reaktionen aufgehört haben? Begründe.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Unterscheide konstante Konzentrationen von stillstehenden Teilchen."],"solution":"Nein. Im dynamischen Gleichgewicht laufen Hin- und Rückreaktion weiter, aber gleich schnell. Deshalb bleiben die Konzentrationen makroskopisch konstant.","competencies":["S"],"operators":["begründen"],"sourceLessonId":"chem.q3.1.mwg","sourceKind":"exercise"},{"id":"chem.q3.1.mwg.exercise.basic-expression","title":"MWG-Ausdruck aufstellen","difficulty":"basic","prompt":"Stelle für N₂(g) + 3 H₂(g) ⇌ 2 NH₃(g) den schulischen Konzentrationsausdruck Kc auf.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Die stöchiometrischen Koeffizienten werden zu Exponenten.","Produkte stehen im Zähler, Edukte im Nenner."],"solution":"Kc = c(NH₃)² / (c(N₂)·c(H₂)³).","competencies":["S"],"operators":["formulieren"],"sourceLessonId":"chem.q3.1.mwg","sourceKind":"exercise"},{"id":"chem.q3.1.mwg.exercise.standard-kc","title":"Gleichgewichtskonstante berechnen","difficulty":"standard","prompt":"Für 2 NO₂(g) ⇌ N₂O₄(g) gelten im Gleichgewicht c(NO₂)=0,20 mol·L⁻¹ und c(N₂O₄)=0,50 mol·L⁻¹. Berechne Kc nach dem üblichen Konzentrationsausdruck.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Schreibe Kc = c(N₂O₄)/c(NO₂)².","Setze beide Gleichgewichtskonzentrationen ein."],"solution":"Kc,Schule = c(N₂O₄)/c(NO₂)² = 0,50 mol·L⁻¹/(0,20 mol·L⁻¹)² = 12,5 L·mol⁻¹. Bei Verwendung normierter Aktivitäten ist die thermodynamische Konstante dimensionslos.","competencies":["S","E"],"operators":["berechnen"],"sourceLessonId":"chem.q3.1.mwg","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"kc","label":"Kc","value":12.5,"unit":"L·mol⁻¹"}]}},{"id":"chem.q3.1.mwg.exercise.standard-ice","title":"Gleichgewichtskonzentration berechnen","difficulty":"standard","prompt":"In einem geschlossenen Gefäß liegt anfangs nur N₂O₄ vor: c₀(N₂O₄)=0,50 mol·L⁻¹ und c₀(NO₂)=0. Im Gleichgewicht sind 0,20 mol·L⁻¹ NO₂ vorhanden. Berechne cₑq(N₂O₄) für N₂O₄(g) ⇌ 2 NO₂(g).","taskType":"numeric","afb":2,"supportedModes":["screen","handwriting"],"hints":["Aus 1 mol N₂O₄ entstehen 2 mol NO₂.","Berechne zuerst die umgesetzte N₂O₄-Konzentration."],"solution":"Aus N₂O₄ ⇌ 2 NO₂ folgt: Für 0,20 mol·L⁻¹ gebildetes NO₂ werden 0,10 mol·L⁻¹ N₂O₄ verbraucht. Daher ist cₑq(N₂O₄)=0,50−0,10=0,40 mol·L⁻¹.","competencies":["S","E"],"operators":["berechnen"],"sourceLessonId":"chem.q3.1.mwg","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"c","label":"cₑq(N₂O₄)","value":0.4,"unit":"mol·L⁻¹"}]}},{"id":"chem.q3.1.mwg.exercise.transfer-data","title":"Messkurve interpretieren","difficulty":"transfer","prompt":"Die Abbildung zeigt, wie die Konzentration eines Produkts zunächst steigt und dann ein Plateau erreicht. Erkläre, was die Kurve über das System aussagt und was sie allein nicht beweist.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Ein Plateau zeigt eine makroskopisch konstante Konzentration.","Ein Gleichgewicht setzt gleich schnelle Hin- und Rückreaktion voraus."],"solution":"Die Konzentration ändert sich im Messzeitraum am Plateau kaum noch. Das ist mit einem dynamischen Gleichgewicht vereinbar, beweist es allein aber nicht. Weitere Daten oder ein geeignetes Modell müssen ausschließen, dass die Reaktion beispielsweise beendet oder ein Stoff aufgebraucht ist.","competencies":["E","B"],"operators":["interpretieren","beurteilen"],"sourceLessonId":"chem.q3.1.mwg","sourceKind":"exercise","figures":[{"file":"concentration-plateau.svg","alt":"Konzentration eines Produkts gegen die Zeit von 0 bis 120 s: Die Kurve steigt anfangs steil und nähert sich ab etwa 80 s einem konstanten Wert von etwa 0,6 mol pro Liter.","placement":"prompt"}]},{"id":"chem.q3.1.mwg.exercise.transfer-equilibrium","title":"Reaktionsrichtung aus Qc und Kc ableiten","difficulty":"transfer","prompt":"Für eine Reaktion gilt bei festgelegter Temperatur Kc=4. Der aktuelle Reaktionsquotient beträgt Qc=1. In welche Richtung läuft die Nettoreaktion zunächst? Begründe mit dem Vergleich von Qc und Kc.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Vergleiche Qc mit Kc.","Bei Qc < Kc ist der Produktanteil im Vergleich zum Gleichgewicht zu klein."],"solution":"Qc<Kc. Der aktuelle Produktanteil ist im Verhältnis zur Gleichgewichtszusammensetzung zu klein; die Nettoreaktion läuft zunächst in Richtung Produkte.","competencies":["S","E"],"operators":["ableiten","begründen"],"sourceLessonId":"chem.q3.1.mwg","sourceKind":"exercise"},{"id":"chem.q3.1.mwg.selftest.dynamic","title":"Dynamisches Gleichgewicht","difficulty":"basic","prompt":"Wann ist ein dynamisches Gleichgewicht erreicht?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Vergleiche Hin- und Rückreaktionsgeschwindigkeit."],"solution":"Wenn Hin- und Rückreaktion gleich schnell ablaufen.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.1.mwg","sourceKind":"selfTest"},{"id":"chem.q3.1.mwg.selftest.kc","title":"Aufbau des MWG","difficulty":"basic","prompt":"Wo stehen Produkte im üblichen MWG-Ausdruck?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Nutze die allgemeine Reaktionsgleichung."],"solution":"Im Zähler; ihre stöchiometrischen Koeffizienten werden Exponenten.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.1.mwg","sourceKind":"selfTest"},{"id":"chem.q3.1.mwg.selftest.qc","title":"Qc kleiner als Kc","difficulty":"basic","prompt":"Was bedeutet Qc < Kc bei gleicher Temperatur?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Das System enthält relativ zu wenig Produkt."],"solution":"Die Nettoreaktion läuft zunächst in Richtung Produkte.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.1.mwg","sourceKind":"selfTest"},{"id":"chem.q3.1.shifts.exercise.basic-concentration","title":"Konzentration ändern","difficulty":"basic","prompt":"Für N₂(g) + 3 H₂(g) ⇌ 2 NH₃(g): Beschreibe die anfängliche Verschiebungsrichtung, wenn H₂ zugegeben wird. Wie ändert sie sich, wenn stattdessen NH₃ zugegeben wird?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die Zugabe erhöht die Konzentration eines Edukts.","Das System reagiert so, dass ein Teil der Störung abgebaut wird."],"solution":"Bei Zugabe von H₂ läuft die Nettoreaktion zunächst nach rechts und bildet NH₃. Bei Zugabe von NH₃ läuft sie zunächst nach links und bildet N₂ und H₂. In beiden Fällen reagiert das System so, dass ein Teil der Konzentrationsänderung abgebaut wird.","competencies":["S"],"operators":["ableiten"],"sourceLessonId":"chem.q3.1.shifts","sourceKind":"exercise"},{"id":"chem.q3.1.shifts.exercise.basic-catalyst","title":"Katalysatorwirkung beschreiben","difficulty":"basic","prompt":"Was verändert ein Katalysator in einem Gleichgewichtssystem? Nenne auch, welche Gleichgewichtsgrößen er nicht verändert.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Er beeinflusst die Geschwindigkeit beider Reaktionsrichtungen."],"solution":"Ein Katalysator beschleunigt Hin- und Rückreaktion und lässt das Gleichgewicht schneller erreichen. Er verändert weder Kc bei gegebener Temperatur noch die Gleichgewichtslage.","competencies":["S"],"operators":["erläutern"],"sourceLessonId":"chem.q3.1.shifts","sourceKind":"exercise"},{"id":"chem.q3.1.shifts.exercise.standard-pressure","title":"Druckeinfluss bestimmen","difficulty":"standard","prompt":"Bei N₂(g) + 3 H₂(g) ⇌ 2 NH₃(g) wird das Volumen verkleinert. Bestimme die Richtung der Verschiebung und begründe mit der Teilchenzahl gasförmiger Stoffe.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Links stehen vier Mol Gasteilchen pro Reaktionsumsatz, rechts zwei.","Eine Druckerhöhung begünstigt die Seite mit weniger Gasteilchen."],"solution":"Das Gleichgewicht verschiebt sich nach rechts, zur NH₃-Seite mit weniger Gasteilchen. Die Volumenverkleinerung erhöht den Druck; die Störung wird durch die Seite mit der kleineren Gasstoffmenge teilweise abgebaut.","competencies":["S","E"],"operators":["bestimmen","begründen"],"sourceLessonId":"chem.q3.1.shifts","sourceKind":"exercise"},{"id":"chem.q3.1.shifts.exercise.standard-temperature","title":"Temperaturwirkung begründen","difficulty":"standard","prompt":"Die Hinreaktion eines Gleichgewichts ist exotherm. Begründe, in welche Richtung sich das Gleichgewicht bei einer Temperaturerhöhung verschiebt und ob sich Kc ändert.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Behandle Wärme bei einer exothermen Hinreaktion wie ein Produkt.","Erhöhe ein Produkt und prüfe die Gegenreaktion."],"solution":"Eine Temperaturerhöhung begünstigt die endotherme Rückreaktion. Das Gleichgewicht verschiebt sich nach links, zu den Edukten. Kc ändert sich mit der Temperatur.","competencies":["S","E"],"operators":["ableiten","begründen"],"sourceLessonId":"chem.q3.1.shifts","sourceKind":"exercise"},{"id":"chem.q3.1.shifts.exercise.transfer-kc","title":"Änderung von Q und K unterscheiden","difficulty":"transfer","prompt":"Zu einem Gleichgewichtsgemisch wird bei konstanter Temperatur ein Edukt zugegeben. Ändert sich dadurch sofort Kc? Begründe mit Kc und Qc.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Kc hängt bei einer bestimmten Reaktion von der Temperatur ab.","Die Stoffzugabe verändert zunächst die aktuellen Konzentrationen und damit Qc."],"solution":"Nein. Bei konstanter Temperatur bleibt Kc unverändert. Die Zugabe verändert zunächst die aktuellen Konzentrationen und damit Qc. Das System reagiert anschließend, bis Qc wieder Kc entspricht.","competencies":["E"],"operators":["begründen","unterscheiden"],"sourceLessonId":"chem.q3.1.shifts","sourceKind":"exercise"},{"id":"chem.q3.1.shifts.exercise.transfer-solids","title":"Einfluss eines Feststoffs beurteilen","difficulty":"transfer","prompt":"In einem heterogenen Gleichgewicht wird die Menge eines reinen Feststoffs erhöht; der Feststoff bleibt weiterhin vorhanden. Ändert sich dadurch die Gleichgewichtslage im üblichen MWG-Modell? Begründe.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die Aktivität eines reinen Feststoffs bleibt im MWG-Ausdruck konstant.","Unterscheide Stoffmenge des Feststoffs von seiner Aktivität."],"solution":"Nein, solange reiner Feststoff vorhanden bleibt. Seine Aktivität ist im MWG-Ausdruck konstant; mehr Feststoff verändert Qc nicht. Die Stoffmenge des Feststoffs kann sich ändern, ohne dass sich dadurch die Gleichgewichtslage verschiebt.","competencies":["S","E"],"operators":["beurteilen","begründen"],"sourceLessonId":"chem.q3.1.shifts","sourceKind":"exercise"},{"id":"chem.q3.1.shifts.selftest.pressure","title":"Druckerhöhung","difficulty":"basic","prompt":"Welche Seite wird bei Druckerhöhung bevorzugt?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Zähle gasförmige Teilchen."],"solution":"Die Seite mit weniger gasförmigen Teilchen.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.1.shifts","sourceKind":"selfTest"},{"id":"chem.q3.1.shifts.selftest.temperature","title":"Temperaturerhöhung","difficulty":"basic","prompt":"Welche Reaktionsrichtung wird bei Temperaturerhöhung bevorzugt?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Die Richtung, die Wärme verbraucht."],"solution":"Die endotherme Reaktionsrichtung.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.1.shifts","sourceKind":"selfTest"},{"id":"chem.q3.1.shifts.selftest.catalyst","title":"Katalysator und Kc","difficulty":"basic","prompt":"Verändert ein Katalysator Kc?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Bei gleicher Temperatur bleibt Kc gleich."],"solution":"Nein. Er beschleunigt Hin- und Rückreaktion, ändert aber Kc und die Gleichgewichtslage nicht.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.1.shifts","sourceKind":"selfTest"},{"id":"chem.q3.2.ph.exercise.basic-ph","title":"pH einer starken Säure","difficulty":"basic","prompt":"Eine starke einprotonige Säure hat die Konzentration 1,0·10⁻³ mol·L⁻¹. Berechne näherungsweise den pH-Wert.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Bei vollständiger Protolyse gilt c(H₃O⁺) ≈ c₀.","Setze den Wert in pH = −lg c(H₃O⁺) ein."],"solution":"c(H₃O⁺) ≈ 1,0·10⁻³ mol·L⁻¹. pH = −lg(1,0·10⁻³) = 3,00. Die Näherung setzt eine starke, einprotonige Säure in hinreichend verdünnter Lösung voraus.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q3.2.ph","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"pH","label":"pH","value":3,"tolerance":{"absolute":0.05}}]}},{"id":"chem.q3.2.ph.exercise.basic-poh","title":"pOH und pH einer Base","difficulty":"basic","prompt":"Bei 25 °C gilt für eine starke Base c(OH⁻) = 1,0·10⁻⁴ mol·L⁻¹. Berechne pOH und pH.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Berechne zuerst pOH = −lg c(OH⁻).","Nutze bei 25 °C pH + pOH = 14,00."],"solution":"pOH = 4,00. Bei 25 °C ist pH = 14,00 − 4,00 = 10,00.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q3.2.ph","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"pOH","label":"pOH","value":4,"tolerance":{"absolute":0.05}},{"id":"pH","label":"pH","value":10,"tolerance":{"absolute":0.05}}]}},{"id":"chem.q3.2.ph.exercise.standard-weak","title":"Schwache Säure berechnen","difficulty":"standard","prompt":"Berechne näherungsweise den pH einer 0,10 mol·L⁻¹ Ethansäurelösung. Verwende Ks = 1,8·10⁻⁵ mol·L⁻¹ und prüfe die Näherung.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["Für eine schwache einprotonige Säure gilt bei x ≪ c₀ näherungsweise [H₃O⁺] ≈ √(Ks·c₀).","Vergleiche x mit c₀."],"solution":"[H₃O⁺] ≈ √(1,8·10⁻⁵·0,10) = √(1,8·10⁻⁶) = 1,34·10⁻³ mol·L⁻¹. pH ≈ 2,87. Der Protolyseanteil beträgt etwa 1,34·10⁻³/0,10 = 1,34 %; x ist deutlich kleiner als c₀, die Näherung ist plausibel.","competencies":["S","E"],"operators":["berechnen","überprüfen"],"sourceLessonId":"chem.q3.2.ph","sourceKind":"exercise"},{"id":"chem.q3.2.ph.exercise.standard-pka","title":"Säurestärke aus pKs","difficulty":"standard","prompt":"Säure A hat pKs = 3,1, Säure B pKs = 5,0. Welche Säure ist stärker und um welchen Faktor unterscheidet sich Ks?","taskType":"structured","afb":2,"supportedModes":["screen"],"hints":["Ks = 10⁻pKs.","Vergleiche die Differenz der pKs-Werte."],"solution":"Säure A ist stärker, weil sie den kleineren pKs-Wert hat. ΔpKs = 1,9, daher ist Ks(A)/Ks(B) = 10¹·⁹ ≈ 79. Säure A ist nach Ks ungefähr 80-mal stärker dissoziiert, wenn die übrigen Bedingungen vergleichbar sind.","competencies":["S","E"],"operators":["vergleichen","berechnen"],"sourceLessonId":"chem.q3.2.ph","sourceKind":"exercise"},{"id":"chem.q3.2.ph.exercise.transfer-polyacid","title":"Mehrprotonige Säure modellieren","difficulty":"transfer","prompt":"Phosphorsäure besitzt drei Protolysekonstanten. Begründe, warum die erste Protolyse meist stärker ist als die zweite und warum du die Stufen nicht zu einem einzigen pKs zusammenfassen darfst.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Nach der ersten Protonenabgabe ist das Teilchen negativ geladen.","Die weitere Abgabe eines Protons aus einem Anion ist elektrostatisch ungünstiger."],"solution":"Nach der ersten Abgabe entsteht H₂PO₄⁻. Dieses negativ geladene Teilchen gibt ein weiteres Proton weniger leicht ab, weil die Protonenabgabe elektrostatisch ungünstiger ist. Jede Stufe ist ein eigenes Gleichgewicht mit eigenem Ks/pKs; ein einziger Wert beschreibt die mehrstufige Protolyse nicht.","competencies":["S","E"],"operators":["begründen"],"sourceLessonId":"chem.q3.2.ph","sourceKind":"exercise"},{"id":"chem.q3.2.ph.exercise.transfer-model","title":"Grenzen der Wurzelnäherung","difficulty":"transfer","prompt":"Bei der Berechnung einer schwachen Säure wird [H₃O⁺] ≈ √(Ks·c₀) verwendet. Nenne die Voraussetzung und erkläre, was du tust, wenn sie nicht erfüllt ist.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die Näherung setzt eine kleine Protolyse gegenüber c₀ voraus.","Ohne die Näherung muss die Gleichgewichtsbeziehung exakt gelöst werden."],"solution":"Die Näherung gilt, wenn x = [H₃O⁺] gegenüber c₀ klein ist, also x ≪ c₀. Prüfe das Ergebnis, indem du x/c₀ bestimmst. Ist der Anteil nicht klein, löse Ks = x²/(c₀−x) ohne die Annahme c₀−x ≈ c₀, zum Beispiel mit einer quadratischen Gleichung.","competencies":["E","B"],"operators":["beurteilen","erläutern"],"sourceLessonId":"chem.q3.2.ph","sourceKind":"exercise"},{"id":"chem.q3.2.ph.selftest.strong","title":"Stärkere Säure am pKs","difficulty":"basic","prompt":"Welcher pKs-Wert kennzeichnet die stärkere Säure?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Kleinerer pKs entspricht größerem Ks."],"solution":"Die Säure mit dem kleineren pKs-Wert.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.2.ph","sourceKind":"selfTest"},{"id":"chem.q3.2.ph.selftest.poh","title":"pH und pOH","difficulty":"basic","prompt":"Welchen Zusammenhang nutzen pH und pOH bei 25 °C?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Nutze das Ionenprodukt des Wassers."],"solution":"pH + pOH = 14,00.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.2.ph","sourceKind":"selfTest"},{"id":"chem.q3.2.ph.selftest.approx","title":"Näherung für schwache Säuren","difficulty":"basic","prompt":"Wann ist c(H₃O⁺) ≈ √(Ks·c₀) für eine schwache Säure plausibel?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Die Protolyse muss klein im Vergleich zur Anfangskonzentration sein."],"solution":"Wenn x = c(H₃O⁺) deutlich kleiner als c₀ ist.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.2.ph","sourceKind":"selfTest"},{"id":"chem.q3.2.protolysis.exercise.basic-role","title":"Säure und Base markieren","difficulty":"basic","prompt":"Betrachte NH₃ + H₂O ⇌ NH₄⁺ + OH⁻. Markiere Brønsted-Säure und Brønsted-Base auf der Eduktseite.","taskType":"free-response","afb":1,"supportedModes":["screen","handwriting"],"hints":["Die Säure gibt ein Proton ab.","Die Base nimmt es auf."],"solution":"H₂O ist die Brønsted-Säure und NH₃ die Brønsted-Base. Wasser gibt H⁺ ab und wird zu OH⁻; Ammoniak nimmt H⁺ auf und wird zu NH₄⁺.","competencies":["S"],"operators":["zuordnen"],"sourceLessonId":"chem.q3.2.protolysis","sourceKind":"exercise"},{"id":"chem.q3.2.protolysis.exercise.basic-pairs","title":"Säure-Base-Paare bestimmen","difficulty":"basic","prompt":"Bestimme die korrespondierenden Säure-Base-Paare in HCl + H₂O → H₃O⁺ + Cl⁻.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Ein Paar unterscheidet sich um genau ein Proton.","Ordne Edukt und konjugiertes Produkt zu."],"solution":"HCl/Cl⁻ ist ein Säure-Base-Paar. H₂O/H₃O⁺ ist das zweite Paar. HCl gibt H⁺ ab; Wasser nimmt es auf.","competencies":["S"],"operators":["bestimmen"],"sourceLessonId":"chem.q3.2.protolysis","sourceKind":"exercise"},{"id":"chem.q3.2.protolysis.exercise.standard-ampholyte","title":"Ampholyt erklären","difficulty":"standard","prompt":"Zeige mit je einer Reaktionsgleichung, dass HCO₃⁻ als Säure und als Base reagieren kann.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Als Säure gibt HCO₃⁻ ein Proton ab.","Als Base nimmt es ein Proton auf."],"solution":"Als Säure: HCO₃⁻ + H₂O ⇌ CO₃²⁻ + H₃O⁺. Als Base: HCO₃⁻ + H₂O ⇌ H₂CO₃ + OH⁻. HCO₃⁻ kann Protonen abgeben und aufnehmen und ist damit ein Ampholyt.","competencies":["S","K"],"operators":["formulieren","erläutern"],"sourceLessonId":"chem.q3.2.protolysis","sourceKind":"exercise"},{"id":"chem.q3.2.protolysis.exercise.standard-strength","title":"Konzentration und Säurestärke","difficulty":"standard","prompt":"Eine 0,10 mol·L⁻¹ Salzsäure und eine 1,0 mol·L⁻¹ Ethansäure werden verglichen. Erkläre, warum die Konzentrationsangabe allein keine Rangfolge der Säurestärke festlegt.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Stärke beschreibt den Protolysegrad beziehungsweise das Gleichgewicht.","Konzentration gibt die Stoffmenge pro Volumen an."],"solution":"Die Konzentration beschreibt, wie viel Säure pro Volumen vorhanden ist. Die Säurestärke beschreibt, wie weit die Protonenübertragung an Wasser abläuft. Salzsäure ist eine starke, Ethansäure eine schwache Säure. Die höhere Konzentration allein macht Ethansäure nicht stärker.","competencies":["S","E"],"operators":["erläutern","vergleichen"],"sourceLessonId":"chem.q3.2.protolysis","sourceKind":"exercise"},{"id":"chem.q3.2.protolysis.exercise.transfer-polyprotic","title":"Mehrstufige Protolyse darstellen","difficulty":"transfer","prompt":"Phosphorsäure kann drei Protonen stufenweise abgeben. Formuliere die erste und zweite Protolyse in Wasser.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Bei jeder Stufe entsteht ein neues korrespondierendes Säurerest-Ion.","Gib die Nettoladung nach jeder Abgabe an."],"solution":"Erste Stufe: H₃PO₄ + H₂O ⇌ H₂PO₄⁻ + H₃O⁺. Zweite Stufe: H₂PO₄⁻ + H₂O ⇌ HPO₄²⁻ + H₃O⁺. Jede Stufe ist ein eigenes Gleichgewicht mit eigener Säurekonstante.","competencies":["S","K"],"operators":["formulieren","darstellen"],"sourceLessonId":"chem.q3.2.protolysis","sourceKind":"exercise"},{"id":"chem.q3.2.protolysis.exercise.transfer-net","title":"Erste Protolyse der Schwefelsäure","difficulty":"transfer","prompt":"Prüfe die Gleichung H₂SO₄ + H₂O → HSO₄⁻ + H₃O⁺ auf Atom- und Ladungsbilanz. Begründe, ob sie die erste Protolyse darstellt.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Zähle H, S und O auf beiden Seiten.","Vergleiche die Gesamtladung."],"solution":"Die Atome sind bilanziert. Links ist die Gesamtladung null; rechts beträgt sie −1 + 1 = 0. Die Gleichung stellt die erste Protonenabgabe von Schwefelsäure an Wasser dar.","competencies":["S","E"],"operators":["überprüfen","begründen"],"sourceLessonId":"chem.q3.2.protolysis","sourceKind":"exercise"},{"id":"chem.q3.2.protolysis.selftest.acid","title":"Brønsted-Säure","difficulty":"basic","prompt":"Was macht eine Brønsted-Säure?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie überträgt ein Proton."],"solution":"Sie gibt ein Proton ab.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.2.protolysis","sourceKind":"selfTest"},{"id":"chem.q3.2.protolysis.selftest.pairs","title":"Korrespondierende Paare","difficulty":"basic","prompt":"Worin unterscheiden sich korrespondierende Säure-Base-Paare?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Betrachte die Teilchenformeln."],"solution":"Sie unterscheiden sich um genau ein Proton.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.2.protolysis","sourceKind":"selfTest"},{"id":"chem.q3.2.protolysis.selftest.ampholyte","title":"Ampholyt","difficulty":"basic","prompt":"Was ist ein Ampholyt?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Das Teilchen kann in beide Richtungen reagieren."],"solution":"Ein Teilchen, das Protonen aufnehmen und abgeben kann.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.2.protolysis","sourceKind":"selfTest"},{"id":"chem.q3.2.titration.exercise.basic-terms","title":"Titrationsbegriffe zuordnen","difficulty":"basic","prompt":"Eine unbekannte Säure wird mit Natronlauge bekannter Konzentration titriert. Welche Lösung ist die Maßlösung, welche die Probelösung?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Die Konzentration der Maßlösung ist bekannt.","Die unbekannte Konzentration soll bestimmt werden."],"solution":"Natronlauge bekannter Konzentration ist die Maßlösung. Die unbekannte Säure ist die Probelösung.","competencies":["S"],"operators":["zuordnen"],"sourceLessonId":"chem.q3.2.titration","sourceKind":"exercise"},{"id":"chem.q3.2.titration.exercise.basic-equivalence","title":"Bedeutung des Äquivalenzpunkts","difficulty":"basic","prompt":"Was bedeutet der Äquivalenzpunkt bei der Titration einer einprotonigen Säure mit einer einwertigen Base?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Vergleiche die umgesetzten Stoffmengen gemäß Reaktionsgleichung."],"solution":"Am Äquivalenzpunkt liegen Säure und Base im stöchiometrisch passenden Verhältnis vor. Für eine 1:1-Neutralisation gilt n(Säure) = n(OH⁻).","competencies":["S"],"operators":["erläutern"],"sourceLessonId":"chem.q3.2.titration","sourceKind":"exercise"},{"id":"chem.q3.2.titration.exercise.standard-calc","title":"Säurekonzentration berechnen","difficulty":"standard","prompt":"20,00 mL einer einprotonigen Säure werden mit 0,1000 mol·L⁻¹ NaOH titriert. Der Äquivalenzpunkt liegt bei 18,60 mL. Berechne die Säurekonzentration.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Die Neutralisation ist im Verhältnis Säure:OH⁻ = 1:1.","Nutze cₐVₐ = cᵦVᵦ am Äquivalenzpunkt."],"solution":"n(OH⁻) = 0,1000 mol·L⁻¹ · 0,01860 L = 0,001860 mol. Damit n(Säure) = 0,001860 mol. c(Säure) = 0,001860 mol / 0,02000 L = 0,09300 mol·L⁻¹.","competencies":["S","E"],"operators":["berechnen"],"sourceLessonId":"chem.q3.2.titration","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"c","label":"Säurekonzentration","value":0.093,"unit":"mol·L⁻¹"}]}},{"id":"chem.q3.2.titration.exercise.standard-indicator","title":"Kriterium der Indikatorwahl","difficulty":"standard","prompt":"Eine starke Säure wird mit einer starken Base titriert. Welches Kriterium nutzt du für die Indikatorwahl?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Der Indikator soll im steilen Abschnitt der Titrationskurve umschlagen.","Der Äquivalenzpunkt liegt bei 25 °C näherungsweise bei pH 7."],"solution":"Wähle einen Indikator, dessen Umschlagsbereich innerhalb des steilen pH-Sprungs um den Äquivalenzpunkt liegt. Bei starker Säure und starker Base liegt dieser bei 25 °C näherungsweise bei pH 7; Bromthymolblau eignet sich mit seinem Umschlagsbereich um neutral als typisches Beispiel.","competencies":["S","E"],"operators":["begründen"],"sourceLessonId":"chem.q3.2.titration","sourceKind":"exercise"},{"id":"chem.q3.2.titration.exercise.transfer-curve","title":"Titrationskurve auswerten","difficulty":"transfer","prompt":"Die Abbildung zeigt die Titrationskurve einer Säureprobe mit Natronlauge. Der pH-Wert ändert sich zunächst nur wenig und steigt nahe einem bestimmten Volumen steil an. Erkläre, was du aus diesem Verlauf ableitest und was du für eine Konzentrationsberechnung zusätzlich brauchst.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Der steile Bereich liegt in der Nähe des Äquivalenzpunkts.","Für die Rechnung brauchst du Volumen, Maßlösungskonzentration und Stöchiometrie."],"solution":"Der steile Sprung markiert den pH-Bereich um den Äquivalenzpunkt. Für die Konzentration brauchst du das Äquivalenzvolumen, die Konzentration der Maßlösung, das Probenvolumen und die ausgeglichene Neutralisationsgleichung mit ihrem Stoffmengenverhältnis. In der Abbildung liegt der Sprung bei etwa 20 mL Natronlauge.","competencies":["E","K"],"operators":["auswerten","ableiten"],"sourceLessonId":"chem.q3.2.titration","sourceKind":"exercise","figures":[{"file":"titration-curve.svg","alt":"Titrationskurve: pH-Wert gegen das Volumen zugegebener Natronlauge von 0 bis 40 mL. Der pH-Wert beginnt bei etwa 2,9, steigt flach bis etwa 6 an, springt bei etwa 20 mL steil auf etwa 11 und flacht danach bei etwa 12,5 ab.","caption":"Berechneter Kurvenverlauf","placement":"prompt"}]},{"id":"chem.q3.2.titration.exercise.transfer-uncertainty","title":"Schwer erkennbarer Farbumschlag","difficulty":"transfer","prompt":"Bei einer schwach gefärbten Probe ist der Farbumschlag des Indikators schwer erkennbar. Nenne eine mögliche Fehlerquelle und eine geeignete Alternative.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Der Endpunkt wird visuell bestimmt.","Ein pH-Meter kann den Verlauf kontinuierlich messen."],"solution":"Der Endpunkt kann zu spät oder zu früh abgelesen werden, wodurch das verbrauchte Maßlösungsvolumen ungenau ist. Eine pH-metrische Titration mit aufgezeichneter Kurve kann den Äquivalenzbereich zuverlässiger bestimmen. Auch dabei sind Kalibrierung und Messunsicherheit zu beachten.","competencies":["E","B"],"operators":["beurteilen","vorschlagen"],"sourceLessonId":"chem.q3.2.titration","sourceKind":"exercise"},{"id":"chem.q3.2.titration.selftest.equivalence","title":"Äquivalenzpunkt","difficulty":"basic","prompt":"Was kennzeichnet den Äquivalenzpunkt?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Berücksichtige das Stoffmengenverhältnis der Reaktionsgleichung."],"solution":"Säure und Base sind im stöchiometrisch passenden Verhältnis umgesetzt.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.2.titration","sourceKind":"selfTest"},{"id":"chem.q3.2.titration.selftest.indicator","title":"Umschlagsbereich","difficulty":"basic","prompt":"Wo soll der Umschlagsbereich eines Indikators liegen?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Suche den starken pH-Sprung der Kurve."],"solution":"Im steilen pH-Sprung um den Äquivalenzpunkt.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.2.titration","sourceKind":"selfTest"},{"id":"chem.q3.2.titration.selftest.calculation","title":"Angaben für die Auswertung","difficulty":"basic","prompt":"Welche Angaben brauchst du mindestens für die Konzentration aus einer 1:1-Titration?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Nutze n=cV."],"solution":"Konzentration und Volumen der Maßlösung sowie das Probenvolumen am Äquivalenzpunkt.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.2.titration","sourceKind":"selfTest"},{"id":"chem.q3.3.advanced.ex.basic-charge","title":"Ladungsmenge bestimmen","difficulty":"basic","prompt":"Durch eine Elektrolyse fließen 0,50 A für 10 min. Berechne die Ladungsmenge.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Zeit zuerst in Sekunden umrechnen.","Nutze Q_el=I·t."],"solution":"t=600 s. Q_el=0,50 A·600 s=300 C.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q3.3.advanced","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"Q","label":"Ladung","value":300,"unit":"C"}]}},{"id":"chem.q3.3.advanced.ex.basic-electrons","title":"Elektronenstoffmenge aus Ladung","difficulty":"basic","prompt":"Wie viele Mol Elektronen entsprechen 1930 C? Verwende F=96485 C mol⁻¹.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Teile die Ladung durch F.","Prüfe die Einheit."],"solution":"n(e⁻)=Q/F=1930/96485 mol=0,0200 mol (3 signifikante Stellen).","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q3.3.advanced","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"n","label":"n(e⁻)","value":0.02,"unit":"mol"}]}},{"id":"chem.q3.3.advanced.ex.standard-product","title":"Produktstoffmenge","difficulty":"standard","prompt":"Bei der Reduktion Ag⁺+e⁻→Ag fließen 9650 C. Bestimme die theoretische Stoffmenge Silber.","taskType":"numeric","afb":2,"supportedModes":["screen","handwriting"],"hints":["Ermittle zuerst n(e⁻).","Das Stoffmengenverhältnis ist 1:1."],"solution":"n(e⁻)=9650/96485=0,100 mol. Da ein Elektron pro Ag⁺ benötigt wird, entstehen theoretisch 0,100 mol Ag.","competencies":["S","E"],"operators":["bestimmen","berechnen"],"sourceLessonId":"chem.q3.3.advanced","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"n","label":"n(Ag)","value":0.1,"unit":"mol"}]}},{"id":"chem.q3.3.advanced.ex.standard-nernst","title":"Potenzialänderung berechnen","difficulty":"standard","prompt":"Für Cu²⁺/Cu sinkt die Cu²⁺-Konzentration bei 25 °C um den Faktor 100. Wie ändert sich E näherungsweise? z=2.","taskType":"numeric","afb":2,"supportedModes":["screen","handwriting"],"hints":["Nutze E=E°+(0,0592/z)·log(c/c°).","Ein Faktor 100 entspricht zwei Zehnerpotenzen."],"solution":"ΔE=(0,0592/2)·log(1/100)=0,0296·(−2) V=−0,0592 V. Das Potential sinkt um etwa 59 mV.","competencies":["S","E"],"operators":["berechnen","deuten"],"sourceLessonId":"chem.q3.3.advanced","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"dE","label":"Potenzialänderung ΔE","value":-0.0592,"unit":"V"}]}},{"id":"chem.q3.3.advanced.ex.transfer-efficiency","title":"Stromausbeute berücksichtigen","difficulty":"transfer","prompt":"Die theoretische Kupfermasse beträgt 1,19 g; gemessen werden 1,07 g. Berechne die Stromausbeute und nenne eine mögliche Ursache.","taskType":"structured","afb":1,"supportedModes":["screen","handwriting"],"hints":["Quotient aus realer und theoretischer Masse mal 100 %.","Nenne einen konkurrierenden Prozess oder Messverlust."],"solution":"η=1,07/1,19·100 %=89,9 %. Mögliche Ursachen sind Nebenreaktionen, unvollständige Abscheidung oder mechanischer Verlust beim Spülen/Trocknen.","competencies":["E","B"],"operators":["berechnen","erläutern"],"sourceLessonId":"chem.q3.3.advanced","sourceKind":"exercise"},{"id":"chem.q3.3.advanced.ex.transfer-scope","title":"Kupfer-Konzentrationszelle","difficulty":"transfer","prompt":"Zwei Cu²⁺/Cu-Halbzellen enthalten Kupfer(II)-sulfat-Lösungen mit c₁(Cu²⁺) = 1,0 mol·L⁻¹ und c₂(Cu²⁺) = 0,010 mol·L⁻¹. Berechne die Zellspannung bei 25 °C und gib an, welche Halbzelle den Pluspol bildet.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["E = E° + (0,0592 V / z) · lg c(Cu²⁺) mit z = 2.","Der Standardwert E° hebt sich bei der Differenz heraus."],"solution":"ΔE = (0,0592 V / 2) · lg(1,0 / 0,010) = 0,0296 V · 2 = 0,0592 V ≈ 0,059 V. Die Halbzelle mit der höheren Cu²⁺-Konzentration hat das höhere Potenzial; dort werden Cu²⁺-Ionen reduziert. Sie bildet den Pluspol, die verdünnte Halbzelle den Minuspol.","competencies":["S"],"operators":["berechnen","angeben"],"sourceLessonId":"chem.q3.3.advanced","sourceKind":"exercise"},{"id":"chem.q3.3.advanced.st.1","title":"Ladung","difficulty":"basic","prompt":"Welche Größe erhältst du aus Stromstärke mal Zeit?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Einheit beachten."],"solution":"Die elektrische Ladung Q_el in Coulomb.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.3.advanced","sourceKind":"selfTest"},{"id":"chem.q3.3.advanced.st.2","title":"Elektronenbilanz","difficulty":"basic","prompt":"Was brauchst du, um aus n(e⁻) eine Produktstoffmenge zu bestimmen?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Betrachte die Teilgleichung."],"solution":"Das stöchiometrische Verhältnis aus der ausgeglichenen Elektroden-Teilgleichung.","competencies":["S"],"operators":["erläutern"],"sourceLessonId":"chem.q3.3.advanced","sourceKind":"selfTest"},{"id":"chem.q3.3.advanced.st.3","title":"Konzentration und Potenzial","difficulty":"basic","prompt":"Wie verändert sich das Potenzial einer Cu²⁺/Cu-Halbzelle, wenn die Cu²⁺-Konzentration steigt?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Betrachte das Vorzeichen des Konzentrationsterms in der Nernst-Gleichung."],"solution":"Es steigt, das Potenzial wird positiver.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.3.advanced","sourceKind":"selfTest"},{"id":"chem.q3.3.electrolysis-corrosion.exercise.basic-electrolysis","title":"Elektrolyse einordnen","difficulty":"basic","prompt":"Warum benötigt eine Elektrolyse eine äußere Spannungsquelle?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die Reaktion läuft nicht in der spontanen galvanischen Richtung."],"solution":"Die Spannungsquelle erzwingt eine nicht spontane Redoxreaktion, indem sie elektrische Energie zuführt und Elektronen an den Elektroden bereitstellt beziehungsweise abzieht.","competencies":["S"],"operators":["erläutern"],"sourceLessonId":"chem.q3.3.electrolysis-corrosion","sourceKind":"exercise"},{"id":"chem.q3.3.electrolysis-corrosion.exercise.basic-corrosion","title":"Bedingungen der Rostbildung","difficulty":"basic","prompt":"Nenne zwei Bedingungen, die die Rostbildung von Eisen begünstigen.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Rostbildung ist eine elektrochemische Reaktion in Gegenwart von Wasser und Oxidationsmittel."],"solution":"Wasser und Sauerstoff begünstigen die Korrosion von Eisen. Salze können durch erhöhte Leitfähigkeit elektrochemische Teilreaktionen unterstützen.","competencies":["S"],"operators":["nennen"],"sourceLessonId":"chem.q3.3.electrolysis-corrosion","sourceKind":"exercise"},{"id":"chem.q3.3.electrolysis-corrosion.exercise.standard-lead","title":"Bleiakkumulator beim Entladen","difficulty":"standard","prompt":"Formuliere die Gesamtreaktion des Bleiakkumulators beim Entladen.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Beide Elektroden bilden Bleisulfat.","Schwefelsäure und Wasser sind beteiligt."],"solution":"Pb(s) + PbO₂(s) + 2 H₂SO₄(aq) → 2 PbSO₄(s) + 2 H₂O(l). Beim Laden wird die Reaktion durch elektrische Energie umgekehrt.","competencies":["S","K"],"operators":["formulieren"],"sourceLessonId":"chem.q3.3.electrolysis-corrosion","sourceKind":"exercise"},{"id":"chem.q3.3.electrolysis-corrosion.exercise.standard-protection","title":"Lackschicht und Opferanode","difficulty":"standard","prompt":"Vergleiche eine Lackschicht mit kathodischem Schutz durch ein unedleres Opfermetall.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Lack schirmt die Oberfläche ab.","Ein Opfermetall wird bevorzugt oxidiert."],"solution":"Eine Lackschicht ist eine Barriere gegen Wasser und Sauerstoff; Schäden können lokale Korrosion ermöglichen. Ein unedleres Opfermetall oxidiert bevorzugt und schützt das Eisen elektrochemisch, solange genügend Opfermetall vorhanden und elektrisch verbunden ist.","competencies":["S","E"],"operators":["vergleichen"],"sourceLessonId":"chem.q3.3.electrolysis-corrosion","sourceKind":"exercise"},{"id":"chem.q3.3.electrolysis-corrosion.exercise.transfer-electrolysis","title":"Elektrodenreaktion vorhersagen","difficulty":"transfer","prompt":"Bei der Elektrolyse einer wässrigen Kupfer(II)-sulfatlösung scheidet sich am geeigneten Kathodenmaterial Kupfer ab. Formuliere die Kathodenreaktion und ordne sie ein.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["An der Kathode findet Reduktion statt.","Kupfer(II)-Ionen nehmen Elektronen auf."],"solution":"Cu²⁺(aq) + 2 e⁻ → Cu(s). Kupfer(II)-Ionen werden an der Kathode reduziert und als metallisches Kupfer abgeschieden. Die Anodenreaktion hängt vom Elektrodenmaterial und den Bedingungen ab.","competencies":["S","E"],"operators":["formulieren","begründen"],"sourceLessonId":"chem.q3.3.electrolysis-corrosion","sourceKind":"exercise"},{"id":"chem.q3.3.electrolysis-corrosion.exercise.transfer-battery","title":"Laden des Bleiakkumulators","difficulty":"transfer","prompt":"Ein Bleiakkumulator wird wiederholt geladen und entladen. Erkläre, warum Laden nicht einfach eine zweite spontane Entladung ist, und nenne eine Materialeigenschaft, die bei der Bewertung wichtig ist.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Beim Laden wird elektrische Energie zugeführt und die Zellreaktion umgekehrt.","Bewerte neben der Reversibilität auch Stoffe und Betriebsbedingungen."],"solution":"Beim Laden erzwingt eine äußere Spannungsquelle die Umkehr der Entladereaktion; Energie wird zugeführt. Für eine Bewertung sind unter anderem Kapazität, Lebensdauer, Ladeverluste, Masse sowie Umwelt- und Recyclingaspekte relevant.","competencies":["S","B"],"operators":["erläutern","beurteilen"],"sourceLessonId":"chem.q3.3.electrolysis-corrosion","sourceKind":"exercise"},{"id":"chem.q3.3.electrolysis-corrosion.selftest.electrolysis","title":"Antrieb der Elektrolyse","difficulty":"basic","prompt":"Was treibt eine Elektrolyse an?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Die Reaktion ist nicht spontan in der ablaufenden Richtung."],"solution":"Eine äußere elektrische Spannungsquelle.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.3.electrolysis-corrosion","sourceKind":"selfTest"},{"id":"chem.q3.3.electrolysis-corrosion.selftest.battery","title":"Akku laden","difficulty":"basic","prompt":"Was geschieht mit einem Akkumulator beim Laden?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Die Entladereaktion wird umgekehrt."],"solution":"Eine äußere Spannungsquelle erzwingt die Rückreaktion und führt elektrische Energie zu.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.3.electrolysis-corrosion","sourceKind":"selfTest"},{"id":"chem.q3.3.electrolysis-corrosion.selftest.sacrificial","title":"Opferanode","difficulty":"basic","prompt":"Warum schützt eine Opferanode ein anderes Metall?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Das unedlere Metall wird zuerst oxidiert."],"solution":"Sie oxidiert bevorzugt und liefert Elektronen; das zu schützende Metall bleibt kathodisch.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.3.electrolysis-corrosion","sourceKind":"selfTest"},{"id":"chem.q3.3.galvanic-cells.exercise.basic-electrodes","title":"Anode und Kathode zuordnen","difficulty":"basic","prompt":"In einer galvanischen Zelle wird Zink zu Zn²⁺ oxidiert und Cu²⁺ zu Kupfer reduziert. Ordne Anode und Kathode zu.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Oxidation findet an der Anode statt, Reduktion an der Kathode."],"solution":"Zinkelektrode: Anode (Oxidation). Kupferelektrode: Kathode (Reduktion).","competencies":["S"],"operators":["zuordnen"],"sourceLessonId":"chem.q3.3.galvanic-cells","sourceKind":"exercise"},{"id":"chem.q3.3.galvanic-cells.exercise.basic-flow","title":"Elektronenfluss im Daniell-Element","difficulty":"basic","prompt":"In welche Richtung fließen die Elektronen im Daniell-Element durch den äußeren Leiter?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Elektronen fließen vom Elektronendonator zur Elektronenaufnahme."],"solution":"Vom Zink, der Anode, zur Kupferelektrode, der Kathode.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.3.galvanic-cells","sourceKind":"exercise"},{"id":"chem.q3.3.galvanic-cells.exercise.standard-voltage","title":"Zellspannung berechnen","difficulty":"standard","prompt":"Für das Daniell-Element gelten E°(Cu²⁺/Cu)=+0,34 V und E°(Zn²⁺/Zn)=−0,76 V. Berechne E°Zelle.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Nutze E°Zelle = E°Kathode − E°Anode.","Beide Werte sind Reduktionspotenziale."],"solution":"E°Zelle = +0,34 V − (−0,76 V) = +1,10 V.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q3.3.galvanic-cells","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"E","label":"E°Zelle","value":1.1,"unit":"V"}]}},{"id":"chem.q3.3.galvanic-cells.exercise.standard-notation","title":"Zellschreibweise","difficulty":"standard","prompt":"Formuliere die Zellschreibweise des Daniell-Elements.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Schreibe die Anode links und die Kathode rechts.","Ein einfacher Strich trennt Phasen, ein Doppelstrich die Salzbrücke."],"solution":"Zn(s) | Zn²⁺(aq) || Cu²⁺(aq) | Cu(s).","competencies":["S","K"],"operators":["formulieren"],"sourceLessonId":"chem.q3.3.galvanic-cells","sourceKind":"exercise"},{"id":"chem.q3.3.galvanic-cells.exercise.transfer-spontaneous","title":"Spontane Reaktion beurteilen","difficulty":"transfer","prompt":"Eine berechnete Standardzellspannung beträgt −0,25 V für die Reaktion in der angegebenen Richtung. Was folgt daraus und wie kannst du eine positive Spannung erhalten?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Ein negatives E°Zelle bedeutet, dass die angegebene Richtung unter Standardbedingungen nicht spontan ist.","Kehre die Reaktion um."],"solution":"Die Reaktion in der angegebenen Richtung ist unter Standardbedingungen nicht spontan. Bei Umkehrung der Gesamtreaktion wechselt das Vorzeichen der Zellspannung zu +0,25 V.","competencies":["S","E"],"operators":["beurteilen","ableiten"],"sourceLessonId":"chem.q3.3.galvanic-cells","sourceKind":"exercise"},{"id":"chem.q3.3.galvanic-cells.exercise.transfer-bridge","title":"Aufgabe der Salzbrücke","difficulty":"transfer","prompt":"Die Abbildung zeigt den Aufbau eines Daniell-Elements. Erkläre, warum eine galvanische Zelle ohne Salzbrücke oder andere ionische Verbindung nach kurzer Zeit keinen dauerhaften Strom liefern kann.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Betrachte die Ladung in beiden Halbzellen.","Elektronenfluss allein würde Ladungstrennung erzeugen."],"solution":"Ohne Ionenwanderung würde sich an der Anode positive Ladung ansammeln und an der Kathode positive Ionen verbraucht werden, sodass Ladungsungleichgewichte den Elektronenfluss hemmen. Die Salzbrücke ermöglicht Ionenwanderung und hält die Lösungen annähernd elektrisch neutral.","competencies":["S","E"],"operators":["erläutern","begründen"],"sourceLessonId":"chem.q3.3.galvanic-cells","sourceKind":"exercise","figures":[{"file":"daniell-cell.svg","alt":"Daniell-Element: links ein Zinkstab in Zinksulfat-Lösung, rechts ein Kupferstab in Kupfersulfat-Lösung. Die Lösungen sind durch eine Salzbrücke verbunden, die Elektroden über eine Leitung mit Spannungsmessgerät. Ein Pfeil zeigt den Elektronenfluss vom Zink (Minuspol) zum Kupfer (Pluspol).","placement":"prompt"}]},{"id":"chem.q3.3.galvanic-cells.selftest.anode","title":"Ort der Oxidation","difficulty":"basic","prompt":"An welcher Elektrode findet Oxidation statt?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Die Elektrodenbezeichnung bleibt für alle Zellentypen gleich."],"solution":"An der Anode.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.3.galvanic-cells","sourceKind":"selfTest"},{"id":"chem.q3.3.galvanic-cells.selftest.flow","title":"Minuspol des Daniell-Elements","difficulty":"basic","prompt":"Welche Elektrode bildet im Daniell-Element den Minuspol, und welcher Vorgang läuft dort ab?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Am Minuspol werden Elektronen an den äußeren Leiter abgegeben."],"solution":"Die Zinkelektrode. Dort wird Zink zu Zn²⁺-Ionen oxidiert; sie ist die Anode.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.3.galvanic-cells","sourceKind":"selfTest"},{"id":"chem.q3.3.galvanic-cells.selftest.voltage","title":"Formel der Zellspannung","difficulty":"basic","prompt":"Wie berechnest du E°Zelle aus Reduktionspotenzialen?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Kathodenpotenzial minus Anodenpotenzial."],"solution":"E°Zelle = E°Kathode − E°Anode.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.3.galvanic-cells","sourceKind":"selfTest"},{"id":"chem.q3.3.redox.exercise.basic-numbers","title":"Oxidationszahlen bestimmen","difficulty":"basic","prompt":"Bestimme die Oxidationszahlen von S in H₂S und S in SO₂.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Wasserstoff hat in diesen Verbindungen meist +I, Sauerstoff meist −II.","Die Summe in einem neutralen Molekül ist null."],"solution":"H₂S: 2·(+I) + x = 0, daher S = −II. SO₂: x + 2·(−II) = 0, daher S = +IV.","competencies":["S"],"operators":["bestimmen"],"sourceLessonId":"chem.q3.3.redox","sourceKind":"exercise"},{"id":"chem.q3.3.redox.exercise.basic-agent","title":"Oxidation und Reduktion erkennen","difficulty":"basic","prompt":"In der Reaktion Zn + Cu²⁺ → Zn²⁺ + Cu: Welcher Stoff wird oxidiert und welcher reduziert?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Oxidation bedeutet Elektronenabgabe, Reduktion Elektronenaufnahme."],"solution":"Zn wird zu Zn²⁺ oxidiert und ist das Reduktionsmittel. Cu²⁺ wird zu Cu reduziert und ist das Oxidationsmittel.","competencies":["S"],"operators":["zuordnen","begründen"],"sourceLessonId":"chem.q3.3.redox","sourceKind":"exercise"},{"id":"chem.q3.3.redox.exercise.standard-half","title":"Teilgleichungen kombinieren","difficulty":"standard","prompt":"Stelle die Gesamtgleichung aus Fe²⁺ → Fe³⁺ und Ce⁴⁺ → Ce³⁺ auf.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Gleiche zuerst die Elektronenzahl an.","Addiere anschließend die Teilgleichungen und kürze Elektronen."],"solution":"Fe²⁺ → Fe³⁺ + e⁻; Ce⁴⁺ + e⁻ → Ce³⁺. Gesamtgleichung: Fe²⁺ + Ce⁴⁺ → Fe³⁺ + Ce³⁺. Elektronen und Ladung sind ausgeglichen.","competencies":["S","E"],"operators":["formulieren","ausgleichen"],"sourceLessonId":"chem.q3.3.redox","sourceKind":"exercise"},{"id":"chem.q3.3.redox.exercise.standard-acidic","title":"Dichromat-Gleichung ausgleichen","difficulty":"standard","prompt":"Gleiche Cr₂O₇²⁻ + Fe²⁺ → Cr³⁺ + Fe³⁺ im sauren Milieu aus.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Gleiche zuerst die Elektronen mit Teilgleichungen aus.","Nutze H₂O für O und H⁺ für H."],"solution":"Reduktion: Cr₂O₇²⁻ + 14 H⁺ + 6 e⁻ → 2 Cr³⁺ + 7 H₂O. Oxidation: Fe²⁺ → Fe³⁺ + e⁻, mal 6. Gesamt: Cr₂O₇²⁻ + 14 H⁺ + 6 Fe²⁺ → 2 Cr³⁺ + 7 H₂O + 6 Fe³⁺. Atome und Ladung (+24 links und rechts) stimmen.","competencies":["S","E"],"operators":["ausgleichen","überprüfen"],"sourceLessonId":"chem.q3.3.redox","sourceKind":"exercise"},{"id":"chem.q3.3.redox.exercise.transfer-basic","title":"Medium und Ladung prüfen","difficulty":"transfer","prompt":"Eine saure Redoxgleichung wird in eine alkalische Lösung übertragen. Welche zusätzlichen Schritte brauchst du nach dem Ausgleich mit H⁺/H₂O?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["In alkalischer Lösung darf am Ende kein H⁺ verbleiben.","Neutralisiere H⁺ mit OH⁻ und kürze Wasser."],"solution":"Addiere zu beiden Seiten so viele OH⁻-Ionen, wie H⁺-Ionen vorhanden sind. H⁺ + OH⁻ bildet H₂O. Kürze anschließend gleiche Wassermoleküle auf beiden Seiten und prüfe erneut Atome sowie Gesamtladung.","competencies":["S","E"],"operators":["beschreiben","überprüfen"],"sourceLessonId":"chem.q3.3.redox","sourceKind":"exercise"},{"id":"chem.q3.3.redox.exercise.transfer-evidence","title":"Permanganat-Entfärbung deuten","difficulty":"transfer","prompt":"Eine Probe entfärbt eine Permanganatlösung im Sauren. Erkläre, welche zusätzlichen Angaben du für eine vollständige Redoxdeutung brauchst.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Entfärbung ist zunächst nur die Beobachtung.","Du brauchst Reaktionspartner und Produkte, um Oxidationszahlen zu vergleichen."],"solution":"Die Entfärbung ist eine Beobachtung, aber kein vollständiger Nachweis des Reaktionswegs. Für die Deutung brauchst du die reagierende Substanz, Produkte und Bedingungen. Dann bestimmst du Oxidationszahlen und prüfst, ob Permanganat reduziert und der andere Stoff oxidiert wird.","competencies":["E","B"],"operators":["auswerten","begründen"],"sourceLessonId":"chem.q3.3.redox","sourceKind":"exercise"},{"id":"chem.q3.3.redox.selftest.oxidation","title":"Oxidation","difficulty":"basic","prompt":"Was geschieht bei einer Oxidation?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Achte auf Elektronen."],"solution":"Elektronen werden abgegeben; die Oxidationszahl steigt.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.3.redox","sourceKind":"selfTest"},{"id":"chem.q3.3.redox.selftest.agent","title":"Oxidationsmittel","difficulty":"basic","prompt":"Was ist ein Oxidationsmittel?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Es nimmt Elektronen auf."],"solution":"Ein Elektronenakzeptor, der selbst reduziert wird.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.3.redox","sourceKind":"selfTest"},{"id":"chem.q3.3.redox.selftest.balance","title":"Ausgeglichene Redoxgleichung","difficulty":"basic","prompt":"Was muss eine ausgeglichene Redoxgleichung erhalten?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Prüfe beide Bilanzen."],"solution":"Atome und Gesamtladung; Elektronen sind in der Gesamtgleichung gekürzt.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.3.redox","sourceKind":"selfTest"},{"id":"chem.q3.4.buffers.exercise.basic-pair","title":"Pufferpaar erkennen","difficulty":"basic","prompt":"Welche Stoffe bilden gemeinsam einen Puffer: CH₃COOH/CH₃COO⁻ oder HCl/Cl⁻? Begründe knapp.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Ein Puffer enthält eine schwache Säure und ihre korrespondierende Base in merklicher Menge."],"solution":"CH₃COOH/CH₃COO⁻ bildet ein Puffersystem: schwache Ethansäure und Ethanoat-Ion. HCl/Cl⁻ puffert im üblichen Modell nicht wirksam, weil HCl eine starke Säure ist.","competencies":["S"],"operators":["zuordnen","begründen"],"sourceLessonId":"chem.q3.4.buffers","sourceKind":"exercise"},{"id":"chem.q3.4.buffers.exercise.basic-addition","title":"Puffer und Säurezugabe","difficulty":"basic","prompt":"Formuliere, wie die Base CH₃COO⁻ auf eine kleine Zugabe von H₃O⁺ reagiert.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die Base nimmt ein Proton auf.","Dabei entsteht ihre korrespondierende Säure."],"solution":"CH₃COO⁻ + H₃O⁺ → CH₃COOH + H₂O. Das zugegebene H₃O⁺ wird teilweise abgefangen.","competencies":["S","K"],"operators":["formulieren"],"sourceLessonId":"chem.q3.4.buffers","sourceKind":"exercise"},{"id":"chem.q3.4.buffers.exercise.standard-hh","title":"Puffer-pH berechnen","difficulty":"standard","prompt":"Ein Acetatpuffer enthält c(CH₃COO⁻) = 0,20 mol·L⁻¹ und c(CH₃COOH) = 0,10 mol·L⁻¹. Berechne näherungsweise den pH mit pKs = 4,76.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Nutze pH = pKs + lg(c(Base)/c(Säure)).","Der Basen-Säure-Quotient ist 2."],"solution":"pH = 4,76 + lg(0,20/0,10) = 4,76 + lg 2 ≈ 4,76 + 0,30 = 5,06.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q3.4.buffers","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"pH","label":"pH","value":5.06,"tolerance":{"absolute":0.05}}]}},{"id":"chem.q3.4.buffers.exercise.standard-capacity","title":"Pufferkapazität vergleichen","difficulty":"standard","prompt":"Zwei Acetatpuffer besitzen dasselbe Verhältnis c(CH₃COO⁻)/c(CH₃COOH), aber Puffer B enthält beide Komponenten in zehnfach höherer Konzentration. Welcher Puffer kann bei vergleichbarem Volumen mehr zugegebene Säure abfangen?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Das Verhältnis bestimmt näherungsweise den pH.","Die absoluten Stoffmengen bestimmen, wie viel Zugabe abgefangen werden kann."],"solution":"Puffer B kann mehr Säure abfangen, weil er pro Volumen mehr Ethanoat-Ionen enthält. Beide Puffer haben bei gleichem Verhältnis näherungsweise denselben pH, aber unterschiedliche Pufferkapazitäten.","competencies":["S","E"],"operators":["vergleichen","begründen"],"sourceLessonId":"chem.q3.4.buffers","sourceKind":"exercise"},{"id":"chem.q3.4.buffers.exercise.transfer-carbonate","title":"Hydrogencarbonatpuffer deuten","difficulty":"transfer","prompt":"Ein Material beschreibt das Gleichgewicht CO₂/HCO₃⁻ im Blut. Erkläre qualitativ, wie HCO₃⁻ auf eine kleine Säurezugabe reagieren kann. Nenne eine Grenze eines einfachen geschlossenen Puffermodells.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["HCO₃⁻ kann als Base Protonen aufnehmen.","Im Körper können Stoffe transportiert und CO₂ abgeatmet werden."],"solution":"HCO₃⁻ nimmt H₃O⁺ auf und bildet H₂CO₃; dieses steht mit gelöstem CO₂ und Wasser im Gleichgewicht. Das reale System ist nicht geschlossen, weil CO₂ transportiert und abgeatmet wird. Ein einfaches Puffermodell bildet diese Regulation nicht vollständig ab.","competencies":["S","E","B"],"operators":["erläutern","beurteilen"],"sourceLessonId":"chem.q3.4.buffers","sourceKind":"exercise"},{"id":"chem.q3.4.buffers.exercise.transfer-scope","title":"Rechnen oder erklären?","difficulty":"transfer","prompt":"Ein Aufgabenblatt verlangt nur eine qualitative Erklärung der Pufferwirkung, nennt aber keine pKs-Werte. Ist eine quantitative Henderson-Hasselbalch-Rechnung zwingend? Begründe anhand der Angaben.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Prüfe den Operator und die verfügbaren Daten.","Eine Formel darf nicht ohne nötige Werte oder curriculare Grundlage erzwungen werden."],"solution":"Nein. Für eine qualitative Erklärung reicht es, die Reaktion des korrespondierenden Paares mit Säure- oder Basenzugaben zu beschreiben. Eine quantitative Henderson-Hasselbalch-Rechnung erfordert passende Konzentrationen und pKs-Daten und muss durch die konkrete curriculare Vorgabe oder Aufgabe verlangt sein.","competencies":["E","B"],"operators":["beurteilen","begründen"],"sourceLessonId":"chem.q3.4.buffers","sourceKind":"exercise"},{"id":"chem.q3.4.buffers.selftest.components","title":"Bestandteile eines Säurepuffers","difficulty":"basic","prompt":"Welche Teilchen bilden einen Säurepuffer?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Ein korrespondierendes Paar aus schwacher Säure und Base."],"solution":"Eine schwache Säure HA und ihre korrespondierende Base A⁻.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.4.buffers","sourceKind":"selfTest"},{"id":"chem.q3.4.buffers.selftest.acid","title":"Säurezugabe zum Acetatpuffer","difficulty":"basic","prompt":"Was geschieht bei einer kleinen Säurezugabe zu einem Acetatpuffer?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Ethanoat ist die Base des Puffers."],"solution":"CH₃COO⁻ nimmt H₃O⁺ auf und bildet CH₃COOH.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.4.buffers","sourceKind":"selfTest"},{"id":"chem.q3.4.buffers.selftest.capacity","title":"Pufferkapazität","difficulty":"basic","prompt":"Wovon hängt die Pufferkapazität unter anderem ab?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Betrachte absolute Stoffmengen, nicht nur das Verhältnis."],"solution":"Sie hängt unter anderem von den absoluten Stoffmengen der Pufferkomponenten ab.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.4.buffers","sourceKind":"selfTest"},{"id":"chem.q3.5.kinetics.exercise.1","title":"Mittlere Bildungsgeschwindigkeit","difficulty":"basic","prompt":"Die Konzentration eines Produkts steigt in 40 s von 0 auf 0,24 mol·L⁻¹. Berechne die mittlere Bildungsgeschwindigkeit.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["v = Δc / Δt"],"solution":"v = (0,24 − 0) mol·L⁻¹ / 40 s = 0,0060 mol·L⁻¹·s⁻¹.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q3.5.kinetics","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"v","label":"Mittlere Bildungsgeschwindigkeit","value":0.006,"unit":"mol·L⁻¹·s⁻¹"}]}},{"id":"chem.q3.5.kinetics.exercise.2","title":"Einflussfaktoren","difficulty":"basic","prompt":"Nenne vier Faktoren, die die Reaktionsgeschwindigkeit beeinflussen, und gib jeweils an, in welche Richtung sie wirken.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Denke an die Stoßtheorie."],"solution":"Höhere Temperatur erhöht die Geschwindigkeit. Höhere Konzentration der Edukte erhöht sie. Ein höherer Zerteilungsgrad, also eine größere Oberfläche eines Feststoffs, erhöht sie. Ein Katalysator erhöht sie.","competencies":["S"],"operators":["nennen","angeben"],"sourceLessonId":"chem.q3.5.kinetics","sourceKind":"exercise"},{"id":"chem.q3.5.kinetics.exercise.3","title":"Stöchiometrisch normieren","difficulty":"standard","prompt":"Für 2 N₂O₅ → 4 NO₂ + O₂ nimmt c(N₂O₅) in einem Zeitraum mit 0,010 mol·L⁻¹·s⁻¹ ab. Berechne, wie schnell c(NO₂) und c(O₂) zunehmen, und gib die stöchiometrisch normierte Reaktionsgeschwindigkeit an.","taskType":"numeric","afb":2,"supportedModes":["screen","handwriting"],"hints":["Teile jede Konzentrationsänderung durch den Koeffizienten des Stoffes."],"solution":"c(NO₂) nimmt doppelt so schnell zu, wie c(N₂O₅) abnimmt: 0,020 mol·L⁻¹·s⁻¹. c(O₂) nimmt halb so schnell zu: 0,0050 mol·L⁻¹·s⁻¹. Normiert: v = ½ · 0,010 = ¼ · 0,020 = 1 · 0,0050 = 0,0050 mol·L⁻¹·s⁻¹.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q3.5.kinetics","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"no2","label":"Zunahme von c(NO₂)","value":0.02,"unit":"mol·L⁻¹·s⁻¹"},{"id":"o2","label":"Zunahme von c(O₂)","value":0.005,"unit":"mol·L⁻¹·s⁻¹"},{"id":"v","label":"Normierte Reaktionsgeschwindigkeit","value":0.005,"unit":"mol·L⁻¹·s⁻¹"}]}},{"id":"chem.q3.5.kinetics.exercise.4","title":"Temperatur und Stoßtheorie","difficulty":"standard","prompt":"Eine Temperaturerhöhung um 10 K erhöht die Zahl der Zusammenstöße zwischen Teilchen nur um wenige Prozent. Trotzdem verdoppelt sich die Reaktionsgeschwindigkeit oft ungefähr. Erkläre diesen Befund.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Nicht jeder Zusammenstoß führt zur Reaktion.","Betrachte die Energieverteilung der Teilchen."],"solution":"Zur Reaktion führen nur Zusammenstöße, bei denen die Teilchen mindestens die Aktivierungsenergie besitzen. Bei einer Temperaturerhöhung verschiebt sich die Energieverteilung zu höheren Energien. Der Anteil der Teilchen mit ausreichender Energie wächst dadurch überproportional, oft auf etwa das Doppelte. Dieser Effekt ist viel größer als die Zunahme der Stoßzahl.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.q3.5.kinetics","sourceKind":"exercise"},{"id":"chem.q3.5.kinetics.exercise.5","title":"Katalysator und Ausbeute","difficulty":"transfer","prompt":"Eine Aussage lautet: „Der Katalysator bei der Ammoniaksynthese erhöht die Ausbeute an Ammoniak.“ Beurteile die Aussage.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Ein Katalysator beeinflusst Hin- und Rückreaktion gleichermaßen."],"solution":"Die Aussage ist in dieser Form falsch. Der Katalysator senkt die Aktivierungsenergie von Hin- und Rückreaktion gleichermaßen. Das Gleichgewicht stellt sich schneller ein, seine Lage und die Gleichgewichtskonstante bleiben bei gleicher Temperatur aber unverändert. Richtig ist: Er erhöht die in einer bestimmten Zeit gebildete Menge, solange das Gleichgewicht noch nicht erreicht ist, und erlaubt eine niedrigere Arbeitstemperatur, bei der die Gleichgewichtslage günstiger ist.","competencies":["S","B"],"operators":["beurteilen"],"sourceLessonId":"chem.q3.5.kinetics","sourceKind":"exercise"},{"id":"chem.q3.5.kinetics.exercise.6","title":"Messreihe auswerten","difficulty":"transfer","prompt":"Die Konzentration eines Edukts wird gemessen: t = 0 s: 0,80 mol·L⁻¹; 20 s: 0,56 mol·L⁻¹; 40 s: 0,40 mol·L⁻¹; 60 s: 0,28 mol·L⁻¹. Berechne die mittlere Verbrauchsgeschwindigkeit für jedes Intervall und deute den Verlauf. Die Abbildung zeigt die Messwerte.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["v = −Δc / Δt für jedes 20-s-Intervall"],"solution":"0–20 s: v = 0,24 / 20 = 0,012 mol·L⁻¹·s⁻¹. 20–40 s: 0,16 / 20 = 0,0080 mol·L⁻¹·s⁻¹. 40–60 s: 0,12 / 20 = 0,0060 mol·L⁻¹·s⁻¹. Die Geschwindigkeit nimmt ab, weil die Eduktkonzentration sinkt und wirksame Zusammenstöße seltener werden.","competencies":["S","E"],"operators":["berechnen","deuten"],"sourceLessonId":"chem.q3.5.kinetics","sourceKind":"exercise","figures":[{"file":"kinetics-measurements.svg","alt":"Diagramm der Eduktkonzentration gegen die Zeit mit vier Messpunkten: 0,80 mol pro Liter bei 0 s, 0,56 bei 20 s, 0,40 bei 40 s und 0,28 bei 60 s, verbunden durch eine gestrichelte Linie.","placement":"prompt"}]},{"id":"chem.q3.5.kinetics.selftest.1","title":"Wirkung des Katalysators","difficulty":"basic","prompt":"Welche Größe senkt ein Katalysator?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Er bietet einen anderen Reaktionsweg."],"solution":"Die Aktivierungsenergie.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q3.5.kinetics","sourceKind":"selfTest","figures":[{"file":"energy-catalyst.svg","alt":"Energiediagramm einer exothermen Reaktion: Die Kurve ohne Katalysator hat ein hohes Maximum, die gestrichelte Kurve mit Katalysator ein niedrigeres. Pfeile zeigen die beiden Aktivierungsenergien; die Reaktionsenthalpie zwischen Edukten und Produkten ist in beiden Fällen gleich.","caption":"Exotherme Reaktion: Der Katalysator senkt die Aktivierungsenergie, ΔH bleibt gleich.","placement":"solution"}]},{"id":"chem.q3.5.kinetics.selftest.2","title":"Momentane Geschwindigkeit","difficulty":"basic","prompt":"Wie bestimmst du die momentane Reaktionsgeschwindigkeit aus einem Konzentrations-Zeit-Diagramm?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Es geht um einen einzelnen Zeitpunkt."],"solution":"Aus der Steigung der Tangente an die Kurve zu diesem Zeitpunkt.","competencies":["S","E"],"operators":["angeben"],"sourceLessonId":"chem.q3.5.kinetics","sourceKind":"selfTest"},{"id":"chem.q3.5.kinetics.selftest.3","title":"Katalysator und Gleichgewicht","difficulty":"basic","prompt":"Verändert ein Katalysator die Lage eines chemischen Gleichgewichts?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Er beschleunigt beide Richtungen."],"solution":"Nein. Das Gleichgewicht stellt sich nur schneller ein.","competencies":["S"],"operators":["entscheiden"],"sourceLessonId":"chem.q3.5.kinetics","sourceKind":"selfTest"},{"id":"chem.q4.1.enthalpy.exercise.1","title":"Exotherm oder endotherm?","difficulty":"basic","prompt":"Ordne zu und gib jeweils das Vorzeichen von ΔH des Reaktionssystems an: (a) Beim Lösen von Ammoniumnitrat in Wasser kühlt sich die Lösung ab. (b) Eine Kerze brennt und erwärmt die Umgebung.","taskType":"structured","afb":2,"supportedModes":["screen"],"hints":["Betrachte, ob das System Energie an die Umgebung abgibt oder von ihr aufnimmt."],"solution":"(a) Endotherm: Das System nimmt Wärme aus der Umgebung auf, ΔH > 0. (b) Exotherm: Das System gibt Wärme an die Umgebung ab, ΔH < 0.","competencies":["S"],"operators":["zuordnen","angeben"],"sourceLessonId":"chem.q4.1.enthalpy","sourceKind":"exercise"},{"id":"chem.q4.1.enthalpy.exercise.2","title":"Wärmemenge berechnen","difficulty":"basic","prompt":"200 g Wasser erwärmen sich in einem Kalorimeter um 3,5 K. Berechne die vom Wasser aufgenommene Wärme. c(Wasser) = 4,18 J·g⁻¹·K⁻¹.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["q = m · c · ΔT"],"solution":"q = 200 g · 4,18 J·g⁻¹·K⁻¹ · 3,5 K = 2926 J ≈ 2,9 kJ.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q4.1.enthalpy","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"q","label":"Aufgenommene Wärme","value":2.926,"unit":"kJ"}]}},{"id":"chem.q4.1.enthalpy.exercise.3","title":"Neutralisationsenthalpie bestimmen","difficulty":"standard","prompt":"50,0 mL Salzsäure (c = 1,00 mol·L⁻¹) und 50,0 mL Natronlauge (c = 1,00 mol·L⁻¹) werden im Kalorimeter gemischt. Die Temperatur steigt um 6,8 K. Berechne die molare Neutralisationsenthalpie. Nimm an, dass die Lösung eine Masse von 100 g und c = 4,18 J·g⁻¹·K⁻¹ hat und keine Wärme verloren geht.","taskType":"numeric","afb":2,"supportedModes":["screen","handwriting"],"hints":["Berechne zuerst die von der Lösung aufgenommene Wärme.","Teile durch die Stoffmenge der umgesetzten Oxonium-Ionen und achte auf das Vorzeichen."],"solution":"q(Lösung) = 100 g · 4,18 J·g⁻¹·K⁻¹ · 6,8 K = 2842 J. n(H₃O⁺) = 1,00 mol·L⁻¹ · 0,0500 L = 0,0500 mol. Das System gibt die Wärme ab: ΔH = −2842 J / 0,0500 mol ≈ −56,8 kJ·mol⁻¹.","competencies":["S","E"],"operators":["berechnen"],"sourceLessonId":"chem.q4.1.enthalpy","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"dH","label":"Molare Neutralisationsenthalpie ΔH","value":-56.8,"unit":"kJ·mol⁻¹"}]}},{"id":"chem.q4.1.enthalpy.exercise.4","title":"Vorzeichenfehler erklären","difficulty":"standard","prompt":"Bei einer Neutralisation steigt die Temperatur im Kalorimeter. Ein Schüler schreibt: „ΔH = +56,8 kJ·mol⁻¹, weil das Wasser Wärme aufgenommen hat.“ Erkläre den Fehler.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Unterscheide zwischen Reaktionssystem und Umgebung."],"solution":"Die Wärme, die das Wasser als Umgebung aufnimmt, ist positiv. ΔH bezieht sich aber auf das Reaktionssystem, das diese Wärme abgegeben hat. Für das System gilt deshalb ΔH = −q(Umgebung) = −56,8 kJ·mol⁻¹; die Neutralisation ist exotherm.","competencies":["S","K"],"operators":["erklären"],"sourceLessonId":"chem.q4.1.enthalpy","sourceKind":"exercise"},{"id":"chem.q4.1.enthalpy.exercise.5","title":"Abweichung vom Literaturwert","difficulty":"transfer","prompt":"Eine Messung ergibt für die Neutralisationsenthalpie −52 kJ·mol⁻¹, der Literaturwert liegt bei etwa −57 kJ·mol⁻¹. Erkläre, welche Fehlerquelle den Betrag zu klein macht, und schlage zwei Verbesserungen vor.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Überlege, wohin Wärme außer in die Lösung gelangen kann."],"solution":"Ein Teil der freigesetzten Wärme geht an das Gefäß, das Thermometer und die Umgebung verloren. Die gemessene Temperaturerhöhung ist dadurch zu klein, und der berechnete Betrag von ΔH fällt zu gering aus. Verbesserungen: ein gut isoliertes Kalorimeter verwenden und dessen Wärmekapazität vorher bestimmen und berücksichtigen; außerdem die Temperatur bis zum Maximum verfolgen und auf den Mischzeitpunkt extrapolieren.","competencies":["E","B"],"operators":["erklären","vorschlagen"],"sourceLessonId":"chem.q4.1.enthalpy","sourceKind":"exercise"},{"id":"chem.q4.1.enthalpy.exercise.6","title":"Lösungsenthalpie von Ammoniumchlorid","difficulty":"transfer","prompt":"5,35 g Ammoniumchlorid (M = 53,49 g·mol⁻¹) werden in 100 g Wasser gelöst; die Temperatur sinkt um 3,5 K. Berechne die molare Lösungsenthalpie, wenn du die Masse des Salzes bei der Wärmeberechnung vernachlässigst, und deute das Vorzeichen.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["Die Temperaturänderung ist negativ.","q = m · c · ΔT mit c = 4,18 J·g⁻¹·K⁻¹"],"solution":"n(NH₄Cl) = 5,35 g / 53,49 g·mol⁻¹ ≈ 0,100 mol. q(Wasser) = 100 g · 4,18 J·g⁻¹·K⁻¹ · (−3,5 K) = −1463 J; das Wasser hat Wärme abgegeben. ΔH = −q(Wasser) / n = +1463 J / 0,100 mol ≈ +14,6 kJ·mol⁻¹. Das positive Vorzeichen zeigt: Der Lösevorgang ist endotherm, er nimmt Wärme aus der Umgebung auf.","competencies":["S","E"],"operators":["berechnen","deuten"],"sourceLessonId":"chem.q4.1.enthalpy","sourceKind":"exercise"},{"id":"chem.q4.1.enthalpy.selftest.1","title":"Vorzeichen bei exothermen Reaktionen","difficulty":"basic","prompt":"Welches Vorzeichen hat ΔH bei einer exothermen Reaktion?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Das System gibt Energie ab."],"solution":"ΔH ist negativ.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q4.1.enthalpy","sourceKind":"selfTest"},{"id":"chem.q4.1.enthalpy.selftest.2","title":"Kalorimetrie-Formel","difficulty":"basic","prompt":"Wofür stehen die Größen in q = m · c · ΔT?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Eine Größe ist stoffspezifisch."],"solution":"q: übertragene Wärme; m: Masse der erwärmten Flüssigkeit; c: spezifische Wärmekapazität; ΔT: Temperaturänderung.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q4.1.enthalpy","sourceKind":"selfTest"},{"id":"chem.q4.1.enthalpy.selftest.3","title":"Molare Größe","difficulty":"basic","prompt":"Warum teilt man die gemessene Wärme durch die Stoffmenge, um die molare Reaktionsenthalpie anzugeben?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Denke an den Vergleich verschiedener Ansätze."],"solution":"Die Wärme hängt von der umgesetzten Stoffmenge ab. Erst der Bezug auf ein Mol macht Werte aus verschiedenen Ansätzen vergleichbar.","competencies":["S"],"operators":["begründen"],"sourceLessonId":"chem.q4.1.enthalpy","sourceKind":"selfTest"},{"id":"chem.q4.1.entropy-gibbs.exercise.1","title":"Vorzeichen von ΔS abschätzen","difficulty":"basic","prompt":"Gib für die Vorgänge das Vorzeichen der Entropieänderung des Systems an und begründe kurz: (a) H₂O(l) → H₂O(g), (b) N₂(g) + 3 H₂(g) → 2 NH₃(g), (c) CaCO₃(s) → CaO(s) + CO₂(g).","taskType":"structured","afb":2,"supportedModes":["screen"],"hints":["Gasförmige Teilchen haben besonders viele Verteilungsmöglichkeiten.","Vergleiche die Stoffmengen an Gas vor und nach der Reaktion."],"solution":"(a) ΔS > 0: Aus einer Flüssigkeit entsteht ein Gas. (b) ΔS < 0: Aus 4 mol Gas entstehen 2 mol Gas. (c) ΔS > 0: Aus einem Feststoff entsteht unter anderem ein Gas.","competencies":["S"],"operators":["angeben","begründen"],"sourceLessonId":"chem.q4.1.entropy-gibbs","sourceKind":"exercise"},{"id":"chem.q4.1.entropy-gibbs.exercise.2","title":"ΔG der Ammoniaksynthese","difficulty":"basic","prompt":"Für N₂ + 3 H₂ → 2 NH₃ gilt ΔH = −92 kJ·mol⁻¹ und ΔS = −199 J·mol⁻¹·K⁻¹. Berechne ΔG bei 298 K.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Rechne ΔS in kJ·mol⁻¹·K⁻¹ um.","ΔG = ΔH − T·ΔS"],"solution":"T·ΔS = 298 K · (−0,199 kJ·mol⁻¹·K⁻¹) ≈ −59,3 kJ·mol⁻¹. ΔG = −92 − (−59,3) ≈ −32,7 kJ·mol⁻¹.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q4.1.entropy-gibbs","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"dG","label":"ΔG","value":-32.7,"unit":"kJ·mol⁻¹"}]}},{"id":"chem.q4.1.entropy-gibbs.exercise.3","title":"Kalkbrennen","difficulty":"standard","prompt":"Für CaCO₃(s) → CaO(s) + CO₂(g) gilt ΔH = +178 kJ·mol⁻¹ und ΔS = +161 J·mol⁻¹·K⁻¹. Berechne die Temperatur, ab der die Zersetzung thermodynamisch begünstigt ist, und begründe das Vorgehen.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["An der Grenze gilt ΔG = 0.","Nimm ΔH und ΔS als temperaturunabhängig an."],"solution":"Die Zersetzung ist begünstigt, wenn ΔG < 0, also T·ΔS > ΔH. Grenztemperatur: T = ΔH / ΔS = 178 000 J·mol⁻¹ / 161 J·mol⁻¹·K⁻¹ ≈ 1106 K, also etwa 833 °C. Oberhalb dieser Temperatur überwiegt der Entropieterm. Die Rechnung setzt näherungsweise temperaturunabhängige Werte für ΔH und ΔS voraus.","competencies":["S"],"operators":["berechnen","begründen"],"sourceLessonId":"chem.q4.1.entropy-gibbs","sourceKind":"exercise"},{"id":"chem.q4.1.entropy-gibbs.exercise.4","title":"Endotherm und trotzdem freiwillig","difficulty":"standard","prompt":"Ammoniumnitrat löst sich bei Raumtemperatur freiwillig in Wasser, obwohl der Vorgang endotherm ist. Erkläre diesen Befund mit der Gibbs-Helmholtz-Gleichung.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Überlege, wie sich die Ordnung beim Auflösen eines Ionengitters ändert."],"solution":"Beim Lösen wird das geordnete Ionengitter aufgelöst; die Ionen verteilen sich in der Lösung. Die Entropie des Systems nimmt deutlich zu, ΔS > 0. Bei Raumtemperatur ist der Term T·ΔS größer als das positive ΔH. Damit ist ΔG = ΔH − T·ΔS < 0, der Vorgang läuft freiwillig ab.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.q4.1.entropy-gibbs","sourceKind":"exercise"},{"id":"chem.q4.1.entropy-gibbs.exercise.5","title":"Ammoniaksynthese bei 450 °C","difficulty":"transfer","prompt":"Für die Ammoniaksynthese gilt ΔH < 0 und ΔS < 0. Leite ab, ob niedrige oder hohe Temperaturen thermodynamisch günstiger sind. Erläutere, warum die technische Synthese trotzdem bei etwa 450 °C durchgeführt wird.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Betrachte, wie T·ΔS das Vorzeichen von ΔG beeinflusst.","Unterscheide Thermodynamik und Kinetik."],"solution":"Bei ΔS < 0 ist −T·ΔS positiv und wächst mit der Temperatur. ΔG wird daher bei steigender Temperatur weniger negativ; niedrige Temperaturen sind thermodynamisch günstiger. Bei niedriger Temperatur verläuft die Reaktion aber selbst mit Katalysator zu langsam. Die Temperatur von etwa 450 °C ist ein Kompromiss zwischen ausreichender Reaktionsgeschwindigkeit und noch akzeptabler Gleichgewichtslage.","competencies":["S","B"],"operators":["ableiten","erläutern"],"sourceLessonId":"chem.q4.1.entropy-gibbs","sourceKind":"exercise"},{"id":"chem.q4.1.entropy-gibbs.exercise.6","title":"Diamant und Graphit","difficulty":"transfer","prompt":"Für die Umwandlung von Diamant in Graphit gilt bei 298 K ΔG ≈ −2,9 kJ·mol⁻¹. Diamanten bleiben trotzdem praktisch unbegrenzt erhalten. Beurteile den scheinbaren Widerspruch.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["ΔG sagt nichts über die Geschwindigkeit aus."],"solution":"Es liegt kein Widerspruch vor. ΔG < 0 zeigt nur, dass Graphit thermodynamisch stabiler ist. Für die Umwandlung müssten jedoch sehr viele starke kovalente Bindungen im Diamantgitter gelöst und neu geknüpft werden. Die Aktivierungsenergie ist so hoch, dass die Reaktion bei Raumtemperatur unmessbar langsam verläuft. Diamant ist metastabil: thermodynamisch nicht begünstigt, aber kinetisch gehemmt.","competencies":["S","B"],"operators":["beurteilen"],"sourceLessonId":"chem.q4.1.entropy-gibbs","sourceKind":"exercise"},{"id":"chem.q4.1.entropy-gibbs.selftest.1","title":"Temperatureinheit","difficulty":"basic","prompt":"In welcher Einheit setzt du die Temperatur in ΔG = ΔH − T·ΔS ein?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Es ist die absolute Temperatur."],"solution":"In Kelvin.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q4.1.entropy-gibbs","sourceKind":"selfTest"},{"id":"chem.q4.1.entropy-gibbs.selftest.2","title":"Bedeutung von ΔG < 0","difficulty":"basic","prompt":"Was sagt ΔG < 0 über eine Reaktion aus?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Konstanter Druck und konstante Temperatur."],"solution":"Die Reaktion ist unter den gegebenen Bedingungen in der betrachteten Richtung thermodynamisch begünstigt, sie kann freiwillig ablaufen.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q4.1.entropy-gibbs","sourceKind":"selfTest"},{"id":"chem.q4.1.entropy-gibbs.selftest.3","title":"Freiwillig gleich schnell?","difficulty":"basic","prompt":"Läuft eine Reaktion mit ΔG < 0 automatisch schnell ab?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Denke an die Aktivierungsenergie."],"solution":"Nein. ΔG beschreibt die Triebkraft, nicht die Geschwindigkeit; eine hohe Aktivierungsenergie kann die Reaktion sehr langsam machen.","competencies":["S"],"operators":["entscheiden"],"sourceLessonId":"chem.q4.1.entropy-gibbs","sourceKind":"selfTest"},{"id":"chem.q4.1.hess.exercise.1","title":"Gleichung umkehren und verdoppeln","difficulty":"basic","prompt":"Für H₂(g) + ½ O₂(g) → H₂O(l) gilt ΔH = −286 kJ·mol⁻¹. Gib ΔH für die Reaktion 2 H₂O(l) → 2 H₂(g) + O₂(g) an.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Umkehren ändert das Vorzeichen.","Verdoppeln verdoppelt den Betrag."],"solution":"Umkehren: +286 kJ; verdoppeln: ΔH = +572 kJ für den Formelumsatz 2 H₂O(l) → 2 H₂(g) + O₂(g).","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q4.1.hess","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"dH","label":"ΔH","value":572,"unit":"kJ"}]}},{"id":"chem.q4.1.hess.exercise.2","title":"Teilreaktionen addieren","difficulty":"basic","prompt":"Für die Teilreaktionen X → Y gilt ΔH = +30 kJ, für Y → Z gilt ΔH = −75 kJ. Berechne ΔH für X → Z.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Addiere die Gleichungen; Y kürzt sich heraus."],"solution":"ΔH = +30 kJ + (−75 kJ) = −45 kJ.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q4.1.hess","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"dH","label":"ΔH","value":-45,"unit":"kJ"}]}},{"id":"chem.q4.1.hess.exercise.3","title":"Verbrennungsenthalpie aus Bildungsenthalpien","difficulty":"standard","prompt":"Berechne die Standardreaktionsenthalpie für CH₄(g) + 2 O₂(g) → CO₂(g) + 2 H₂O(l). Standardbildungsenthalpien: CH₄(g) −74,8 kJ·mol⁻¹, CO₂(g) −393,5 kJ·mol⁻¹, H₂O(l) −285,8 kJ·mol⁻¹.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["ΔH°_R = Σ ν ΔH°_f(Produkte) − Σ ν ΔH°_f(Edukte)","Die Standardbildungsenthalpie von O₂ ist null."],"solution":"ΔH°_R = [−393,5 + 2 · (−285,8)] − [−74,8 + 2 · 0] = −965,1 + 74,8 = −890,3 kJ·mol⁻¹.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q4.1.hess","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"dH","label":"ΔH°_R","value":-890.3,"unit":"kJ·mol⁻¹"}]}},{"id":"chem.q4.1.hess.exercise.4","title":"Bildungsenthalpie von Kohlenstoffmonooxid","difficulty":"standard","prompt":"Bestimme ΔH für C(s) + ½ O₂(g) → CO(g) aus: (1) C(s) + O₂(g) → CO₂(g), ΔH₁ = −393,5 kJ·mol⁻¹; (2) CO(g) + ½ O₂(g) → CO₂(g), ΔH₂ = −283,0 kJ·mol⁻¹.","taskType":"numeric","afb":2,"supportedModes":["screen","handwriting"],"hints":["Kehre eine der beiden Gleichungen um, damit CO₂ sich kürzt."],"solution":"Gleichung (1) bleibt, Gleichung (2) wird umgekehrt: CO₂(g) → CO(g) + ½ O₂(g), ΔH = +283,0 kJ·mol⁻¹. Addition ergibt C(s) + ½ O₂(g) → CO(g) mit ΔH = −393,5 + 283,0 = −110,5 kJ·mol⁻¹.","competencies":["S"],"operators":["bestimmen"],"sourceLessonId":"chem.q4.1.hess","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"dH","label":"ΔH","value":-110.5,"unit":"kJ·mol⁻¹"}]}},{"id":"chem.q4.1.hess.exercise.5","title":"Hydrierung von Ethen","difficulty":"transfer","prompt":"Berechne ΔH für C₂H₄(g) + H₂(g) → C₂H₆(g) aus den Verbrennungsenthalpien: C₂H₄ −1411 kJ·mol⁻¹, H₂ −286 kJ·mol⁻¹, C₂H₆ −1560 kJ·mol⁻¹. Begründe deinen Rechenweg.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["Formuliere einen Kreisprozess: Edukte verbrennen, Produkt verbrennen.","Bei Verbrennungsenthalpien stehen die Edukte zuerst."],"solution":"Weg 1: Ethen und Wasserstoff werden direkt verbrannt, ΔH = −1411 + (−286) = −1697 kJ. Weg 2: Erst hydrieren (ΔH gesucht), dann Ethan verbrennen (−1560 kJ). Beide Wege führen zu denselben Verbrennungsprodukten, also gilt ΔH + (−1560) = −1697. ΔH = −1697 + 1560 = −137 kJ·mol⁻¹. Allgemein: ΔH_R = Σ ΔH_c(Edukte) − Σ ΔH_c(Produkte).","competencies":["S"],"operators":["berechnen","begründen"],"sourceLessonId":"chem.q4.1.hess","sourceKind":"exercise"},{"id":"chem.q4.1.hess.exercise.6","title":"Warum indirekt messen?","difficulty":"transfer","prompt":"Die Bildungsenthalpie von Kohlenstoffmonooxid lässt sich kalorimetrisch kaum direkt messen. Erläutere den Grund und warum der Satz von Hess hier weiterhilft.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Überlege, welche Produkte bei der Verbrennung von Kohlenstoff entstehen."],"solution":"Verbrennt man Kohlenstoff mit begrenztem Sauerstoff, entsteht ein Gemisch aus CO und CO₂; eine reine Bildung von CO lässt sich nicht erreichen. Die gemessene Wärme gehört daher nicht eindeutig zu der gesuchten Reaktion. Weil die Enthalpie eine Zustandsgröße ist, kann man den Wert aus gut messbaren Reaktionen, den vollständigen Verbrennungen von C und CO, über den Satz von Hess berechnen.","competencies":["S","E"],"operators":["erläutern"],"sourceLessonId":"chem.q4.1.hess","sourceKind":"exercise"},{"id":"chem.q4.1.hess.selftest.1","title":"Gleichung umkehren","difficulty":"basic","prompt":"Was passiert mit ΔH, wenn du eine thermochemische Gleichung umkehrst?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Hin- und Rückweg verbinden dieselben Zustände."],"solution":"ΔH ändert sein Vorzeichen, der Betrag bleibt gleich.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q4.1.hess","sourceKind":"selfTest"},{"id":"chem.q4.1.hess.selftest.2","title":"Gleichung vervielfachen","difficulty":"basic","prompt":"Was passiert mit ΔH, wenn du alle Koeffizienten einer Gleichung mit 3 multiplizierst?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["ΔH bezieht sich auf den Formelumsatz."],"solution":"ΔH wird ebenfalls mit 3 multipliziert.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q4.1.hess","sourceKind":"selfTest"},{"id":"chem.q4.1.hess.selftest.3","title":"Zustandsgröße","difficulty":"basic","prompt":"Was bedeutet es, dass die Enthalpie eine Zustandsgröße ist?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Denke an verschiedene Reaktionswege."],"solution":"Die Enthalpieänderung hängt nur von Anfangs- und Endzustand ab, nicht vom Weg dazwischen.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q4.1.hess","sourceKind":"selfTest"},{"id":"chem.q4.2.energy-sustainability.exercise.1","title":"Wirkungsgrad einer Brennstoffzelle","difficulty":"basic","prompt":"Eine Brennstoffzelle setzt Wasserstoff mit einem Energieinhalt von 4,0 MJ um und liefert 2,4 MJ elektrische Energie. Berechne den Wirkungsgrad.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["η = E_nutz / E_zugeführt · 100 %"],"solution":"η = 2,4 MJ / 4,0 MJ · 100 % = 60 %.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.q4.2.energy-sustainability","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"eta","label":"Wirkungsgrad η","value":60,"unit":"%","tolerance":{"absolute":0.5}}]}},{"id":"chem.q4.2.energy-sustainability.exercise.2","title":"Teilreaktionen der Brennstoffzelle","difficulty":"basic","prompt":"Formuliere für eine Wasserstoff-Sauerstoff-Brennstoffzelle mit saurem Elektrolyten die Reaktionen an Anode und Kathode sowie die Gesamtreaktion.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["An der Anode wird oxidiert, an der Kathode reduziert."],"solution":"Anode: H₂ → 2 H⁺ + 2 e⁻. Kathode: O₂ + 4 H⁺ + 4 e⁻ → 2 H₂O. Gesamt: 2 H₂ + O₂ → 2 H₂O.","competencies":["S"],"operators":["formulieren"],"sourceLessonId":"chem.q4.2.energy-sustainability","sourceKind":"exercise"},{"id":"chem.q4.2.energy-sustainability.exercise.3","title":"Wirkungsgrad einer Energiekette","difficulty":"standard","prompt":"Strom wird über Elektrolyse in Wasserstoff umgewandelt (angenommener Wirkungsgrad 70 %), der Wasserstoff verdichtet und gespeichert (90 %) und in einer Brennstoffzelle wieder verstromt (55 %). Berechne den Gesamtwirkungsgrad und erläutere das Ergebnis.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["Die Wirkungsgrade einer Kette werden multipliziert."],"solution":"η_gesamt = 0,70 · 0,90 · 0,55 ≈ 0,35, also etwa 35 %. Rund zwei Drittel der eingesetzten elektrischen Energie gehen in der Kette verloren, vor allem als Wärme. Jeder Umwandlungsschritt verringert den Gesamtwirkungsgrad.","competencies":["S","E"],"operators":["berechnen","erläutern"],"sourceLessonId":"chem.q4.2.energy-sustainability","sourceKind":"exercise"},{"id":"chem.q4.2.energy-sustainability.exercise.4","title":"Ist Bioethanol CO₂-neutral?","difficulty":"standard","prompt":"Bioethanol wird häufig als „CO₂-neutral“ bezeichnet. Erläutere, was an dieser Aussage zutrifft und was sie vernachlässigt.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Vergleiche die CO₂-Bilanz von Pflanze und Verbrennung.","Denke an den gesamten Herstellungsweg."],"solution":"Bei der Verbrennung wird etwa so viel CO₂ frei, wie die Pflanzen beim Wachsen durch Fotosynthese gebunden haben; insofern ist die Verbrennung selbst annähernd ausgeglichen. Vernachlässigt werden Emissionen aus Anbau, Düngemittelherstellung, Ernte, Transport sowie aus Gärung und Destillation. Über den gesamten Lebensweg ist Bioethanol daher nicht vollständig CO₂-neutral.","competencies":["S","B"],"operators":["erläutern"],"sourceLessonId":"chem.q4.2.energy-sustainability","sourceKind":"exercise"},{"id":"chem.q4.2.energy-sustainability.exercise.5","title":"Batterie oder Wasserstoff im Pkw","difficulty":"transfer","prompt":"Annahmen: Vom Strom aus dem Netz bis zum Antrieb erreicht ein Batteriefahrzeug einen Gesamtwirkungsgrad von 75 %, ein Wasserstoff-Brennstoffzellenfahrzeug mit elektrolytisch erzeugtem Wasserstoff 30 %. Bewerte die beiden Antriebe anhand des Wirkungsgrads und mindestens zwei weiterer Kriterien.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Ein einzelnes Kriterium reicht nicht für ein Gesamturteil.","Mögliche Kriterien: Rohstoffe, Tankdauer und Reichweite, Infrastruktur."],"solution":"Wirkungsgrad: Das Batteriefahrzeug nutzt die eingesetzte Energie etwa 2,5-mal besser; für dieselbe Fahrleistung braucht der Wasserstoffweg deutlich mehr Strom. Rohstoffe: Batterien benötigen Stoffe wie Lithium, Nickel oder Cobalt, Brennstoffzellen geringe Mengen Platin; beide Rohstoffketten haben ökologische und soziale Folgen. Nutzung: Wasserstoff lässt sich in wenigen Minuten tanken, Batterien laden länger; dafür ist das Stromnetz bereits verbreitet, die Wasserstoffinfrastruktur kaum. Ein Gesamturteil hängt davon ab, wie die Kriterien gewichtet werden und woher der Strom stammt; bei begrenztem erneuerbarem Strom spricht der Wirkungsgrad deutlich für die Batterie.","competencies":["B"],"operators":["bewerten"],"sourceLessonId":"chem.q4.2.energy-sustainability","sourceKind":"exercise"},{"id":"chem.q4.2.energy-sustainability.exercise.6","title":"Biodiesel herstellen","difficulty":"transfer","prompt":"Biodiesel entsteht durch Umesterung von Rapsöl mit Methanol. Formuliere die Reaktion in allgemeiner Form für ein Triacylglycerid und beurteile einen ökologischen Nachteil von Biodiesel aus Raps.","taskType":"free-response","afb":3,"supportedModes":["screen","handwriting"],"hints":["Jede der drei Esterbindungen wird auf Methanol übertragen.","Denke an den Flächenbedarf."],"solution":"Triacylglycerid + 3 CH₃OH → 3 R–COOCH₃ + Glycerin (C₃H₅(OH)₃); die Reaktion wird katalysiert, zum Beispiel basisch. Es entstehen Fettsäuremethylester (Biodiesel) und Glycerin. Ein ökologischer Nachteil ist der hohe Flächenbedarf: Rapsanbau konkurriert mit der Nahrungsmittelproduktion und benötigt Dünger, dessen Herstellung und Ausbringung Emissionen verursacht. Biodiesel kann daher fossilen Diesel nur begrenzt ersetzen.","competencies":["S","B"],"operators":["formulieren","beurteilen"],"sourceLessonId":"chem.q4.2.energy-sustainability","sourceKind":"exercise"},{"id":"chem.q4.2.energy-sustainability.selftest.1","title":"Wirkungsgrad","difficulty":"basic","prompt":"Was gibt der Wirkungsgrad eines Energiewandlers an?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Er ist ein Verhältnis zweier Energien."],"solution":"Den Anteil der zugeführten Energie, der als nutzbare Energie abgegeben wird.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q4.2.energy-sustainability","sourceKind":"selfTest"},{"id":"chem.q4.2.energy-sustainability.selftest.2","title":"Produkt der Brennstoffzelle","difficulty":"basic","prompt":"Welcher Stoff entsteht in einer Wasserstoff-Sauerstoff-Brennstoffzelle?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Denke an die Gesamtreaktion."],"solution":"Wasser.","competencies":["S"],"operators":["angeben"],"sourceLessonId":"chem.q4.2.energy-sustainability","sourceKind":"selfTest"},{"id":"chem.q4.2.energy-sustainability.selftest.3","title":"Fairer Vergleich","difficulty":"basic","prompt":"Warum müssen zwei Energiespeicher mit derselben Systemgrenze verglichen werden?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Überlege, was passiert, wenn bei einem Speicher die Herstellung fehlt."],"solution":"Sonst werden unterschiedliche Abschnitte des Lebenswegs verglichen, etwa nur der Betrieb des einen und auch die Herstellung des anderen. Das Ergebnis wäre verzerrt.","competencies":["B"],"operators":["begründen"],"sourceLessonId":"chem.q4.2.energy-sustainability","sourceKind":"selfTest"},{"id":"chem.experimental.observation.exercise.basic-observation","title":"Beobachtung oder Deutung?","difficulty":"basic","prompt":"Ordne jede Aussage als Beobachtung oder Deutung ein: (a) Die Lösung färbt sich von blau nach farblos. (b) Es entsteht Wasserstoff. (c) Am Boden des Reagenzglases setzt sich ein weißer Feststoff ab. (d) Die Temperatur steigt von 21 °C auf 34 °C. (e) Die Reaktion ist exotherm.","taskType":"matching","afb":2,"supportedModes":["screen"],"hints":["Eine Beobachtung kannst du sehen, riechen, hören oder messen.","Sobald ein Stoffname eines Produkts oder ein Fachbegriff zur Erklärung vorkommt, ist es meist eine Deutung."],"solution":"Beobachtungen: (a), (c), (d). Deutungen: (b) nennt ein Produkt, das nur durch einen Nachweis erschlossen werden kann; (e) ist die Erklärung der gemessenen Temperaturerhöhung.","competencies":["E","K"],"operators":["zuordnen","unterscheiden"],"sourceLessonId":"chem.experimental.observation","sourceKind":"exercise","answer":{"kind":"matching","options":["Beobachtung","Deutung"],"items":[{"id":"a","label":"(a) Die Lösung färbt sich von blau nach farblos.","correct":"Beobachtung"},{"id":"b","label":"(b) Es entsteht Wasserstoff.","correct":"Deutung"},{"id":"c","label":"(c) Am Boden setzt sich ein weißer Feststoff ab.","correct":"Beobachtung"},{"id":"d","label":"(d) Die Temperatur steigt von 21 °C auf 34 °C.","correct":"Beobachtung"},{"id":"e","label":"(e) Die Reaktion ist exotherm.","correct":"Deutung"}]}},{"id":"chem.experimental.observation.exercise.basic-variables","title":"Variablen festlegen","difficulty":"basic","prompt":"Du untersuchst, wie die Temperatur die Geschwindigkeit der Reaktion von Magnesiumband mit Salzsäure beeinflusst. Nenne die unabhängige Variable, die abhängige Variable und drei Größen, die konstant bleiben müssen.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die unabhängige Variable veränderst du gezielt.","Überlege, was außer der Temperatur die Reaktionsgeschwindigkeit noch beeinflusst."],"solution":"Unabhängige Variable: Temperatur der Salzsäure. Abhängige Variable: Reaktionsgeschwindigkeit, zum Beispiel gemessen als Zeit bis zum Auflösen des Magnesiums oder als Gasvolumen pro Zeit. Konstant: Konzentration und Volumen der Salzsäure, Masse und Oberfläche des Magnesiumbands, Rühren.","competencies":["E"],"operators":["bestimmen","nennen"],"sourceLessonId":"chem.experimental.observation","sourceKind":"exercise"},{"id":"chem.experimental.observation.exercise.standard-blank","title":"Wozu eine Blindprobe?","difficulty":"standard","prompt":"Eine Schülergruppe führt die Fehling-Probe mit einer Probelösung durch und erhält einen rotbraunen Niederschlag. Eine Blindprobe mit Wasser wurde nicht angesetzt. Erläutere, welche Fehldeutung dadurch möglich ist, und beschreibe die fehlende Blindprobe.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Überlege, was passiert, wenn die Fehling-Lösung oder das Reagenzglas bereits verunreinigt ist.","Die Blindprobe enthält alles außer der Probe."],"solution":"Ohne Blindprobe bleibt offen, ob der Niederschlag von der Probe stammt. Ein verunreinigtes Reagenzglas, eine verunreinigte Fehling-Lösung oder zu starkes Erhitzen könnten ebenfalls zu einem Niederschlag führen. Die Blindprobe enthält das gleiche Volumen Wasser statt der Probe sowie die gleiche Menge Fehling-Lösung und wird genauso erwärmt. Bleibt sie blau, kann der Niederschlag im Probeansatz der Probe zugeordnet werden.","competencies":["E","B"],"operators":["erläutern","beschreiben"],"sourceLessonId":"chem.experimental.observation","sourceKind":"exercise"},{"id":"chem.experimental.observation.exercise.standard-errors","title":"Fehler einordnen","difficulty":"standard","prompt":"Bei einer Titration liest eine Person den Flüssigkeitsstand der Bürette jedes Mal von schräg oben ab. Eine zweite Person erhält bei fünf Wiederholungen die Volumina 12,3 mL, 12,6 mL, 12,2 mL, 12,5 mL und 12,4 mL. Ordne beide Fälle einem Fehlertyp zu und nenne jeweils eine Gegenmaßnahme.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Prüfe, ob der Fehler die Werte immer in dieselbe Richtung verschiebt.","Bilde für die zweite Person den Mittelwert."],"solution":"Schräges Ablesen von oben ist ein systematischer Fehler, weil jeder Wert in dieselbe Richtung verfälscht wird. Gegenmaßnahme: auf Augenhöhe am unteren Rand des Meniskus ablesen. Die Streuung der fünf Werte ist ein zufälliger Fehler. Gegenmaßnahme: Mehrfachmessungen und Mittelwert, hier x̄ = 62,0 mL / 5 = 12,4 mL.","competencies":["E"],"operators":["zuordnen","nennen"],"sourceLessonId":"chem.experimental.observation","sourceKind":"exercise","figures":[{"file":"meniscus-reading.svg","alt":"Ausschnitt einer Bürette mit nach unten zunehmender Skala und gewölbtem Flüssigkeitsspiegel. Drei Augen blicken auf den tiefsten Punkt des Meniskus: Von schräg oben wird 12,30 mL abgelesen (zu klein), auf Augenhöhe 12,35 mL (richtig), von schräg unten 12,40 mL (zu groß).","caption":"Schräges Ablesen verschiebt jeden Wert in dieselbe Richtung.","placement":"solution"}]},{"id":"chem.experimental.observation.exercise.transfer-fructose","title":"Schlussfolgerung prüfen","difficulty":"transfer","prompt":"Ein Schüler beobachtet bei der Fehling-Probe mit Fructose einen rotbraunen Niederschlag. Er folgert: „Fructose besitzt eine Aldehydgruppe.“ Beurteile diese Schlussfolgerung.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Fructose ist eine Ketohexose.","Bedenke die Bedingungen der Fehling-Probe: heiß und alkalisch."],"solution":"Die Schlussfolgerung ist nicht haltbar. Fructose ist eine Ketose und besitzt in der offenkettigen Form eine Ketogruppe. In der heißen alkalischen Fehling-Lösung lagert sich Fructose über ein Endiol in Aldosen um. Diese wirken reduzierend und reduzieren Cu²⁺ zu Cu₂O. Der positive Test zeigt nur, dass unter den Testbedingungen ein reduzierend wirkender Stoff vorliegt, nicht dass das Ausgangsmolekül eine Aldehydgruppe besitzt.","competencies":["E","B"],"operators":["beurteilen","begründen"],"sourceLessonId":"chem.experimental.observation","sourceKind":"exercise"},{"id":"chem.experimental.observation.exercise.transfer-plan","title":"Experiment zur Kerzenflamme planen","difficulty":"transfer","prompt":"Plane ein Experiment, mit dem man prüfen kann, ob bei der Verbrennung von Kerzenwachs Kohlenstoffdioxid entsteht. Formuliere eine Hypothese, beschreibe Durchführung, Kontrolle und erwartete Beobachtung und nenne eine Sicherheitsmaßnahme.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die Verbrennungsgase müssen aufgefangen und in ein Nachweisreagenz geleitet werden.","Überlege, womit du vergleichst, damit Kohlenstoffdioxid aus der Raumluft nicht stört."],"solution":"Hypothese: Wenn Kerzenwachs verbrennt, entsteht Kohlenstoffdioxid, das Kalkwasser trübt. Durchführung: Die Verbrennungsgase werden mit einem Trichter über der Flamme abgesaugt und durch klares Kalkwasser geleitet. Kontrolle: Gleich lange und gleich viel Raumluft ohne Flamme durch eine zweite Kalkwasserprobe leiten. Erwartung: Nur der Probeansatz wird deutlich milchig trüb. Sicherheit: Schutzbrille, nichts Brennbares in Flammennähe, Kerze standsicher aufstellen.","competencies":["E","K"],"operators":["planen","beschreiben"],"sourceLessonId":"chem.experimental.observation","sourceKind":"exercise"},{"id":"chem.experimental.observation.selftest.positive-control","title":"Positivkontrolle","difficulty":"basic","prompt":"Welche Information liefert eine Positivkontrolle bei einem Nachweis?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Sie enthält einen Stoff, der sicher positiv reagiert."],"solution":"Sie zeigt, dass das Nachweisreagenz unter den gewählten Bedingungen funktioniert. Nur dann ist ein negatives Ergebnis im Probeansatz aussagekräftig.","competencies":["E"],"operators":["angeben"],"sourceLessonId":"chem.experimental.observation","sourceKind":"selfTest"},{"id":"chem.experimental.observation.selftest.negative-result","title":"Negatives Ergebnis","difficulty":"basic","prompt":"Nenne zwei Gründe, warum ein negativer Nachweis einen Stoff nicht sicher ausschließt.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Denke an Menge und Bedingungen."],"solution":"Die Konzentration kann unter der Nachweisgrenze liegen. Die Bedingungen wie Temperatur, pH-Wert oder Reaktionszeit können ungeeignet sein, oder das Reagenz ist unbrauchbar.","competencies":["E","B"],"operators":["nennen"],"sourceLessonId":"chem.experimental.observation","sourceKind":"selfTest"},{"id":"chem.experimental.observation.selftest.hypothesis","title":"Hypothese formulieren","difficulty":"basic","prompt":"Formuliere eine prüfbare Hypothese zur Frage, ob eine Lösung Chlorid-Ionen enthält.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Nutze die Form „Wenn …, dann …“ und nenne eine erwartete Beobachtung."],"solution":"Zum Beispiel: Wenn die Lösung Chlorid-Ionen enthält, bildet sich nach Ansäuern mit Salpetersäure und Zugabe von Silbernitrat-Lösung ein weißer Niederschlag.","competencies":["E","K"],"operators":["formulieren"],"sourceLessonId":"chem.experimental.observation","sourceKind":"selfTest"},{"id":"chem.experimental.qualitative.exercise.basic-limewater","title":"Kalkwasser deuten","difficulty":"basic","prompt":"Bei der Verbrennung von Ethanol entsteht ein Gas, das Kalkwasser trübt. Nenne das Gas und formuliere die Reaktionsgleichung für die Trübung. Die Abbildung zeigt den Versuchsaufbau.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Ethanol ist eine organische Verbindung mit Kohlenstoff-Atomen.","Die Trübung entsteht durch einen schwer löslichen Feststoff."],"solution":"Das Gas ist Kohlenstoffdioxid. Im Kalkwasser bildet sich schwer lösliches Calciumcarbonat: Ca²⁺ + 2 OH⁻ + CO₂ → CaCO₃↓ + H₂O.","competencies":["S","E"],"operators":["benennen","formulieren"],"sourceLessonId":"chem.experimental.qualitative","sourceKind":"exercise","figures":[{"file":"limewater-test.svg","alt":"Über einer Ethanolflamme hängt ein umgedrehter Trichter. Ein Schlauch führt die angesaugten Verbrennungsgase in eine Waschflasche mit Kalkwasser, wo sie durch die Lösung perlen; ein zweites Rohr führt zur Wasserstrahlpumpe. Das Kalkwasser ist milchig trüb.","placement":"prompt"}]},{"id":"chem.experimental.qualitative.exercise.basic-water","title":"Wasser nachweisen","difficulty":"basic","prompt":"Beschreibe, wie du nachweisen kannst, dass sich an einem kalten Becherglas über einer Kerzenflamme Wasser niederschlägt. Gib Beobachtung und Deutung an.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Ein weißes Salz ändert bei Kontakt mit Wasser seine Farbe."],"solution":"Man bringt etwas wasserfreies, weißes Kupfer(II)-sulfat mit dem Beschlag in Kontakt. Beobachtung: Das Pulver färbt sich blau. Deutung: Es bildet sich das blaue Hydrat CuSO₄ · 5 H₂O, der Beschlag enthält also Wasser.","competencies":["E","K"],"operators":["beschreiben","deuten"],"sourceLessonId":"chem.experimental.qualitative","sourceKind":"exercise"},{"id":"chem.experimental.qualitative.exercise.standard-carbonate","title":"Carbonat in Eierschalen","difficulty":"standard","prompt":"Eierschalen bestehen überwiegend aus Calciumcarbonat. Plane einen Nachweis für Carbonat in Eierschalen und formuliere für beide Schritte die Reaktionsgleichungen.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Der Nachweis besteht aus zwei aufeinanderfolgenden Reaktionen.","Das freigesetzte Gas muss selbst nachgewiesen werden."],"solution":"Schritt 1: Zerkleinerte Eierschalen werden mit verdünnter Salzsäure versetzt; es tritt Gasentwicklung auf: CaCO₃ + 2 H₃O⁺ → Ca²⁺ + CO₂ + 3 H₂O. Schritt 2: Das Gas wird in Kalkwasser geleitet, das sich trübt: Ca²⁺ + 2 OH⁻ + CO₂ → CaCO₃↓ + H₂O. Erst beide Beobachtungen zusammen weisen auf Carbonat hin.","competencies":["E","S"],"operators":["planen","formulieren"],"sourceLessonId":"chem.experimental.qualitative","sourceKind":"exercise"},{"id":"chem.experimental.qualitative.exercise.standard-ammonium","title":"Ammonium-Ionen im Dünger","difficulty":"standard","prompt":"Ein Dünger soll auf Ammonium-Ionen untersucht werden. Man versetzt eine Probe mit Natronlauge, erwärmt leicht und hält angefeuchtetes Universalindikatorpapier darüber. Das Papier färbt sich blau. Erkläre die Beobachtung mit Reaktionsgleichungen.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Hydroxid-Ionen sind Protonenakzeptoren.","Das entweichende Gas reagiert im Wasser auf dem Papier."],"solution":"Die Hydroxid-Ionen deprotonieren die Ammonium-Ionen; Ammoniak entweicht: NH₄⁺ + OH⁻ → NH₃ + H₂O. Im Wasser auf dem Indikatorpapier nimmt Ammoniak Protonen auf: NH₃ + H₂O ⇌ NH₄⁺ + OH⁻. Die entstehenden Hydroxid-Ionen färben den Indikator blau. Da das Papier die Natronlauge nicht berührt, stammt die Färbung vom Gas.","competencies":["S","E"],"operators":["erklären","formulieren"],"sourceLessonId":"chem.experimental.qualitative","sourceKind":"exercise"},{"id":"chem.experimental.qualitative.exercise.transfer-halides","title":"Drei Halogenide unterscheiden","difficulty":"transfer","prompt":"Drei unbeschriftete Lösungen enthalten Natriumchlorid, Natriumbromid und Natriumiodid. Entwickle ein Vorgehen, mit dem du die Lösungen zuordnen kannst, und begründe, warum die Niederschlagsfarbe allein unsicher ist.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die Silberhalogenide unterscheiden sich in Farbe und Löslichkeit in Ammoniak-Lösung.","Überlege, wie gut sich weiß und gelblich weiß unterscheiden lassen."],"solution":"Jede Lösung mit verdünnter Salpetersäure ansäuern und Silbernitrat-Lösung zugeben. Silberchlorid fällt weiß, Silberbromid gelblich weiß, Silberiodid gelb aus. Da die Farben ähnlich sind und Silberchlorid sich im Licht dunkel färbt, gibt man anschließend verdünnte Ammoniak-Lösung zu den Niederschlägen: Silberchlorid löst sich, Silberbromid kaum, Silberiodid nicht. Die Kombination aus Farbe und Löslichkeit ermöglicht die Zuordnung.","competencies":["E","B"],"operators":["entwickeln","begründen"],"sourceLessonId":"chem.experimental.qualitative","sourceKind":"exercise","figures":[{"file":"silver-halides.svg","alt":"Zwei Reihen mit je drei Reagenzgläsern für NaCl, NaBr und NaI. Oben nach Ansäuern und Zugabe von Silbernitrat: weißer, gelblich weißer und gelber Niederschlag. Unten nach Zugabe von verdünnter Ammoniak-Lösung: Der weiße Niederschlag hat sich gelöst, der gelblich weiße kaum, der gelbe nicht.","placement":"solution"}]},{"id":"chem.experimental.qualitative.exercise.transfer-organic-halide","title":"Kein Niederschlag bei Chlorethan","difficulty":"transfer","prompt":"Gibt man Silbernitrat-Lösung zu einer Lösung von Chlorethan in Ethanol, entsteht zunächst kein Niederschlag. Nach längerem Erwärmen mit Wasser bildet sich langsam ein weißer Niederschlag. Erkläre beide Beobachtungen.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Unterscheide zwischen kovalent gebundenem Chlor und Chlorid-Ionen.","Beim Erwärmen mit Wasser kann eine Substitution ablaufen."],"solution":"Im Chlorethan-Molekül ist das Chlor-Atom kovalent gebunden. Es liegen keine freien Chlorid-Ionen vor, deshalb fällt zunächst kein Silberchlorid aus. Beim Erwärmen mit Wasser wird das Chlor-Atom langsam nucleophil substituiert: C₂H₅Cl + H₂O → C₂H₅OH + H⁺ + Cl⁻. Die freigesetzten Chlorid-Ionen bilden mit den Silber-Ionen weißes Silberchlorid: Ag⁺ + Cl⁻ → AgCl↓.","competencies":["S","E"],"operators":["erklären","formulieren"],"sourceLessonId":"chem.experimental.qualitative","sourceKind":"exercise"},{"id":"chem.experimental.qualitative.selftest.nitric-acid","title":"Warum Salpetersäure?","difficulty":"basic","prompt":"Warum säuert man vor dem Chlorid-Nachweis mit Salpetersäure und nicht mit Salzsäure an?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Prüfe, welche Ionen die Salzsäure mitbringt."],"solution":"Das Ansäuern verhindert Niederschläge mit Carbonat- oder Hydroxid-Ionen. Salzsäure enthält selbst Chlorid-Ionen und würde den Nachweis immer positiv ausfallen lassen; Nitrat-Ionen stören nicht.","competencies":["E"],"operators":["begründen"],"sourceLessonId":"chem.experimental.qualitative","sourceKind":"selfTest"},{"id":"chem.experimental.qualitative.selftest.indicator-gas","title":"Indikatorpapier für Gase","difficulty":"basic","prompt":"Warum muss Universalindikatorpapier für den Nachweis eines Gases angefeuchtet werden?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Saure oder basische Wirkung zeigt sich erst in einer Reaktion mit Wasser."],"solution":"Erst im Wasser auf dem Papier kann das Gas eine Protolyse eingehen und Oxonium- oder Hydroxid-Ionen bilden. Diese bewirken die Farbänderung des Indikators.","competencies":["S","E"],"operators":["begründen"],"sourceLessonId":"chem.experimental.qualitative","sourceKind":"selfTest"},{"id":"chem.experimental.qualitative.selftest.copper-sulfate","title":"Kupfer(II)-sulfat","difficulty":"basic","prompt":"Wasserfreies Kupfer(II)-sulfat färbt sich mit einer Flüssigkeit blau. Ist die Flüssigkeit damit als reines Wasser identifiziert?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Der Test spricht auf das Vorhandensein von Wasser an."],"solution":"Nein. Der Test zeigt nur, dass Wasser enthalten ist. Auch wässrige Lösungen oder wasserhaltige Gemische färben das Salz blau.","competencies":["E","B"],"operators":["entscheiden","begründen"],"sourceLessonId":"chem.experimental.qualitative","sourceKind":"selfTest"},{"id":"chem.experimental.organic-tests.exercise.basic-match","title":"Passenden Nachweis wählen","difficulty":"basic","prompt":"Ordne jedem Stoff einen geeigneten Nachweis zu und gib die Beobachtung bei positivem Verlauf an: (a) Propanal, (b) Stärke, (c) Hühnereiweiß, (d) Propen.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Bestimme zuerst das jeweilige Strukturmerkmal.","Für (c) eignet sich ein Nachweis für Peptidbindungen."],"solution":"(a) Aldehydgruppe: Fehling-Probe, beim Erwärmen rotbrauner Niederschlag; alternativ Silberspiegel nach Tollens. (b) Iod-Kaliumiodid-Lösung: blauschwarze Färbung. (c) Biuret-Reaktion: violette Färbung. (d) C=C-Doppelbindung: Baeyer-Probe, die violette Lösung entfärbt sich und es entsteht ein brauner Niederschlag; alternativ Entfärbung von Bromwasser.","competencies":["S","E"],"operators":["zuordnen","angeben"],"sourceLessonId":"chem.experimental.organic-tests","sourceKind":"exercise"},{"id":"chem.experimental.organic-tests.exercise.basic-fehling","title":"Fehling-Probe beschreiben","difficulty":"basic","prompt":"Beschreibe die Durchführung der Fehling-Probe und die Beobachtung bei positivem Verlauf.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Fehling-Lösung wird aus zwei Teillösungen frisch gemischt.","Die Probe muss erwärmt werden."],"solution":"Fehling-Lösung I (Kupfer(II)-sulfat-Lösung) und Fehling-Lösung II (alkalische Kaliumnatriumtartrat-Lösung) werden zu gleichen Teilen gemischt; es entsteht eine tiefblaue Lösung. Diese gibt man zur Probelösung und erwärmt im Wasserbad. Bei positivem Verlauf verschwindet die blaue Farbe zunehmend, und es bildet sich ein rotbrauner Niederschlag von Kupfer(I)-oxid.","competencies":["E","K"],"operators":["beschreiben"],"sourceLessonId":"chem.experimental.organic-tests","sourceKind":"exercise","figures":[{"file":"fehling-test.svg","alt":"Drei Reagenzgläser: Links die tiefblaue Mischung aus Fehling I, Fehling II und Probe. In der Mitte nach Erwärmen im Wasserbad bei positivem Verlauf eine heller gewordene Lösung mit rotbraunem Niederschlag von Kupfer(I)-oxid. Rechts nach Erwärmen bei negativem Verlauf eine blau gebliebene Lösung.","placement":"solution"}]},{"id":"chem.experimental.organic-tests.exercise.standard-disaccharides","title":"Maltose und Saccharose","difficulty":"standard","prompt":"Maltose reagiert bei der Fehling-Probe positiv, Saccharose negativ. Erkläre den Unterschied mit dem Bau der beiden Disaccharide.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Untersuche, welche anomeren C-Atome an der glycosidischen Bindung beteiligt sind.","Nur eine freie Halbacetalgruppe kann sich zur offenkettigen Form öffnen."],"solution":"In Maltose sind zwei Glucose-Einheiten α-1,4-glycosidisch verknüpft. Das anomere C-Atom der zweiten Glucose-Einheit bleibt frei. Diese Halbacetalgruppe kann sich öffnen und bildet eine Aldehydgruppe, die Cu²⁺ reduziert. In Saccharose sind das anomere C-Atom C1 der Glucose und das anomere C-Atom C2 der Fructose gemeinsam an der glycosidischen Bindung beteiligt. Es gibt keine freie Halbacetalgruppe, keine Ringöffnung und daher keine reduzierende Wirkung.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.experimental.organic-tests","sourceKind":"exercise"},{"id":"chem.experimental.organic-tests.exercise.standard-protein","title":"Zwei Proteinnachweise auswerten","difficulty":"standard","prompt":"Eine Probe ergibt bei der Biuret-Reaktion eine violette Färbung, bei der Xanthoprotein-Reaktion aber keine Gelbfärbung. Deute die beiden Ergebnisse.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die beiden Proben sprechen auf unterschiedliche Strukturmerkmale an."],"solution":"Die Biuret-Reaktion zeigt mindestens zwei Peptidbindungen an; die Probe enthält also Peptide oder Proteine. Die Xanthoprotein-Reaktion spricht auf aromatische Seitenketten an. Ihr negativer Verlauf spricht dafür, dass das Peptid keine oder nur sehr wenige aromatische Aminosäure-Reste wie Phenylalanin oder Tyrosin enthält.","competencies":["S","E"],"operators":["deuten"],"sourceLessonId":"chem.experimental.organic-tests","sourceKind":"exercise"},{"id":"chem.experimental.organic-tests.exercise.transfer-unknown","title":"Zwei Isomere mit der Formel C₃H₆O","difficulty":"transfer","prompt":"Zwei Flüssigkeiten besitzen die Summenformel C₃H₆O. Es handelt sich um Propanal und Propanon. Entwickle einen Nachweis zur Zuordnung, formuliere die Reaktionsgleichung für den positiven Fall und begründe das unterschiedliche Verhalten.","taskType":"free-response","afb":2,"supportedModes":["screen","handwriting"],"hints":["Aldehyde und Ketone unterscheiden sich in ihrer Oxidierbarkeit.","Nutze die vereinfachte Gleichung der Fehling-Probe."],"solution":"Beide Flüssigkeiten werden der Fehling-Probe unterzogen, mit Blindprobe. Propanal besitzt eine Aldehydgruppe mit einem H-Atom am Carbonyl-C und wird zur Propansäure oxidiert; es entsteht ein rotbrauner Niederschlag: CH₃CH₂CHO + 2 Cu²⁺ + 5 OH⁻ → CH₃CH₂COO⁻ + Cu₂O + 3 H₂O. Propanon ist ein Keton; am Carbonyl-C sitzt kein H-Atom, unter diesen milden Bedingungen findet keine Oxidation statt, die Lösung bleibt blau.","competencies":["S","E"],"operators":["entwickeln","formulieren","begründen"],"sourceLessonId":"chem.experimental.organic-tests","sourceKind":"exercise"},{"id":"chem.experimental.organic-tests.exercise.transfer-formic-acid","title":"Silberspiegel mit Methansäure","difficulty":"transfer","prompt":"Methansäure ist eine Carbonsäure, reagiert aber bei der Silberspiegel-Probe positiv. Erkläre diese Beobachtung mit der Molekülstruktur und formuliere die Reaktionsgleichung für die alkalische Lösung mit dem Methanoat-Ion.","taskType":"free-response","afb":3,"supportedModes":["screen","handwriting"],"hints":["Zeichne die Strukturformel von Methansäure und vergleiche sie mit einem Aldehyd.","In alkalischer Lösung entsteht aus Kohlenstoffdioxid Carbonat."],"solution":"Im Methansäure-Molekül H–COOH ist an das Carbonyl-C ein H-Atom gebunden. Das Molekül enthält damit eine Struktur wie eine Aldehydgruppe und lässt sich weiter oxidieren. Das C-Atom wird von der Oxidationszahl +II auf +IV oxidiert, die Silber-Ionen werden zu Silber reduziert: HCOO⁻ + 2 [Ag(NH₃)₂]⁺ + 3 OH⁻ → CO₃²⁻ + 2 Ag + 4 NH₃ + 2 H₂O.","competencies":["S"],"operators":["erklären","formulieren"],"sourceLessonId":"chem.experimental.organic-tests","sourceKind":"exercise"},{"id":"chem.experimental.organic-tests.selftest.saccharose","title":"Saccharose und Fehling","difficulty":"basic","prompt":"Wie fällt die Fehling-Probe mit Saccharose aus, und warum?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Prüfe, ob eine freie Halbacetalgruppe vorliegt."],"solution":"Negativ. Beide anomeren C-Atome sind an der glycosidischen Bindung beteiligt; es gibt keine freie Halbacetalgruppe und keine offenkettige Form mit Carbonylgruppe.","competencies":["S"],"operators":["angeben","begründen"],"sourceLessonId":"chem.experimental.organic-tests","sourceKind":"selfTest"},{"id":"chem.experimental.organic-tests.selftest.starch","title":"Iod-Stärke beim Erwärmen","difficulty":"basic","prompt":"Was beobachtest du, wenn du eine blau gefärbte Iod-Stärke-Lösung erwärmst und wieder abkühlst? Deute kurz.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die Färbung hängt von der Helixstruktur der Amylose ab."],"solution":"Beim Erwärmen verschwindet die Blaufärbung, beim Abkühlen kehrt sie zurück. Die Amylose-Helix öffnet sich in der Wärme und gibt die eingelagerten Polyiodid-Ionen frei; beim Abkühlen bildet sie sich neu.","competencies":["S","E"],"operators":["beschreiben","deuten"],"sourceLessonId":"chem.experimental.organic-tests","sourceKind":"selfTest"},{"id":"chem.experimental.organic-tests.selftest.biuret","title":"Biuret und Dipeptid","difficulty":"basic","prompt":"Ein Dipeptid ergibt keinen positiven Biuret-Test. Ist der Versuch fehlgeschlagen?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Zähle die Peptidbindungen."],"solution":"Nein. Ein Dipeptid hat nur eine Peptidbindung; für den violetten Komplex sind mindestens zwei Peptidbindungen nötig.","competencies":["S","B"],"operators":["entscheiden","begründen"],"sourceLessonId":"chem.experimental.organic-tests","sourceKind":"selfTest"},{"id":"chem.experimental.separation.exercise.basic-setup","title":"Destillationsapparatur","difficulty":"basic","prompt":"Nenne die Aufgabe von (a) Siedesteinchen, (b) der Thermometerkugel auf Höhe des seitlichen Abgangs und (c) dem Kühlwasser, das unten in den Kühler eintritt.","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Überlege jeweils, welches Problem ohne das Bauteil auftreten würde."],"solution":"(a) Siedesteinchen verhindern einen Siedeverzug und sorgen für gleichmäßiges Sieden. (b) Die Thermometerkugel misst so die Temperatur des Dampfes, der tatsächlich in den Kühler gelangt. (c) Im Gegenstrom ist der Kühler vollständig mit Wasser gefüllt, und das kälteste Wasser kühlt den bereits abgekühlten Dampf am Kühlerende; so wird der Dampf vollständig kondensiert.","competencies":["E"],"operators":["nennen"],"sourceLessonId":"chem.experimental.separation","sourceKind":"exercise","figures":[{"file":"distillation-setup.svg","alt":"Destillationsapparatur: Rundkolben mit Flüssigkeit und Siedesteinchen über einer Heizquelle, darauf ein Aufsatz mit Thermometer, dessen Messfühler auf Höhe des seitlichen Abgangs sitzt. Vom Abgang führt ein schräg nach unten geneigter Liebigkühler zur Vorlage, in die das Destillat tropft. Das Kühlwasser tritt unten am Kühler ein und oben aus.","placement":"solution"}]},{"id":"chem.experimental.separation.exercise.basic-rf","title":"Rf-Wert berechnen","difficulty":"basic","prompt":"Die Laufmittelfront liegt 6,5 cm über der Startlinie, ein Fleck 4,2 cm. Berechne den Rf-Wert. Die Abbildung zeigt die DC-Platte.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Rf = s(Stoff) / s(Front)."],"solution":"Rf = 4,2 cm / 6,5 cm ≈ 0,65.","competencies":["E"],"operators":["berechnen"],"sourceLessonId":"chem.experimental.separation","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"rf","label":"Rf-Wert","value":0.65,"tolerance":{"absolute":0.01}}]},"figures":[{"file":"tlc-rf-measurement.svg","alt":"DC-Platte mit Startlinie und Laufmittelfront. Ein roter Fleck ist 4,2 cm über der Startlinie, die Laufmittelfront 6,5 cm über der Startlinie; beide Strecken sind mit Pfeilen markiert. Ein zweiter, grüner Fleck ist kürzer gewandert.","placement":"prompt"}]},{"id":"chem.experimental.separation.exercise.standard-boiling","title":"Siedetemperaturen erklären","difficulty":"standard","prompt":"Butan (M ≈ 58 g/mol) siedet bei etwa −1 °C, Propanon (M ≈ 58 g/mol) bei 56 °C und Propan-1-ol (M ≈ 60 g/mol) bei 97 °C. Erkläre die Reihenfolge mit den zwischenmolekularen Kräften.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Die molaren Massen sind ähnlich, die Van-der-Waals-Kräfte also vergleichbar.","Prüfe für jeden Stoff, ob Dipole oder Wasserstoffbrücken möglich sind."],"solution":"Bei ähnlicher Molekülgröße unterscheiden sich vor allem die zusätzlichen Kräfte. Butan ist unpolar; zwischen den Molekülen wirken nur Van-der-Waals-Kräfte, daher die niedrigste Siedetemperatur. Propanon besitzt eine polare Carbonylgruppe; zusätzlich wirken Dipol-Dipol-Kräfte. Propan-1-ol besitzt eine Hydroxygruppe und bildet Wasserstoffbrücken, die stärksten der drei zwischenmolekularen Kräfte; es siedet am höchsten.","competencies":["S"],"operators":["erklären"],"sourceLessonId":"chem.experimental.separation","sourceKind":"exercise"},{"id":"chem.experimental.separation.exercise.standard-melting","title":"Schmelzbereich beurteilen","difficulty":"standard","prompt":"Für den reinen Stoff X gibt die Literatur eine Schmelztemperatur von 122 °C an. Ein im Labor hergestelltes Produkt schmilzt zwischen 114 °C und 119 °C. Beurteile die Reinheit des Produkts und schlage eine Maßnahme vor.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Vergleiche Lage und Breite des Schmelzbereichs mit dem Literaturwert."],"solution":"Der Schmelzbereich liegt deutlich unter dem Literaturwert und ist mit 5 K breit. Beides spricht für ein verunreinigtes Produkt. Man kann es reinigen, zum Beispiel durch Umkristallisieren, und den Schmelzbereich erneut bestimmen. Ein enger Schmelzbereich nahe 122 °C spräche dann für ein reines Produkt.","competencies":["E","B"],"operators":["beurteilen"],"sourceLessonId":"chem.experimental.separation","sourceKind":"exercise"},{"id":"chem.experimental.separation.exercise.transfer-equilibrium","title":"Ester abdestillieren?","difficulty":"transfer","prompt":"Ethansäure (Siedetemperatur 118 °C) und Ethanol (78 °C) reagieren im Gleichgewicht zu Ethylethanoat (77 °C) und Wasser (100 °C). Jemand schlägt vor, die Ausbeute zu erhöhen, indem man den Ester während der Reaktion abdestilliert. Prüfe diesen Vorschlag.","taskType":"free-response","afb":3,"supportedModes":["screen"],"hints":["Wende das Prinzip von Le Chatelier an.","Vergleiche die Siedetemperatur des Esters mit denen der anderen Stoffe."],"solution":"Prinzipiell ist der Vorschlag sinnvoll: Entfernt man ein Produkt, sinkt seine Konzentration, und das Gleichgewicht verschiebt sich nach Le Chatelier zu den Produkten. Der Ester ist auch der am niedrigsten siedende Stoff. Seine Siedetemperatur liegt aber nur etwa 1 K unter der von Ethanol. Beim Abdestillieren geht daher auch das Edukt Ethanol über, was dem gewünschten Effekt entgegenwirkt. Eine wirksame Umsetzung erfordert eine fraktionierte Destillation oder einen Ethanol-Überschuss.","competencies":["S","B"],"operators":["prüfen","begründen"],"sourceLessonId":"chem.experimental.separation","sourceKind":"exercise"},{"id":"chem.experimental.separation.exercise.transfer-tlc","title":"Aminosäuren per DC vergleichen","difficulty":"transfer","prompt":"Ein Gemisch aus Aminosäuren soll per Dünnschichtchromatografie untersucht werden. Begründe drei Arbeitsschritte: Startlinie mit Bleistift, Startlinie oberhalb des Laufmittelspiegels, Referenzsubstanzen auf derselben Platte. Erläutere außerdem, wie die farblosen Aminosäuren sichtbar werden.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Tinte enthält selbst Farbstoffe.","Rf-Werte hängen von den Bedingungen ab."],"solution":"Bleistift-Graphit wandert nicht mit, Tintenfarbstoffe würden mitlaufen und das Chromatogramm stören. Läge die Startlinie unter dem Laufmittelspiegel, würden sich die Proben im Laufmittel der Kammer lösen statt in der Schicht aufzusteigen. Referenzsubstanzen auf derselben Platte erleben dieselben Bedingungen; nur so sind Rf-Werte direkt vergleichbar. Zum Sichtbarmachen besprüht man die getrocknete Platte mit Ninhydrin-Lösung und erwärmt; die Aminosäuren erscheinen meist als violette Flecken.","competencies":["E"],"operators":["begründen","erläutern"],"sourceLessonId":"chem.experimental.separation","sourceKind":"exercise"},{"id":"chem.experimental.separation.selftest.thermometer","title":"Thermometerposition","difficulty":"basic","prompt":"Warum taucht das Thermometer bei einer Destillation nicht in die siedende Flüssigkeit ein?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Gesucht ist die Temperatur dessen, was destilliert."],"solution":"Gemessen werden soll die Temperatur des Dampfes, der in den Kühler gelangt. Sie zeigt an, welcher Stoff gerade übergeht; die Flüssigkeit im Kolben kann heißer sein.","competencies":["E"],"operators":["begründen"],"sourceLessonId":"chem.experimental.separation","sourceKind":"selfTest"},{"id":"chem.experimental.separation.selftest.fractions","title":"Erdölfraktionen","difficulty":"basic","prompt":"Ist eine Erdölfraktion wie Benzin ein Reinstoff?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Fraktionen werden nach Siedebereichen aufgefangen."],"solution":"Nein. Eine Fraktion ist ein Gemisch vieler Stoffe mit ähnlichen Siedetemperaturen in einem bestimmten Siedebereich.","competencies":["S"],"operators":["entscheiden"],"sourceLessonId":"chem.experimental.separation","sourceKind":"selfTest"},{"id":"chem.experimental.separation.selftest.rf-range","title":"Rf-Wert über 1?","difficulty":"basic","prompt":"Eine Auswertung ergibt Rf = 1,2. Was ist falsch gelaufen?","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Kein Stoff kann weiter wandern als das Laufmittel."],"solution":"Ein Rf-Wert kann höchstens 1 sein. Vermutlich wurden die Strecken vertauscht oder nicht beide von der Startlinie aus gemessen.","competencies":["E"],"operators":["überprüfen"],"sourceLessonId":"chem.experimental.separation","sourceKind":"selfTest"},{"id":"chem.experimental.quantitative.exercise.basic-naoh","title":"Natronlauge titrieren","difficulty":"basic","prompt":"20,00 mL Natronlauge werden mit Salzsäure der Konzentration 0,200 mol·L⁻¹ titriert. Bis zum Äquivalenzpunkt werden 15,00 mL verbraucht. Berechne die Konzentration der Natronlauge. Die Abbildung zeigt den Versuchsaufbau.","taskType":"numeric","afb":1,"supportedModes":["screen","handwriting"],"hints":["Oxonium- und Hydroxid-Ionen reagieren im Verhältnis 1 : 1.","Rechne die Volumina in Liter um."],"solution":"n(H₃O⁺) = 0,200 mol·L⁻¹ · 0,01500 L = 3,000 · 10⁻³ mol. Wegen H₃O⁺ + OH⁻ → 2 H₂O gilt n(OH⁻) = 3,000 · 10⁻³ mol. c(NaOH) = 3,000 · 10⁻³ mol / 0,02000 L = 0,150 mol·L⁻¹.","competencies":["S"],"operators":["berechnen"],"sourceLessonId":"chem.experimental.quantitative","sourceKind":"exercise","answer":{"kind":"numeric","parts":[{"id":"c","label":"c(NaOH)","value":0.15,"unit":"mol·L⁻¹"}]},"figures":[{"file":"titration-setup.svg","alt":"Titrationsaufbau: Am Stativ hängt eine Bürette mit Maßlösung bekannter Konzentration und einem Hahn. Darunter steht auf einem Magnetrührer ein Erlenmeyerkolben mit Probelösung und Indikator. Abgelesen werden Anfangs- und Endstand der Bürette.","placement":"prompt"}]},{"id":"chem.experimental.quantitative.exercise.basic-indicator","title":"Indikator auswählen","difficulty":"basic","prompt":"Ethansäure-Lösung soll mit Natronlauge titriert werden. Zur Auswahl stehen Methylorange (Umschlagsbereich pH 3,1 bis 4,4) und Phenolphthalein (pH 8,2 bis 10). Begründe, welcher Indikator geeignet ist.","taskType":"free-response","afb":2,"supportedModes":["screen"],"hints":["Überlege, in welchem pH-Bereich der Äquivalenzpunkt bei einer schwachen Säure liegt."],"solution":"Am Äquivalenzpunkt liegt eine Natriumethanoat-Lösung vor. Die Ethanoat-Ionen reagieren als schwache Base mit Wasser, der pH-Wert liegt im alkalischen Bereich. Der Umschlagsbereich von Phenolphthalein liegt im steilen Teil der Kurve um diesen Punkt; Phenolphthalein ist geeignet. Methylorange würde schon weit vor dem Äquivalenzpunkt umschlagen.","competencies":["S","E"],"operators":["begründen"],"sourceLessonId":"chem.experimental.quantitative","sourceKind":"exercise"},{"id":"chem.experimental.quantitative.exercise.standard-sulfur-dioxide","title":"Schwefeldioxid im Wein","difficulty":"standard","prompt":"50,0 mL Weißwein werden nach Zusatz von Stärke-Lösung mit Iod-Lösung (c = 0,0100 mol·L⁻¹) bis zur bleibenden Blaufärbung titriert. Verbrauch: 7,50 mL. Berechne die Massenkonzentration an Schwefeldioxid in mg·L⁻¹ (M(SO₂) = 64,07 g·mol⁻¹) und erläutere die Rolle der Stärke.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["SO₂ + I₂ + 2 H₂O → SO₄²⁻ + 2 I⁻ + 4 H⁺","Rechne zuerst die Masse in 50,0 mL aus und dann auf einen Liter um."],"solution":"n(I₂) = 0,0100 mol·L⁻¹ · 0,00750 L = 7,50 · 10⁻⁵ mol = n(SO₂). m(SO₂) = 7,50 · 10⁻⁵ mol · 64,07 g·mol⁻¹ ≈ 4,81 · 10⁻³ g = 4,81 mg in 50,0 mL. β(SO₂) = 4,81 mg / 0,0500 L ≈ 96 mg·L⁻¹. Solange Schwefeldioxid vorhanden ist, wird das zugetropfte Iod sofort reduziert. Erst nach dem Äquivalenzpunkt bleibt freies Iod übrig und färbt die Stärke blau.","competencies":["S","E"],"operators":["berechnen","erläutern"],"sourceLessonId":"chem.experimental.quantitative","sourceKind":"exercise"},{"id":"chem.experimental.quantitative.exercise.standard-permanganate","title":"Eisen(II)-Ionen mit Permanganat","difficulty":"standard","prompt":"25,00 mL einer Eisen(II)-sulfat-Lösung werden angesäuert und mit Kaliumpermanganat-Lösung (c = 0,0200 mol·L⁻¹) titriert. Verbrauch: 18,00 mL. Berechne c(Fe²⁺) und beschreibe, woran man den Endpunkt erkennt.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["MnO₄⁻ + 5 Fe²⁺ + 8 H⁺ → Mn²⁺ + 5 Fe³⁺ + 4 H₂O","Kaliumpermanganat-Lösung ist intensiv violett."],"solution":"n(MnO₄⁻) = 0,0200 mol·L⁻¹ · 0,01800 L = 3,60 · 10⁻⁴ mol. n(Fe²⁺) = 5 · 3,60 · 10⁻⁴ mol = 1,80 · 10⁻³ mol. c(Fe²⁺) = 1,80 · 10⁻³ mol / 0,02500 L = 0,0720 mol·L⁻¹. Solange Fe²⁺ vorliegt, wird das violette Permanganat zu fast farblosem Mn²⁺ reduziert. Der Endpunkt ist erreicht, wenn eine schwache Rosafärbung bestehen bleibt.","competencies":["S","E"],"operators":["berechnen","beschreiben"],"sourceLessonId":"chem.experimental.quantitative","sourceKind":"exercise"},{"id":"chem.experimental.quantitative.exercise.transfer-iodine-value","title":"Zwei Öle vergleichen","difficulty":"transfer","prompt":"Bei der Iodzahl-Bestimmung von Öl A (m = 0,200 g) werden 17,10 mL Thiosulfat-Lösung (c = 0,100 mol·L⁻¹) verbraucht, beim Blindwert 25,00 mL. Öl B hat die Iodzahl 120. Berechne die Iodzahl von Öl A und vergleiche die beiden Öle hinsichtlich ihrer Fettsäure-Reste.","taskType":"structured","afb":2,"supportedModes":["screen","handwriting"],"hints":["IZ = (V_Blind − V_Probe) · c(S₂O₃²⁻) · ½ · M(I₂) · 100 / m(Fett) mit M(I₂) = 253,8 g·mol⁻¹.","Die Iodzahl ist ein Maß für C=C-Doppelbindungen."],"solution":"ΔV = 25,00 mL − 17,10 mL = 7,90 mL. n(S₂O₃²⁻) = 7,90 · 10⁻⁴ mol, n(I₂) = 3,95 · 10⁻⁴ mol, m(I₂) = 3,95 · 10⁻⁴ mol · 253,8 g·mol⁻¹ ≈ 0,100 g. IZ = 0,100 g / 0,200 g · 100 ≈ 50. Öl B bindet pro 100 g mehr als doppelt so viel Iod; es enthält deutlich mehr C=C-Doppelbindungen, also einen höheren Anteil ungesättigter Fettsäure-Reste.","competencies":["S","E"],"operators":["berechnen","vergleichen"],"sourceLessonId":"chem.experimental.quantitative","sourceKind":"exercise"},{"id":"chem.experimental.quantitative.exercise.transfer-errors","title":"Auswirkung von Fehlern","difficulty":"transfer","prompt":"Bei einer Säure-Base-Titration passieren folgende Fehler: (a) Die Bürette wurde nur mit Wasser gespült und dann mit Maßlösung gefüllt. (b) Der Farbumschlag wird um mehrere Tropfen überschritten. (c) Eine Luftblase in der Bürettenspitze entweicht während der Titration. Beurteile jeweils, ob die berechnete Konzentration der Probe zu hoch oder zu niedrig ausfällt.","taskType":"structured","afb":3,"supportedModes":["screen"],"hints":["Überlege jeweils, ob das abgelesene Volumen größer oder kleiner ist als das Volumen, das tatsächlich reagiert hat.","Ein größeres Volumen der Maßlösung führt bei der Berechnung zu einer größeren Stoffmenge."],"solution":"(a) Restwasser verdünnt die Maßlösung; es wird mehr Volumen verbraucht, die berechnete Konzentration ist zu hoch. (b) Es wird mehr Maßlösung abgelesen als bis zum Äquivalenzpunkt nötig; das Ergebnis ist zu hoch. (c) Das Volumen der entweichenden Luftblase wird als verbrauchte Maßlösung abgelesen, obwohl es keine Lösung war; das Ergebnis ist zu hoch. Alle drei sind systematische Fehler.","competencies":["E","B"],"operators":["beurteilen"],"sourceLessonId":"chem.experimental.quantitative","sourceKind":"exercise"},{"id":"chem.experimental.quantitative.selftest.equivalence","title":"Äquivalenzpunkt und Endpunkt","difficulty":"basic","prompt":"Worin unterscheiden sich Äquivalenzpunkt und Endpunkt einer Titration?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Einer ist durch die Stöchiometrie festgelegt, der andere durch eine Anzeige."],"solution":"Am Äquivalenzpunkt haben die Stoffe genau im stöchiometrischen Verhältnis reagiert. Der Endpunkt ist der Punkt, an dem man aufgrund eines Farbumschlags oder einer Messung aufhört; er soll möglichst mit dem Äquivalenzpunkt übereinstimmen.","competencies":["S"],"operators":["unterscheiden"],"sourceLessonId":"chem.experimental.quantitative","sourceKind":"selfTest"},{"id":"chem.experimental.quantitative.selftest.starch","title":"Stärke als Indikator","difficulty":"basic","prompt":"Wozu setzt man bei Titrationen mit Iod Stärke-Lösung zu?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Denke an die Iod-Stärke-Reaktion."],"solution":"Stärke zeigt freies Iod durch eine Blaufärbung an. So erkennt man genau, wann Iod im Überschuss vorliegt oder vollständig verbraucht ist.","competencies":["E"],"operators":["angeben"],"sourceLessonId":"chem.experimental.quantitative","sourceKind":"selfTest"},{"id":"chem.experimental.quantitative.selftest.blank","title":"Blindwert","difficulty":"basic","prompt":"Welche Information liefert der Blindwert bei einer Rücktitration?","taskType":"free-response","afb":1,"supportedModes":["screen"],"hints":["Der Ansatz enthält alles außer der Probe."],"solution":"Er gibt an, wie viel Maßlösung der gesamten eingesetzten Reagenzmenge entspricht. Die Differenz zum Verbrauch der Probe entspricht der Menge, die mit der Probe reagiert hat.","competencies":["E"],"operators":["angeben"],"sourceLessonId":"chem.experimental.quantitative","sourceKind":"selfTest"}]'),i={schemaVersion:1,exercises:e};export{i as default,e as exercises,n as schemaVersion};
